const T1_ASSESS = {"1-1":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح تطور تكنولوجيا المعلومات في الفترة الممتدة من الأربعينيات إلى الستينيات موضحًا استخدامها الأساسي في تلك الفترة؟","a":"شهدت الفترة من الأربعينيات إلى الستينيات ظهور الحواسيب الإلكترونية، ومنها ENIAC، واستخدام الصمامات المفرغة. واستخدمت أساسا للأغراض العسكرية والحسابات العلمية."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح المقصود ب«قانون مور» وهل يعد قانونًا فيزيائيًا ثابتا؟ فسر إجابتك.","a":"قانون مور يصف اتجاها تاريخيا لازدياد عدد الترانزستورات في الدوائر المتكاملة بمعدل يقارب الضعف كل عامين، وهو ليس قانونًا فيزيائيًا ثابتا. ويواجه استمرار تصغير مكونات الدوائر تحديات هندسية وفيزيائية، منها ازدياد تيارات التسرب وتأثيرات كمومية مثل النفق الكمومي."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات التالية يمثل التقنية أو الحدث الرئيسي المرتبط بفترة السبعينيات والثمانينيات من القرن الماضي؟","a":"(ب) انتشار الحواسيب الشخصية (PCs)","mcq":{"stem":"أي من الخيارات التالية يمثل التقنية أو الحدث الرئيسي المرتبط بفترة السبعينيات والثمانينيات من القرن الماضي؟","opts":["ظهور الهواتف الذكية","انتشار الحواسيب الشخصية (PCs)","انتشار الحوسبة السحابية","إتاحة الإنترنت للاستخدام التجاري وظهور الويب"],"correct":1}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي الملاحظة التجريبية التي تصف اتجاها تاريخيا لازدياد عدد الترانزستورات في الدوائر المتكاملة بمعدل يقارب الضعف كل عامين؟","a":"(ب) قانون مور","mcq":{"stem":"ما هي الملاحظة التجريبية التي تصف اتجاها تاريخيا لازدياد عدد الترانزستورات في الدوائر المتكاملة بمعدل يقارب الضعف كل عامين؟","opts":["الحوسبة السحابية","قانون مور","الحوسبة الطرفية","التراكب الكمي"],"correct":1}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر ثلاث تغيرات اجتماعية ناتجة عن تكنولوجيا المعلومات؟","a":"-١ شبكات التواصل الاجتماعي (SNS) -٢ التجارة الإلكترونية (E-commerce) -٣ العمل عن بُعد (Remote Work)."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما المقصود بمصطلح «التجارة الإلكترونية (E-commerce)»؟ موضحًا ذلك بمثالين.","a":"التجارة الإلكترونية: بيع السلع والخدمات وشراؤها عبر الإنترنت. مثالان من الكتاب: متاجر إلكترونية مثل أمازون وإيباي."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يشير إلى نمط عمل يؤدي فيه الشخص مهامه من المنزل أو من موقع آخر بعيد باستخدام الإنترنت؟","a":"(ج) العمل عن بعد (Remote Work)","mcq":{"stem":"ما هو المصطلح الذي يشير إلى نمط عمل يؤدي فيه الشخص مهامه من المنزل أو من موقع آخر بعيد باستخدام الإنترنت؟","opts":["التعلم عبر الإنترنت","التجارة الإلكترونية","العمل عن بعد (Remote Work)","الدفع غير النقدي"],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما المقصود بخدمة «شبكات التواصل الاجتماعي (SNS)»؟","a":"(أ) منصات تتيح للمستخدمين التواصل ونشر المحتوى ومشاركته بسرعة.","mcq":{"stem":"ما المقصود بخدمة «شبكات التواصل الاجتماعي (SNS)»؟","opts":["منصات تتيح للمستخدمين التواصل ونشر المحتوى ومشاركته بسرعة.","بيع السلع والخدمات وشرائها عبر الإنترنت.","دفع قيمة السلع أو الخدمات بوسائل غير نقدية.","نمط تعليمي تُقدَّم فيه الدروس عبر الإنترنت."],"correct":0}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح كيف تساهم «الحوسبة الطرفية» في تعزيز الأمان وسرعة اتخاذ القرار في تقنية القيادة الذاتية دون الحاجة لإرسال البيانات إلى السحابة؟","a":"الحوسبة الطرفية هي معالجة البيانات على الجهاز نفسه فورًا بدلًا من إرسالها إلى السحابة.وتستخدم المركبة ذاتية القيادة كاميرات ومستشعرات لإدراك محيطها، ثم يعالج النظام البيانات لاتخاذ قرارات القيادة والتحكم فيها.وتعالج بعض البيانات محليًا بالحوسبة الطرفية لتقليل زمن الاستجابة؛ لأن التأخير في معالجة بيانات القيادة قد يؤثر في السلامة."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"قارن بإيجاز بين «الواقع المعزز (AR)» و«الواقع الافتراضي (VR)» من حيث التعريف وطريقة العمل؟","a":"الواقع المعزز (AR): تقنية تضيف عناصر أو معلومات رقمية إلى مشهد من العالم الحقيقي. الواقع الافتراضي (VR): تقنية تضع المستخدم داخل بيئة افتراضية مولدة حاسوبيًا. يضيف الواقع المعزز عناصر رقمية إلى العالم الحقيقي، بينما يضع الواقع الافتراضي المستخدم داخل بيئة رقمية كاملة."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي التقنية التي تقضي بمعالجة البيانات على الجهاز نفسه فورًا بدلًا من إرسالها إلى السحابة لتجنب التأخير في اتخاذ القرار؟","a":"(ج) الحوسبة الطرفية.","mcq":{"stem":"ما هي التقنية التي تقضي بمعالجة البيانات على الجهاز نفسه فورًا بدلًا من إرسالها إلى السحابة لتجنب التأخير في اتخاذ القرار؟","opts":["الحوسبة السحابية.","الحوسبة الكمومية.","الحوسبة الطرفية.","شبكات التواصل الاجتماعي."],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات الآتية يمثل المفهوم الدقيق لتقنية «الواقع المعزز (AR)»؟","a":"(ب) تقنية تضيف عناصر أو معلومات رقمية إلى مشهد من العالم الحقيقي.","mcq":{"stem":"أي من الخيارات الآتية يمثل المفهوم الدقيق لتقنية «الواقع المعزز (AR)»؟","opts":["تقنية تضع المستخدم داخل بيئة افتراضية مولدة حاسوبيا بالكامل.","تقنية تضيف عناصر أو معلومات رقمية إلى مشهد من العالم الحقيقي.","نهج حوسبي يستخدم خصائص ميكانيكا الكم لمعالجة المعلومات.","نظام لإجراء المدفوعات بالنقود الإلكترونية ورموز QR."],"correct":1}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح المبدأ الذي يقوم عليه «الكيوبت (qubit)» في الحوسبة الكمومية وكيف يختلف عن «البت الكلاسيكي»؟","a":"يحمل البت التقليدي حالة واحدة (0 أو 1)، أما الكيوبت (qubit) فيستخدم مبدأ التراكب الكمومي (0 و1) معا. والحوسبة الكمومية نهج حوسبي يستخدم خصائص ميكانيكا الكم لمعالجة المعلومات."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"كيف غير انتشار الحوسبة السحابية من العقد الثاني من الألفية فصاعدًا طريقة تقديم موارد تكنولوجيا المعلومات؟","a":"أدى انتشار الحوسبة السحابية من العقد الثاني من الألفية فصاعدًا إلى تقديم موارد تكنولوجيا المعلومات في صورة خدمات عبر الإنترنت، ودعم تحليل البيانات الضخمة والذكاء الاصطناعي."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما الذي يميز «الكيوبت (qubit)» عن «البت الكلاسيكي» في الحوسبة الكمومية؟","a":"(ب) يستخدم مبدأ التراكب الكمي ليكون مزيجا من 0 و1 في نفس الوقت.","mcq":{"stem":"ما الذي يميز «الكيوبت (qubit)» عن «البت الكلاسيكي» في الحوسبة الكمومية؟","opts":["يحمل حالة محددة واحدة إما 0 أو 1 في كل وقت.","يستخدم مبدأ التراكب الكمي ليكون مزيجا من 0 و1 في نفس الوقت.","يعتمد فقط على الدوائر المتكاملة التقليدية وثبات التيار الكهربائي.","يقتصر استخدامه حصريا على الحسابات البسيطة."],"correct":1}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما المقصود بمصطلح «الدفع غير النقدي (Cashless Payment)»؟","a":"(ب) دفع قيمة السلع أو الخدمات بوسائل غير نقدية مثل البطاقات أو تطبيقات الهاتف أو رموز QR","mcq":{"stem":"ما المقصود بمصطلح «الدفع غير النقدي (Cashless Payment)»؟","opts":["بيع السلع والخدمات وشراؤها عبر المتاجر الفعلية باستخدام النقد الورقي.","دفع قيمة السلع أو الخدمات بوسائل غير نقدية مثل البطاقات أو تطبيقات الهاتف أو رموز QR","العمل من المنزل باستخدام الإنترنت والبريد الإلكتروني.","تقديم الدروس والمواد التعليمية عبر الإنترنت للمستخدمين."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح المراحل التاريخية لتطور تكنولوجيا المعلومات منذ ظهور الحواسيب الإلكترونية في الأربعينيات وحتى الستينيات مبينًا الغرض الأساسي استخدامها في تلك الفترة.","a":"أساسا شهدت الفترة من الأربعينيات إلى الستينيات ظهور الحواسيب الإلكترونية، ومنها حاسوب، ENIAC واستخدام الصمامات المفرغة.واستخدمت للأغراض العسكرية والحسابات العلمية."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح «قانون مور» موضحًا ما يصفه، والتحديات الهندسية والفيزيائية التي تواجه استمرار تصغير مكونات الدوائر.","a":"قانون مور يصف اتجاها تاريخيا لازدياد عدد الترانزستورات في الدوائر المتكاملة بمعدل يقارب الضعف كل عامين، وليس قانونًا فيزيائيًا ثابتا.وقد أسهم هذا الاتجاه في زيادة قدرات الحوسبة وتحسين أداء المعالجات، لكن استمرار تصغير مكونات الدوائر يواجه تحديات هندسية وفيزيائية، منها ازدياد تيارات التسرب وتأثيرات كمومية مثل النفق الكمومي.لذلك يعتمد تحسين الأداء أيضا على تعدد الأنوية والمعالجة المتوازية وتصميمات متخصصة."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"عدد التحولات المجتمعية الخمسة الناتجة عن تكنولوجيا المعلومات، موضحًا مفهوم كل من «العمل عن بعد» و«التجارة الإلكترونية»","a":"التحولات الخمسة: شبكات التواصل الاجتماعي، والتجارة الإلكترونية والعمل عن بعد، والتعلم عبر الإنترنت، والدفع غير النقدي. العمل عن بعد: نمط عمل يؤدي فيه الشخص مهامه من المنزل أو من موقع آخر بعيد باستخدام الإنترنت. التجارة الإلكترونية: بيع السلع والخدمات وشراؤها عبر الإنترنت."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح خصائص واستخدامات التقنيات الناشئة الثلاث البارزة المذكورة في الدرس (القيادة الذاتية، الواقع المعزز/ الافتراضي، والحوسبة الكمومية)","a":"-١ القيادة الذاتية: تقنية تستخدم الذكاء الاصطناعي للمساعدة على قيادة المركبة، وتستخدم كاميرات ومستشعرات لإدراك محيطها واتخاذ قرارات القيادة، مع معالجة بعض البيانات محليًا لتقليل زمن الاستجابة. -٢ الواقع المعزز/ الافتراضي: الواقع المعزز يضيف عناصر أو معلومات رقمية إلى مشهد من العالم الحقيقي؛ والواقع الافتراضي يضع المستخدم داخل بيئة افتراضية مولدة حاسوبيا. -٣ الحوسبة الكمومية: نهج حوسبي يستخدم خصائص ميكانيكا الكم لمعالجة المعلومات، وقد يوفر تفوقا في فئات محددة من المسائل، لكنه لا يسرع جميع أنواع الحسابات."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"في أي فترة زمنية بدأت إتاحة الإنترنت للاستخدام التجاري وظهر الويب مما توسع معه الوصول العالمي إلى المعلومات؟","a":"(ب) التسعينيات.","mcq":{"stem":"في أي فترة زمنية بدأت إتاحة الإنترنت للاستخدام التجاري وظهر الويب مما توسع معه الوصول العالمي إلى المعلومات؟","opts":["الأربعينيات والستينيات.","التسعينيات.","السبعينيات والثمانينيات.","من العقد الثاني من الألفية فصاعداً."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي التقنية التي تستخدم الذكاء الاصطناعي للمساعدة على قيادة المركبة باستخدام الكاميرات والمستشعرات لإدراك المحيط واتخاذ القرار؟","a":"(ب) القيادة الذاتية.","mcq":{"stem":"ما هي التقنية التي تستخدم الذكاء الاصطناعي للمساعدة على قيادة المركبة باستخدام الكاميرات والمستشعرات لإدراك المحيط واتخاذ القرار؟","opts":["الحوسبة السحابية.","القيادة الذاتية.","الواقع الافتراضي.","الحوسبة الكمومية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما المصطلح الذي يعبر عن تكنولوجيا المعلومات المقدمة كخدمة عبر الإنترنت لدعم تحليل البيانات الضخمة والذكاء الاصطناعي؟","a":"(أ) الحوسبة السحابية.","mcq":{"stem":"ما المصطلح الذي يعبر عن تكنولوجيا المعلومات المقدمة كخدمة عبر الإنترنت لدعم تحليل البيانات الضخمة والذكاء الاصطناعي؟","opts":["الحوسبة السحابية.","الحوسبة الطرفية.","البت الكلاسيكي.","التراكب الكمي."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الآتي يعد الوصف الصحيح لمفهوم «الواقع الافتراضي (VR)»؟","a":"(ب) تقنية تضع المستخدم داخل بيئة افتراضية مولدة حاسوبيا.","mcq":{"stem":"أي من الآتي يعد الوصف الصحيح لمفهوم «الواقع الافتراضي (VR)»؟","opts":["تقنية تضيف معلومات رقمية فوق صور من العالم الحقيقي.","تقنية تضع المستخدم داخل بيئة افتراضية مولدة حاسوبيا.","تقنية لمعالجة البيانات على الجهاز نفسه فورًا دون السحابة.","نظام لإجراء المدفوعات بالنقود الإلكترونية ورموز QR."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح كيف أثر ظهور الحواسيب الشخصية (PCs) وانتشار الوصول العالمي إلى المعلومات والبريد الإلكتروني على المجتمع في فترة السبعينيات والثمانينيات.","a":"السبعينيات والثمانينيات: انتشار الحواسيب الشخصية PCs مما أدى إلى بداية استخدام الأفراد للحاسب. التسعينيات: إتاحة الإنترنت للاستخدام التجاري وظهور الويب، مما أدى إلى انتشار الوصول العالمي إلى المعلومات والبريد الإلكتروني."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح كيف يؤدي استمرار تصغير مكونات الدوائر في قانون مور إلى ظهور تحديات هندسية وفيزيائية مثل تيارات التسرب والتأثيرات الكمومية والنفق الكمومي.","a":"مع استمرار تصغير الترانزستورات ومكونات الدوائر المتكاملة وفق الاتجاه الذي يصفه قانون مور، تظهر تحديات هندسية وفيزيائية: منها تيارات التسرب: تزداد مع استمرار تصغير المكونات (حتى في الحالات التي المفروض الترانزستور يمنع فيها مروره). التأثيرات الكمومية: تظهر عند الأحجام شديدة الصغر، ومنها ظاهرة النفق الكمومي. وتجعل هذه التحديات الاستمرار في تصغير المكونات أكثر صعوبة، ولذلك يعتمد تحسين أداء المعالجات أيضا على تعدد الأنوية والمعالجة المتوازية والتصميمات المتخصصة."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح باختصار مفهوم كل من «شبكات التواصل الاجتماعي (SNS)» و«التعلم عبر الإنترنت» و«الدفع غير النقدي» باعتبارها تحولات مجتمعية.","a":"شبكات التواصل الاجتماعي (SNS): منصات تتيح للمستخدمين التواصل ونشر المحتوى ومشاركته بسرعة. التعلم عبر الإنترنت: نمط تعليمي تقدم فيه الدروس والمواد التعليمية عبر الإنترنت. الدفع غير النقدي: دفع قيمة السلع أو الخدمات بوسائل غير نقدية، مثل البطاقات المصرفية أو تطبيقات الهاتف أو رموز QR."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح كيف تعالج الحوسبة الطرفية البيانات محليًا على متن المركبة ذاتية القيادة فورًا لتقليل زمن الاستجابة وضمان السلامة.","a":"تستخدم المركبة كاميرات ومستشعرات لإدراك محيطها، ثم يعالج النظام البيانات لاتخاذ قرارات القيادة والتحكم فيها.ولأن التأخير في معالجة بيانات القيادة قد يؤثر في السلامة، تعالج بعض البيانات محليًا على المركبة بالحوسبة الطرفية لتقليل زمن الاستجابة دون انتظار السحابة."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"الفترة الزمنية التي شهدت ظهور الهواتف الذكية وانتشار الإنترنت عبر الهواتف المحمولة بسرعة هي:","a":"(ب) العقد الأول من الألفية.","mcq":{"stem":"الفترة الزمنية التي شهدت ظهور الهواتف الذكية وانتشار الإنترنت عبر الهواتف المحمولة بسرعة هي:","opts":["السبعينيات والستينيات.","العقد الأول من الألفية.","التسعينيات.","الأربعينيات من القرن العشرين."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"تقنية تضيف عناصر أو معلومات رقمية إلى مشهد من العالم الحقيقي تعرف باسم:","a":"(ج) الواقع المعزز (AR)","mcq":{"stem":"تقنية تضيف عناصر أو معلومات رقمية إلى مشهد من العالم الحقيقي تعرف باسم:","opts":["الواقع الافتراضي (VR).","القيادة الذاتية.","الواقع المعزز (AR)","الحوسبة الكمومية."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي الملاحظات الآتية تصف بدقة ما يفعله «قانون مور»؟","a":"(أ) تضاعف عدد الترانزستورات في الدائرة المتكاملة تقريبًا كل عامين.","mcq":{"stem":"أي الملاحظات الآتية تصف بدقة ما يفعله «قانون مور»؟","opts":["تضاعف عدد الترانزستورات في الدائرة المتكاملة تقريبًا كل عامين.","ثبات عدد الترانزستورات وعدم تغيرها عبر الزمن نهائيًا.","زيادة استهلاك الطاقة في الحواسيب التقليدية بمقدار الضعف سنوياً.","انخفاض قدرات الحوسبة ومعالجة البيانات مع مرور السنوات."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"نمط تعليمي وتدريبي تقدم فيه الدروس والمواد التعليمية حصريًا أو جزئيًا عبر شبكة الإنترنت هو:","a":"(ج) التعلم عبر الإنترنت (Online Learning).","mcq":{"stem":"نمط تعليمي وتدريبي تقدم فيه الدروس والمواد التعليمية حصريًا أو جزئيًا عبر شبكة الإنترنت هو:","opts":["التجارة الإلكترونية.","العمل عن بعد.","التعلم عبر الإنترنت (Online Learning).","الدفع غير النقدي."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"ناقش أثر ظهور الويب وانتشار الإنترنت في تسعينيات القرن العشرين على إتاحة المعلومات للاستخدام التجاري والعالمي.","a":"في التسعينيات أتيح الإنترنت للاستخدام التجاري وظهر الويب، وكان التأثير على المجتمع انتشار الوصول العالمي إلى المعلومات والبريد الإلكتروني."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح كيف تعد القيادة الذاتية من ضمن التقنيات الناشئة البارزة.","a":"القيادة الذاتية تقنية تستخدم الذكاء الاصطناعي للمساعدة على قيادة المركبة.وتستخدم المركبة كاميرات ومستشعرات لإدراك محيطها، ثم يعالج النظام البيانات لاتخاذ قرارات القيادة والتحكم فيها.وتعالج بعض البيانات محليًا بالحوسبة الطرفية لتقليل زمن الاستجابة، لأن التأخير قد يؤثر في السلامة."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح مفهوم كل من التجارة الإلكترونية والدفع غير النقدي.","a":"التجارة الإلكترونية: بيع السلع والخدمات وشراؤها عبر الإنترنت. الدفع غير النقدي: دفع قيمة السلع أو الخدمات بوسائل غير نقدية، مثل البطاقات المصرفية أو تطبيقات الهاتف أو رموز QR."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح الفروق الجوهرية بين «البت الكلاسيكي» و«الكيوبت (qubit)» مستخدمًا مفهوم «التراكب الكمي» في الحوسبة الكمومية.","a":"يحمل البت التقليدي حالة واحدة، أما الكيوبت (qubit) فيستخدم مبدأ التراكب الكمومي.والحوسبة الكمومية نهج حوسبي يستخدم خصائص ميكانيكا الكم لمعالجة المعلومات."},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"بدأت الحواسيب الإلكترونية في الظهور واستخدمت باستخدام الصمامات المفرغة في فترة:","a":"(أ) الأربعينيات.","mcq":{"stem":"بدأت الحواسيب الإلكترونية في الظهور واستخدمت باستخدام الصمامات المفرغة في فترة:","opts":["الأربعينيات.","السبعينيات.","التسعينيات.","العقد الأول من الألفية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"مبدأ أو نهج حوسبي يستخدم خصائص ميكانيكا الكم لمعالجة المعلومات وقد يوفر تفوقا في فئات محددة من المسائل هو:","a":"(ب) الحوسبة الكمومية.","mcq":{"stem":"مبدأ أو نهج حوسبي يستخدم خصائص ميكانيكا الكم لمعالجة المعلومات وقد يوفر تفوقا في فئات محددة من المسائل هو:","opts":["الحوسبة الطرفية.","الحوسبة الكمومية.","الدفع غير النقدي.","شبكات التواصل الاجتماعي."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"منصات تتيح للمستخدمين التواصل ونشر المحتوى ومشاركته بسرعة وتعد فعالة جدًا في نشر المعلومات هي:","a":"(أ) شبكات التواصل الاجتماعي (SNS)","mcq":{"stem":"منصات تتيح للمستخدمين التواصل ونشر المحتوى ومشاركته بسرعة وتعد فعالة جدًا في نشر المعلومات هي:","opts":["شبكات التواصل الاجتماعي (SNS)","التجارة الإلكترونية.","العمل عن بعد.","الحوسبة السحابية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"المهام الأدائية","qtype":"موضوعي","q":"أسلوب عمل يؤدي فيه الشخص مهامه ووظائفه من المنزل أو من موقع آخر بعيد باستخدام تقنيات الاتصال والإنترنت يسمى:","a":"(ب) العمل عن بعد (Remote Work)","mcq":{"stem":"أسلوب عمل يؤدي فيه الشخص مهامه ووظائفه من المنزل أو من موقع آخر بعيد باستخدام تقنيات الاتصال والإنترنت يسمى:","opts":["التعلم عبر الإنترنت.","العمل عن بعد (Remote Work)","القيادة الذاتية.","الحوسبة الطرفية."],"correct":1}}],"1-2":[{"period":"الفترة الأولى","kind":null,"qtype":"مقالي","q":"عرف مفهوم الذكاء الاصطناعي، موضحًا في ثلاث نقاط الفرق بين التعلم الآلي والتعلم العميق والذكاء الاصطناعي التوليدي.","a":" الذكاء الاصطناعي (AI): مجال يضم أنظمة حاسوبية تستطيع تنفيذ مهام مثل التعلم من البيانات والتنبؤ والتعرف وتوليد المحتوى واتخاذ القرارات أو دعمها.  التعلم الآلي (ML): فرع من الذكاء الاصطناعي تتعلم فيه النماذج أنماطا من البيانات لإجراء تنبؤات أو تصنيفات أو دعم قرارات بدلًا من برمجة كل قاعدةاعليا صراحة.  التعلم العميق (DL): أسلوب من أساليب التعلم الآلي يعتمد على شبكات عصبية متعددة الطبقات لتعلم تمثيلات وأنماط معقدة.  الذكاء الاصطناعي التوليدي (GenAI): أنظمة تنشئ محتوى جديدا، مثل النصوص والصور والصوت والبرمجيات، اعتمادا على الأنماط التي تعلمتها من بيانات التدريب."},{"period":"الفترة الأولى","kind":null,"qtype":"مقالي","q":"اشرح كيف تتعلم النماذج في فرع «التعلم الآلي» مقارنة بالطرق التقليدية المعتمدة على البرمجة الصريحة للقواعد.","a":"في التعلم الآلي تتعلم النماذج أنماطا من البيانات لإجراء تنبؤات أو تصنيفات أو دعم قرارات بدلًا من برمجة كل قاعدة صراحة، ومن أمثلتها تصنيف الرسائل المزعجة وتوصية المنتجات. أما في البرمجة التقليدية فتعتمد الطريقة على قواعد مبرمجة صراحة."},{"period":"الفترة الأولى","kind":null,"qtype":"موضوعي","q":"أي من الخيارات التالية يمثل المجال الواسع الذي يضم أنظمة حاسوبية تستطيع تنفيذ مهام مثل التعلم والتنبؤ والتعرف على الكلام والصور؟","a":"(ب) الذكاء الاصطناعي.","mcq":{"stem":"أي من الخيارات التالية يمثل المجال الواسع الذي يضم أنظمة حاسوبية تستطيع تنفيذ مهام مثل التعلم والتنبؤ والتعرف على الكلام والصور؟","opts":["التعلم العميق.","الذكاء الاصطناعي.","التعلم الآلي.","الذكاء الاصطناعي التوليدي."],"correct":1}},{"period":"الفترة الأولى","kind":null,"qtype":"موضوعي","q":"ماذا يعد «التعلم الآلي (Machine Learning)» من منظور تسلسل تقنيات الذكاء الاصطناعي؟","a":"(أ) فرع من الذكاء الاصطناعي تتعلم فيه النماذج أنماطًا من البيانات.","mcq":{"stem":"ماذا يعد «التعلم الآلي (Machine Learning)» من منظور تسلسل تقنيات الذكاء الاصطناعي؟","opts":["فرع من الذكاء الاصطناعي تتعلم فيه النماذج أنماطًا من البيانات.","أسلوب يعتمد حصريا على شبكات عصبية غير متصلة.","نظام لتوليد الصور ومقاطع الفيديو حصريا دون بيانات تدريب.","مجموعة من القواعد المبرمجة يدوياً بشكل صارم وثابت."],"correct":0}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما المكونات الأساسية للشبكة العصبية الاصطناعية؟","a":"الشبكة العصبية الاصطناعية نموذج حاسوبي مستوحى بصورة مبسطة من فكرة ترابط العصبونات.تتكون من وحدات مترابطة تتغير أوزانها أثناء التدريب لتتعلم أنماطا من البيانات. مكوناتها: طبقة إدخال، وطبقات مخفية، وطبقة إخراج."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح مفهوم «الذكاء الاصطناعي التوليدي (GenAI)» موضحًا ذلك بأمثلة.","a":"الذكاء الاصطناعي التوليدي: أنظمة تنشئ محتوى جديدا، مثل النصوص والصور والصوت والبرمجيات، اعتمادا على الأنماط التي تعلمتها من بيانات التدريب.وتعتمد غالبية أنظمته الحديثة على نماذج التعلم العميق. أمثلة ChatGPT، وأدوات توليد الصور."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يصف أسلوبا من أساليب التعلم الآلي يعتمد على شبكات عصبية متعددة الطبقات لتعلم تمثيلات وأنماط معقدة؟","a":"(ج) التعلم العميق.","mcq":{"stem":"ما هو المصطلح الذي يصف أسلوبا من أساليب التعلم الآلي يعتمد على شبكات عصبية متعددة الطبقات لتعلم تمثيلات وأنماط معقدة؟","opts":["التعلم الآلي.","الذكاء الاصطناعي التوليدي.","التعلم العميق.","مرشح الرسائل المزعجة."],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي الوظيفة الأساسية لأنظمة «الذكاء الاصطناعي التوليدي»؟","a":"(ب) إنشاء محتوى جديد مثل النصوص والصور والصوت والبرمجيات.","mcq":{"stem":"ما هي الوظيفة الأساسية لأنظمة «الذكاء الاصطناعي التوليدي»؟","opts":["برمجة القواعد الصريحة للحواسيب القديمة.","إنشاء محتوى جديد مثل النصوص والصور والصوت والبرمجيات.","تصنيف رسائل البريد المزعجة فقط دون توليد محتوى.","تشغيل الدوائر المتكاملة وفق قانون مور."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح العلاقة بين الذكاء الاصطناعي والتعلم الآلي والتعلم العميق والذكاء الاصطناعي التوليدي؟","a":"الذكاء الاصطناعي مجال واسع يضم أنظمة تستطيع تنفيذ مهام مثل التعلم والتنبؤ والتعرف وتوليد المحتوى.والتعلم الآلي فرع من الذكاء الاصطناعي يتعلم الأنماط من البيانات، والتعلم العميق أسلوب منه يعتمد على شبكات عصبية متعددة الطبقات.وتعتمد غالبية أنظمة الذكاء الاصطناعي التوليدي الحديثة على نماذج التعلم العميق لإنشاء محتوى جديد."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح المقصود بمصطلح «الهلوسة» في سياق الذكاء الاصطناعي التوليدي؟","a":"هي أن ينتج الذكاء الاصطناعي التوليدي نصا يبدو معقولًا، لكنه غير صحيح واقعيا. ويجب التحقق من المخرجات ومصادرها بدلًا من الاعتماد دون مراجعة"},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التقنيات التالية تعتمد عليها غالبية أنظمة الذكاء الاصطناعي التوليدي الحديثة لإنشاء محتوى جديد؟","a":"(ب) نماذج التعلم العميق والشبكات العصبية.","mcq":{"stem":"أي من التقنيات التالية تعتمد عليها غالبية أنظمة الذكاء الاصطناعي التوليدي الحديثة لإنشاء محتوى جديد؟","opts":["القواعد المبرمجة صراحة.","نماذج التعلم العميق والشبكات العصبية.","الحوسبة الطرفية وقانون مور.","البتات الكلاسيكية الثابتة."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يقصد بمصطلح «الهلوسة» عندما ينتج الذكاء الاصطناعي التوليدي نصا غير صحيح؟","a":"(أ) إنتاج نص يبدو معقولا ومنطقياً لكنه غير صحيح واقعيا.","mcq":{"stem":"ماذا يقصد بمصطلح «الهلوسة» عندما ينتج الذكاء الاصطناعي التوليدي نصا غير صحيح؟","opts":["إنتاج نص يبدو معقولا ومنطقياً لكنه غير صحيح واقعيا.","التوقف التام عن الاستجابة بسبب انقطاع الإنترنت.","توليد صور دقيقة بنسبة مئة بالمئة ومطابقة للواقع تماماً.","تصنيف رسائل البريد المزعجة بدقة فائقة."],"correct":0}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"افترض أن مزارعا يريد استخدام نظام ذكاء اصطناعي للتمييز بين صور المحاصيل السليمة والمصابة بالأمراض.اشرح نوع البيانات التي قد يجعل يحتاجها النظام للتدريب؟ وحدد عاملا قد يجعل تنبؤه خاطئا؟","a":"بيانات التدريب: صور للمحاصيل السليمة وصور للمحاصيل المصابة بالأمراض، حتى يتعلم النظام الأنماط اللازمة للتمييز بينهما. عامل قد يسبب الخطأ: أن يواجه النموذج حالة نادرة لم يرَ منها أمثلة كافية في بيانات التدريب؛ إذ أن التعلم العميق يعتمد كثيرًا على بيانات كبيرة نسبيًا لتعلم أنماط موثوقة."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تحدث عن فائدة واحدة ومخاطرة لاستخدام الذكاء الاصطناعي التوليدي في كتابة تقرير مدرسي، وماذا ينبغي على المتعلمين فعله للتحقق من المخرجات؟","a":"الفائدة: السرعة في إنجاز التقرير. المخاطرة: احتمال الحصول على معلومات غير صحيحة أو غير مدعومة (الهلوسة). ما ينبغي فعله: التحقق من المخرجات ومصادرها، وعدم الاعتماد على معلومات تبدو صحيحة دون مصدر موثوق."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات الآتية لا يُعد مثالا مناسبًا على تطبيقات «الذكاء الاصطناعي التوليدي»؟","a":"(ج) مرشح الرسائل المزعجة (Spam Filter)","mcq":{"stem":"أي من الخيارات الآتية لا يُعد مثالا مناسبًا على تطبيقات «الذكاء الاصطناعي التوليدي»؟","opts":["نموذج ChatGPT لتوليد النصوص.","أدوات توليد الصور باستخدام الذكاء الاصطناعي.","مرشح الرسائل المزعجة (Spam Filter)","أدوات توليد الصوت والمقاطع الصوتية."],"correct":2}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي المكونات الأساسية التي تتكون منها الشبكة العصبية الاصطناعية لتعلم الأنماط المعقدة من البيانات؟","a":"(أ) طبقات متصلة تضم وحدات عصبونية تتغير أوزانها أثناء التدريب.","mcq":{"stem":"ما هي المكونات الأساسية التي تتكون منها الشبكة العصبية الاصطناعية لتعلم الأنماط المعقدة من البيانات؟","opts":["طبقات متصلة تضم وحدات عصبونية تتغير أوزانها أثناء التدريب.","مجموعة من الصمامات المفرغة والدوائر الكهربائية البسيطة.","قواعد برمجية ثابتة ومكتوبة بخوارزميات خطية بحتة","مفاتيح يدوية لتنظيم تدفق التيار الكهربائي في المعالج."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"عرف الذكاء الاصطناعي ووضح كيف تختلف الأنظمة الذكية اليوم عن الحواسيب التقليدية المبرمجة بقواعد ثابتة؟","a":"الذكاء الاصطناعي مجال يضم أنظمة حاسوبية تستطيع تنفيذ مهام مثل التعلم من البيانات والتنبؤ والتعرف وتوليد المحتوى واتخاذ القرارات أو دعمها. والفرق أن نماذج التعلم الآلي تتعلم أنماطا من البيانات لإجراء تنبؤات أو دعم قرارات بدلًا من برمجة كل قاعدة صراحة كما في الطرق التقليدية."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بالتفصيل العلاقة المتداخلة بين الذكاء الاصطناعي والتعلم الآلي والتعلم العميق مدعما إجابتك بالمفاهيم الأساسية لكل منها؟","a":"الذكاء الاصطناعي (AI): هو المجال الواسع الذي يضم أنظمة تنفذ مهام مثل التعلم والتنبؤ والتعرف وتوليد المحتوى. التعلم الآلي (ML): فرع من الذكاء الاصطناعي تتعلم فيه النماذج أنماطا من البيانات مثل تصنيف الرسائل المزعجة وتوصية المنتجات. التعلم العميق (DL): أسلوب من التعلم الآلي يعتمد على شبكات عصبية متعددة الطبقات لتعلم أنماط معقدة، مثل تحليل الصور والتعرف على الكلام. إذن التعلم الآلي فرع الذكاء الاصطناعي، والتعلم العميق أسلوبًا من التعلم الآلي، وهي علاقة مبسطة بين فئات مترابطة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما هو «الذكاء الاصطناعي التوليدي»، وكيف يعتمد على نماذج التعلم العميق لإنشاء محتوى جديد كالنصوص والصور؟","a":"الذكاء الاصطناعي التوليدي أنظمة تنشئ محتوى جديدا، مثل النصوص والصور والصوت والبرمجيات، اعتمادا على الأنماط التي تعلمتها من بيانات التدريب.وتعتمد غالبية أنظمته الحديثة على نماذج التعلم العميق.ومن أمثلته ChatGPT وأدوات توليد الصور."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش مشكلة «الهلوسة» في الذكاء الاصطناعي التوليدي، موضحًا سبب خطورتها والإجراء المناسب للتحقق من المخرجات؟","a":"الهلوسة: إنتاج نص يبدو: معقولًا، لكنه غير صحيح واقعيا. خطورتها: قد يؤدي استخدامه كما هو في تقرير مدرسي إلى الاعتماد على معلومات غير صحيحة أو غير مدعومة. الإجراء المناسب: التحقق من المخرجات ومصادرها، وعدم الاعتماد على إجابة دون مصدر موثوق."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي مما يلي يمثل فرعًا من الذكاء الاصطناعي تتعلم فيه النماذج أنماطًا من البيانات بدلًا من برمجة كل قاعدة صراحة؟","a":"(ج) التعلم الآلي.","mcq":{"stem":"أي مما يلي يمثل فرعًا من الذكاء الاصطناعي تتعلم فيه النماذج أنماطًا من البيانات بدلًا من برمجة كل قاعدة صراحة؟","opts":["التعلم العميق.","الذكاء الاصطناعي التوليدي.","التعلم الآلي.","الحوسبة السحابية."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أسلوب من أساليب التعلم الآلي يعتمد على شبكات عصبية متعددة الطبقات لتعلم تمثيلات وأنماط معقدة مثل تحليل الصور والتعرف على الكلام هو:","a":"(أ) التعلم العميق.","mcq":{"stem":"أسلوب من أساليب التعلم الآلي يعتمد على شبكات عصبية متعددة الطبقات لتعلم تمثيلات وأنماط معقدة مثل تحليل الصور والتعرف على الكلام هو:","opts":["التعلم العميق.","الذكاء الاصطناعي.","الذكاء الاصطناعي التوليدي.","البرمجة التقليدية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"نظام حاسوبي مستوحى بصورة مبسطة من فكرة ترابط العصبونات وتتغير أوزانه أثناء التدريب هو:","a":"(ب) الشبكة العصبية الاصطناعية.","mcq":{"stem":"نظام حاسوبي مستوحى بصورة مبسطة من فكرة ترابط العصبونات وتتغير أوزانه أثناء التدريب هو:","opts":["الكيوبت الكمومي.","الشبكة العصبية الاصطناعية.","البت الكلاسيكي.","قانون مور."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"عندما ينتج الذكاء الاصطناعي التوليدي نصا غير صحيح؟ نصا يبدو معقولًا ولكن غير صحيح واقعيا، تسمى هذه الظاهرة ب:","a":"(أ) الهلوسة.","mcq":{"stem":"عندما ينتج الذكاء الاصطناعي التوليدي نصا غير صحيح؟ نصا يبدو معقولًا ولكن غير صحيح واقعيا، تسمى هذه الظاهرة ب:","opts":["الهلوسة.","التراكب الكمي.","الحوسبة الطرفية.","التشغيل الخطي."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف تساعد أمثلة الحياة اليومية مثل تصنيف الرسائل المزعجة وتوصيات المنتجات والترجمة في فهم تطبيقات الذكاء الاصطناعي؟","a":"يمكن أن يعمل الذكاء الاصطناعي في الخلفية عند استخدام الهاتف أو الحاسوب؛ فيصنف رسائل البريد المزعجة، أو يوصي بمنتجات، أو يترجم نصا. ويعد تصنيف الرسائل المزعجة وتوصية المنتجات مثالين على التعلم الآلي الذي يتعلم أنماطا من البيانات. أما الترجمة فهي مثال على المهام التي تؤديها أنظمة الذكاء الاصطناعي."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"قارن بوضوح بين «التعلم الآلي» و«التعلم العميق» من حيث الاعتماد على الشبكات العصبية وحجم البيانات المطلوبة للتدريب؟","a":"التعلم الآلي: فرع من الذكاء الاصطناعي تتعلم فيه النماذج أنماطًا من البيانات للتنبؤ أو التصنيف أو دعم القرارات. التعلم العميق: أسلوب من التعلم الآلي يعتمد على شبكات عصبية متعددة الطبقات لتعلم تمثيلات وأنماط معقدة، وكثيرًا ما يعتمد على بيانات كبيرة نسبيًا لتتعلم أنماطًا موثوقة. من حيث حجم البيانات: الحاجة المتكررة لبيانات كبيرة نسبيًا في التعلم العميق، ولا يحدد حجمًا ثابتًا مطلوبًا للتعلم الآلي عمومًا."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يتمكن الذكاء الاصطناعي التوليدي من إنشاء محتوى جديد ومتنوع مثل النصوص والصور والأصوات اعتمادا على بيانات التدريب؟","a":"ينشئ الذكاء الاصطناعي التوليدي محتوى جديدا، مثل النصوص والصور والصوت والبرمجيات، اعتمادا على الأنماط التي تعلمتها نماذجه من بيانات التدريب.وتعتمد غالبية أنظمته الحديثة على نماذج التعلم العميق، مثل ChatGPT وأدوات توليد الصور."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ضع قاعدة مناسبة للتعامل مع الذكاء الاصطناعي التوليدي في الواجبات المدرسية مع ذكر سببين مقنعين لضرورة التحقق من دقة المصادر؟","a":"القاعدة: لا تستخدم مخرجات الذكاء الاصطناعي التوليدي في الواجبات المدرسية كما هي دون التحقق منها ومن مصادرها. السبب الأول: قد ينتج نصا يبدو صحيحا لكنه خاطئ في الواقع (هلوسة) السبب الثاني: قد تتضمن المخرجات معلومات غير مدعومة بمصادر؛ ولذلك يشدد الكتاب على ضرورة التحقق من المخرجات ومصادرها."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يعد مثالا مباشرا على تطبيقات «التعلم الآلي»؟","a":"(أ) مرشحات الرسائل المزعجة وتوصيات المنتجات.","mcq":{"stem":"أي من الخيارات التالية يعد مثالا مباشرا على تطبيقات «التعلم الآلي»؟","opts":["مرشحات الرسائل المزعجة وتوصيات المنتجات.","توليد الصور ومقاطع الفيديو الفنية المعقدة.","معالجة البيانات على الأجهزة الطرفية للسيارات","تشغيل الدوائر المتكاملة وفق قانون مور."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو الوصف الدقيق ل«الذكاء الاصطناعي التوليدي (GenAI)»؟","a":"(ب) ذكاء اصطناعي يستخدم التعلم العميق لتوليد بيانات جديدة مثل النصوص والصور.","mcq":{"stem":"ما هو الوصف الدقيق ل«الذكاء الاصطناعي التوليدي (GenAI)»؟","opts":["نظام يقتصر على تصنيف البريد المزعج وإزالة الفيروسات.","ذكاء اصطناعي يستخدم التعلم العميق لتوليد بيانات جديدة مثل النصوص والصور.","تقنية حوسبية تستخدم ميكانيكا الكم والمعالجة المتوازية.","شبكة عصبية بسيطة ذات طبقة إدخال وإخراج واحدة فقط."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا تسمى الطبقات الواقعة بين طبقة الإدخال وطبقة الإخراج في الشبكة العصبية الاصطناعية؟","a":"(أ) الطبقات المخفية.","mcq":{"stem":"ماذا تسمى الطبقات الواقعة بين طبقة الإدخال وطبقة الإخراج في الشبكة العصبية الاصطناعية؟","opts":["الطبقات المخفية.","الطبقات الطرفية.","الطبقات السحابية.","الطبقات الخطية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما الذي يجب على المتعلمين فعله لتجنب مخاطر «الهلوسة» عند استخدام الذكاء الاصطناعي التوليدي في إعداد تقاريرهم المدرسية؟","a":"(ب) التحقق من المخرجات ومصادرها ومقارنتها بالحقائق الموثوقة.","mcq":{"stem":"ما الذي يجب على المتعلمين فعله لتجنب مخاطر «الهلوسة» عند استخدام الذكاء الاصطناعي التوليدي في إعداد تقاريرهم المدرسية؟","opts":["الاعتماد المطلق على المخرجات دون أي مراجعة بشرية.","التحقق من المخرجات ومصادرها ومقارنتها بالحقائق الموثوقة.","تجنب استخدام الهواتف والحواسيب بشكل كامل ودائم.","نسخ النصوص حرفياً وتسليمها للمدرس مباشرة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"لماذا تعد معظم أنظمة الذكاء الاصطناعي الحالية «ضيق النطاق)»Narrow(AI؟","a":"لأن معظم أنظمة الذكاء الاصطناعي الحالية تصمم لأداء مهمة محددة أو مجموعة محدودة من المهام."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"عرف الشبكة العصبية الاصطناعية.","a":"الشبكة العصبية الاصطناعية (ANN): نموذج حاسوبي مستوحى بصورة مبسطة من فكرة ترابط العصبونات، ويتكون من وحدات مترابطة تتغير أوزانها أثناء التدريب لتتعلم أنماطا من البيانات."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ارسم شكال مبسطا توضح فيه العلاقة بين الذكاء الاصطناعي والتعلم العميق والتعلم الآلي والذكاء الاصطناعي التوليدي.","a":"يمكن رسم العلاقة بصورة تعليمية مبسطة كما في كتاب المدرسة (شكل): الذكاء الاصطناعي (AI) ↳التعلم الآلي (ML) ↳التعلم العميق (DL) الذكاء الاصطناعي التوليدي (GenAI): تعتمد غالبية أنظمته الحديثة على نماذج التعلم العميق. وهذا تمثيل تعليمي مبسط، وليس تسلسل احتواء صارما في كل حالة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"معظم أنظمة الذكاء الاصطناعي الحالية تصمم لأداء:","a":"(أ) مهمة محددة أو مجموعة محدودة من المهام (ضيق النطاق).","mcq":{"stem":"معظم أنظمة الذكاء الاصطناعي الحالية تصمم لأداء:","opts":["مهمة محددة أو مجموعة محدودة من المهام (ضيق النطاق).","محاكاة الوعي البشري الكامل في جميع المجالات دون قيود.","برمجة الأجهزة الكهربائية المنزلية القديمة يدوياً.","إدارة شبكات الاتصال العسكرية العالمية فقط."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات الآتية يمثل التقنية الأنسب لمهام تحليل الصور المعقدة والتعرف المتقدم على الكلام؟","a":"(أ) التعلم العميق المعتمد على شبكات عصبية متعددة الطبقات.","mcq":{"stem":"أي من الخيارات الآتية يمثل التقنية الأنسب لمهام تحليل الصور المعقدة والتعرف المتقدم على الكلام؟","opts":["التعلم العميق المعتمد على شبكات عصبية متعددة الطبقات.","القواعد المبرمجة يدوياً بأسلوب خطي ثابت.","الحوسبة السحابية التقليدية دون ذكاء اصطناعي.","التجارة الإلكترونية والدفع غير النقدي"],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي الفائدة الأساسية للسرعة التي يوفرها الذكاء الاصطناعي التوليدي للطالب عند إعداد التقارير؟","a":"(أ) المساعدة في إنجاز المهام سريعًا مع ضرورة الانتباه لمخاطر عدم الصحة.","mcq":{"stem":"ما هي الفائدة الأساسية للسرعة التي يوفرها الذكاء الاصطناعي التوليدي للطالب عند إعداد التقارير؟","opts":["المساعدة في إنجاز المهام سريعًا مع ضرورة الانتباه لمخاطر عدم الصحة.","ضمان صحة جميع المعلومات بنسبة مئة بالمئة تلقائيًا.","الاستغناء التام عن الكتب والمصادر المدرسية الرسمية","منع حدوث ظاهرة الهلوسة نهائيًا."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو الإجراء السليم الذي ينبغي اتباعه عند استخدام أدوات الذكاء الاصطناعي التوليدي في الواجبات والمشاريع؟","a":"(أ) التحقق الدائم من صحة المعلومات ومراجعة المصادر والمراجع الأصلية.","mcq":{"stem":"ما هو الإجراء السليم الذي ينبغي اتباعه عند استخدام أدوات الذكاء الاصطناعي التوليدي في الواجبات والمشاريع؟","opts":["التحقق الدائم من صحة المعلومات ومراجعة المصادر والمراجع الأصلية.","اعتبار كل ما تنتجه الشاشات حقائق علمية مطلقة لا تقبل التشكيك.","عدم كتابة أي أبحاث مدرسية والاعتماد على الذكاء الاصطناعي كليًا.","إرسال مخرجات الذكاء الاصطناعي دون قراءتها أو تفحصها."],"correct":0}}],"1-3":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح كيف أصبحت تقنيات مثل منصات الفيديو والمساعدات الصوتية جزءا من الخدمات اليومية، وما هو الدور الأساسي للذكاء الاصطناعي فيها؟","a":"أصبح الذكاء الاصطناعي جزءا من خدمات يومية كثيرة؛ فقد تقترح منصة فيديو مقاطع تناسب اهتمامات المستخدم، ويجيب مساعد صوتي عن أسئلته. دوره: تتنبأ أنظمة التوصية بالتفضيلات من بيانات السلوك السابق وتعرض التوصيات، وتتعرف المساعدات الصوتية على الصوت وتفهم الأوامر وتنفذها."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح المقصود ب«الذكاء الاصطناعي للتشخيص بالصور» في مجال الرعاية الصحية، وكيف يسفهمي الكشف عن الأمراض؟","a":"هو استخدام الذكاء الاصطناعي في الرعاية الصحية للكشف عن الأمراض من الصور الطبية، مثل صور الأشعة السينية والتصوير المقطعي. كذلك في دعم اكتشاف الأدوية."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات التالية يعد مثالا على نظام يتنبأ بالتفضيلات من بيانات السلوك السابق ويعرض التوصيات؟","a":"(أ) نظام التوصية.","mcq":{"stem":"أي من الخيارات التالية يعد مثالا على نظام يتنبأ بالتفضيلات من بيانات السلوك السابق ويعرض التوصيات؟","opts":["نظام التوصية.","المساعد الصوتي.","الترجمة الآلية.","التعرف على الوجه."],"correct":0}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي الخدمة التي تقوم بترجمة النص تلقائيا إلى لغات مختلفة كما ورد في خدمات الذكاء الاصطناعي اليومية؟","a":"(ج) الترجمة الآلية.","mcq":{"stem":"ما هي الخدمة التي تقوم بترجمة النص تلقائيا إلى لغات مختلفة كما ورد في خدمات الذكاء الاصطناعي اليومية؟","opts":["نظام التوصية.","المساعد الصوتي.","الترجمة الآلية.","التعرف على الوجه."],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر أربع خدمات أساسية للذكاء الاصطناعي في الحياة اليومية مع بيان دور الذكاء الاصطناعي في كل خدمة؟","a":" أنظمة التوصية: التنبؤ بالتفضيلات من بيانات السلوك السابق وعرض التوصيات، مثل يوتيوب وأمازون وسبوتيفاي.  المساعدات الصوتية: التعرف على الصوت وفهم الأوامر وتنفيذها، مثل سيري (Siri) ومساعد جوجل.  الترجمة الآلية: ترجمة النص تلقائيا إلى لغات مختلفة، مثل Google Translate و D.eepL  التعرف على الوجه: الكشف عن وجوه الأشخاص في الصور والتعرف عليها تلقائيا، مثل فتح الهاتف الذكي."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما هو الدور الذي يلعبه الذكاء الاصطناعي في قطاع التصنيع؟ اذكر مثالين توضيحيين.","a":"يدخل الذكاء الاصطناعي في قطاع التصنيع، ومن أمثلة استخدامه: التنبؤية، أي التنبؤ بأعطال الآلات أو المعدات قبل وقوعها."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يشير إلى نظام الذكاء الاصطناعي الذي يتعرف على الصوت، ويفهم الأوامر، وينفذها مثل Siri ومساعد جوجل؟","a":"(ب) المساعد الصوتي","mcq":{"stem":"ما هو المصطلح الذي يشير إلى نظام الذكاء الاصطناعي الذي يتعرف على الصوت، ويفهم الأوامر، وينفذها مثل Siri ومساعد جوجل؟","opts":["نظام التوصية","المساعد الصوتي","الترجمة الآلية","التعرف على الوجه"],"correct":1}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من القطاعات الصناعية التالية ترتبط بمهمة «تحسين مسارات التوصيل»؟","a":"(د) الخدمات اللوجستية","mcq":{"stem":"أي من القطاعات الصناعية التالية ترتبط بمهمة «تحسين مسارات التوصيل»؟","opts":["الرعاية الصحية","الزراعة","التصنيع","الخدمات اللوجستية"],"correct":3}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح كيف يتم استخدام الذكاء الاصطناعي في قطاع الزراعة ودوره في مراقبة المحاصيل والآفات.","a":"يستخدم الذكاء الاصطناعي في قطاع الزراعة للتنبؤ بموعد الحصاد والكشف عن الآفات والأمراض."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"اذكر أربع مهام يمكن أن يؤديها الذكاء الاصطناعي في معالجة البيانات المعقدة والتعرف على الصور والأصوات.","a":"إيجاد الأنماط وتصنيفها في البيانات المعقدة، مثل الصور والنصوص. .. التعرف على الصور والأصوات والنصوص. .. توليد بعض أنواع المحتوى. .. الاستدلال الاحتمالي والتنبؤ استنادا إلى البيانات."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي الصناعة التي تستخدم الذكاء الاصطناعي للكشف عن الأمراض من صور الأشعة السينية والتصوير المقطعي؟","a":"(أ) الرعاية الصحية","mcq":{"stem":"ما هي الصناعة التي تستخدم الذكاء الاصطناعي للكشف عن الأمراض من صور الأشعة السينية والتصوير المقطعي؟","opts":["الرعاية الصحية","الزراعة","التصنيع","الخدمات اللوجستية"],"correct":0}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات الآتية يمثل المهمة الرئيسية للذكاء الاصطناعي في قطاع الزراعة؟","a":"(ب) التنبؤ بموعد الحصاد والكشف عن الآفات والأمراض","mcq":{"stem":"أي من الخيارات الآتية يمثل المهمة الرئيسية للذكاء الاصطناعي في قطاع الزراعة؟","opts":["تحسين مسارات التوصيل","التنبؤ بموعد الحصاد والكشف عن الآفات والأمراض","فحص جودة المنتج والصيانة التنبؤية","تحليل الصور الطبية واكتشاف الأدوية"],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح مقولة «الذكاء الاصطناعي بارع في إيجاد الأنماط في البيانات، لكن الحكم البشري لا يزال ضروريا»","a":"يبرع الذكاء الاصطناعي في إيجاد الأنماط وتصنيفها، والتعرف على الصور والأصوات والنصوص، والتنبؤ استنادا إلى البيانات. لكنه قد يخطئ أو ينتج نتائج متحيزة؛ لذلك يظل الحكم البشري ضروريا في الأمور المتعلقة بالأخلاق والخصوصية والمسؤولية، وتزداد أهمية التحقق البشري كلما كان القرار أعلى أثرا."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر ثلاثة احتياطات للاستخدام المتعلقة بالذكاء الاصطناعي.","a":" الحذر عند اتخاذ قرارات ذات بعد أخلاقي قد تؤدي إلى تمييز أو تحيز.  الحذر عند التعامل مع المعلومات الشخصية والبيانات الحساسة.  الحذر في القرارات عالية الأثر وتحديد المسؤولية عن نتائجها."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يصف توليد معلومات غير صحيحة أو غير مدعومة تبدو مقنعة من قبل الذكاء الاصطناعي؟","a":"(ب) الهلوسة.","mcq":{"stem":"ما هو المصطلح الذي يصف توليد معلومات غير صحيحة أو غير مدعومة تبدو مقنعة من قبل الذكاء الاصطناعي؟","opts":["مشكلة الصندوق الأسود.","الهلوسة.","التمييز أو التحيز.","بيانات التدريب غير الكافية."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يقصد بمشكلة «الصندوق الأسود» في سياق تطبيقات الذكاء الاصطناعي؟","a":"(ب) عدم الوضوح حول كيفية توصل الذكاء الاصطناعي إلى حكمه أو قراره.","mcq":{"stem":"ماذا يقصد بمشكلة «الصندوق الأسود» في سياق تطبيقات الذكاء الاصطناعي؟","opts":["توليد معلومات غير صحيحة تبدو مقنعة للمستخدم.","عدم الوضوح حول كيفية توصل الذكاء الاصطناعي إلى حكمه أو قراره.","استخدام أعمال محمية بحقوق المؤلف كبيانات تدريب.","نقص بيانات التدريب أو عدم تمثيلها للواقع بدقة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيفية استخدام أنظمة التوصية في الحياة اليومية مع ذكر أمثلة تطبيقية مثل يوتيوب وأمازون؟","a":"تستخدم أنظمة التوصية بيانات السلوك السابق للتنبؤ بتفضيلات المستخدم وعرض توصيات قد تهمه؛ مثل اقتراح فيديوهات في يوتيوب، وعرض توصيات في أمازون، ومن أمثلتها أيضا سبوتيفاي."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر استخدامات الذكاء الاصطناعي في الرعاية الصحية؟","a":"من استخدامات الذكاء الاصطناعي في الرعاية الصحية:. التشخيص بالصور، أي الكشف عن الأمراض من صور الأشعة السينية والتصوير المقطعي.٢ .. دعم اكتشاف الأدوية."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر أربعة قطاعات صناعية رئيسية يتم فيها إدخال تقنيات الذكاء الاصطناعي مع بيان دور كل قطاع باختصار؟","a":"الرعاية الصحية: التشخيص بالصور ودعم اكتشاف الأدوية. الزراعة: التنبؤ بموعد الحصاد والكشف عن الآفات والأمراض. التصنيع: أتمتة فحص جودة المنتج والصيانة التنبؤية. الخدمات اللوجستية: تحسين مسارات التوصيل."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح ما يبرع فيه الذكاء الاصطناعي وما يتطلب الحذر عند استخدامه فيما يتعلق بالقرارات ذات البعد الأخلاقي والخصوصية؟","a":"ما يبرع فيه: إيجاد وتصنيف الأنماط في البيانات المعقدة، والتعرف على الصور والأصوات والنصوص، وتوليد بعض المحتوى، والاستدلال الاحتمالي والتنبؤ استنادا إلى البيانات. ما يتطلب الحذر: القرارات ذات البعد الأخلاقي التي قد تؤدي إلى تمييز أو تحيز، والتعامل مع المعلومات الشخصية والبيانات الحساسة، والقرارات عالية الأثر وتحديد المسؤولية عن نتائجها."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخدمات التالية تستخدم لفتح الهاتف الذكي والكشف عن وجوه الأشخاص في الصور والتعرف عليها تلقائيا؟","a":"(د) التعرف على الوجه.","mcq":{"stem":"أي من الخدمات التالية تستخدم لفتح الهاتف الذكي والكشف عن وجوه الأشخاص في الصور والتعرف عليها تلقائيا؟","opts":["نظام التوصية.","المساعد الصوتي.","الترجمة الآلية.","التعرف على الوجه."],"correct":3}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي التقنية المستخدمة في فحص جودة المنتج والتنبؤ بأعطال الآلات قبل وقوعها؟","a":"(ب) الذكاء الاصطناعي في التصنيع والصيانة التنبؤية.","mcq":{"stem":"ما هي التقنية المستخدمة في فحص جودة المنتج والتنبؤ بأعطال الآلات قبل وقوعها؟","opts":["الذكاء الاصطناعي للتشخيص بالصور.","الذكاء الاصطناعي في التصنيع والصيانة التنبؤية.","نظم التوصية والمساعد الصوتي.","الترجمة الآلية وشبكات التواصل."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"من ضمن احتياطات الاستخدام للذكاء الاصطناعي، ماذا تعني ظاهرة «الهلوسة»؟","a":"(ب) توليد معلومات غير صحيحة أو غير مدعومة تبدو مقنعة.","mcq":{"stem":"من ضمن احتياطات الاستخدام للذكاء الاصطناعي، ماذا تعني ظاهرة «الهلوسة»؟","opts":["عدم معرفة كيف توصل النظام لقراره","توليد معلومات غير صحيحة أو غير مدعومة تبدو مقنعة.","وجود تحيز في بيانات التدريب.","انتهاك حقوق المؤلف للبيانات."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الآتي لا يعد الوصف الصحيح لما يبرع فيه الذكاء الاصطناعي؟","a":"(أ) إيجاد وتصنيف الأنماط في البيانات المعقدة والاستدلال الاحتمالي.","mcq":{"stem":"أي من الآتي لا يعد الوصف الصحيح لما يبرع فيه الذكاء الاصطناعي؟","opts":["إيجاد وتصنيف الأنماط في البيانات المعقدة والاستدلال الاحتمالي.","اتخاذ الأحكام الأخلاقية المطلقة بدون بشر.","ضمان خلو المخرجات تماماً من أي تحيز مستقبلي.","حفظ البيانات الشخصية وحمايتها بسرية تامة."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكرا دور الذكاء الاصطناعي في المساعدات الصوتية مع ذكر مثالين.","a":"الدور: التعرف على الصوت وفهم الأوامر وتنفيذها. مثالان من: سيري (Siri) ومساعد جوجل."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش دور الذكاء الاصطناعي في قطاعي الزراعة والخدمات اللوجستية في تحسين العمليات والإنتاجية؟","a":"الزراعة: يستخدم الذكاء الاصطناعي للتنبؤ بموعد الحصاد والكشف عن الآفات والأمراض. الخدمات اللوجستية: يستخدم لتحسين مسارات التوصيل."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح باختصار احتياطات الاستخدام المرتبطة ببيانات التدريب المتحيزة والقرارات عالية الأثر وتحديد المسؤولية؟","a":"قد تصبح نتائج الذكاء الاصطناعي غير دقيقة عندما تكون بيانات التدريب غير كافية أو غير ممثلة أو متحيزة.وقد تؤدي القرارات ذات البعد الأخلاقي إلى تمييز أو تحيز؛ لذا يتطلب الأمر الحذر في القرارات عالية الأثر، وتحديد المسؤولية عن نتائجها، والتحقق البشري خصوصا حين يزداد أثر القرار"},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح سبب ضرورة وجود تأكيد من طبيب بشري للتشخيص الطبي بدلًا من الاعتماد على الذكاء الاصطناعي وحده؟","a":"لأن الذكاء الاصطناعي قد يخطئ أو ينتج نتائج متحيزة، وقد تتأثر دقة النتائج ببيانات تدريب غير كافية أو غير ممثلة أو متحيزة.والتشخيص الطبي قرار يؤثر في حياة الأشخاص؛ لذلك ينبغي أن يؤكد الطبيب البشري التشخيص النهائي بدلًا من تركه للذكاء الاصطناعي وحده."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"خدمة يومية تستخدم لفهم الكلام وتنفيذ الأوامر الصوتية مثل Siri ومساعد جوجل هي:","a":"(ب) المساعد الصوتي.","mcq":{"stem":"خدمة يومية تستخدم لفهم الكلام وتنفيذ الأوامر الصوتية مثل Siri ومساعد جوجل هي:","opts":["نظام التوصية.","المساعد الصوتي.","الترجمة الآلية.","التعرف على الوجه."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"قطاع صناعي يستخدم الذكاء الاصطناعي لتحسين مسارات التوصيل هو:","a":"(د) الخدمات اللوجستية.","mcq":{"stem":"قطاع صناعي يستخدم الذكاء الاصطناعي لتحسين مسارات التوصيل هو:","opts":["الرعاية الصحية.","الزراعة.","التصنيع.","الخدمات اللوجستية."],"correct":3}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يعبر عن عدم وضوح كيفية توصل الذكاء الاصطناعي إلى حكمه أو قراره؟","a":"(ب) مشكلة الصندوق الأسود.","mcq":{"stem":"ما هو المصطلح الذي يعبر عن عدم وضوح كيفية توصل الذكاء الاصطناعي إلى حكمه أو قراره؟","opts":["الهلوسة.","مشكلة الصندوق الأسود.","التمييز أو التحيز.","الاستدلال الاحتمالي."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ممن ضمن المهام التي يجيدها الذكاء الاصطناعي:","a":"(ب) التعرف على الصور والأصوات والنصوص وتوليد المحتوى.","mcq":{"stem":"ممن ضمن المهام التي يجيدها الذكاء الاصطناعي:","opts":["اتخاذ القرارات الأخلاقية المعقدة.","التعرف على الصور والأصوات والنصوص وتوليد المحتوى.","ضمان دقة النتائج المطلقة دون بيانات تدريب","حماية الخصوصية الشخصية تلقائيًا."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح ثلاث خدمات يمكن أن يؤديها الذكاء الاصطناعي في الحياة اليومية.","a":""},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح الأبعاد المتعلقة بمشكلة الصندوق الأسود وقضايا الحقوق عند استخدام أعمال محمية بحقوق المؤلف كبيانات تدريب؟","a":"مشكلة الصندوق الأسود: عدم الوضوح حول كيفية توصل الذكاء الاصطناعي إلى حكمه أو قراره. قضايا الحقوق: تثار قضايا الحقوق عند استخدام أعمال محمية بحقوق المؤلف بوصفها بيانات تدريب للذكاء الاصطناعي."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح الفروق الجوهرية بين ما يبرع فيه الذكاء الاصطناعي من إيجاد الأنماط وبين الجوانب التي تتطلب الحذر الشديد مثل الخصوصية والأخلاق؟","a":"ما يبرع فيه: إيجاد وتصنيف الأنماط في البيانات المعقدة، والتعرف على الصور والأصوات والنصوص، وتوليد بعض أنواع المحتوى، والتنبؤ استنادا إلى البيانات. ما يتطلب الحذر: القرارات الأخلاقية التي قد تؤدي إلى تمييز أو تحيز، والتعامل مع البيانات الشخصية والحساسة، والقرارات عالية الأثر وتحديد المسؤولية عن نتائجها؛ ولذلك يظل الحكم البشري ضروريا."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"نظام يتنبأ بالتفضيلات من بيانات السلوك السابق ويعرض التوصيات في منصات مثل يوتيوب وأمازون يسمى:","a":"(أ) نظام التوصية.","mcq":{"stem":"نظام يتنبأ بالتفضيلات من بيانات السلوك السابق ويعرض التوصيات في منصات مثل يوتيوب وأمازون يسمى:","opts":["نظام التوصية.","المساعد الصوتي.","الترجمة الآلية.","التعرف على الوجه."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الصناعات التالية تستخدم الذكاء الاصطناعي للتنبؤ بموعد الحصاد والكشف عن الآفات والأمراض؟","a":"(ب) الزراعة.","mcq":{"stem":"أي من الصناعات التالية تستخدم الذكاء الاصطناعي للتنبؤ بموعد الحصاد والكشف عن الآفات والأمراض؟","opts":["الرعاية الصحية.","الزراعة.","التصنيع.","الخدمات اللوجستية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"القرارات ذات البعد الأخلاقي التي قد تؤدي إلى تمييز أو تحيز تعد ضمن:","a":"(ب) ما يتطلب الحذر عند استخدام الذكاء الاصطناعي.","mcq":{"stem":"القرارات ذات البعد الأخلاقي التي قد تؤدي إلى تمييز أو تحيز تعد ضمن:","opts":["ما يبرع فيه الذكاء الاصطناعي.","ما يتطلب الحذر عند استخدام الذكاء الاصطناعي.","المهارات الأساسية للتعلم العميق.","دور أنظمة التوصية اليومية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"يعرف التحيز في أنظمة الذكاء الاصطناعي على أنه:","a":"(أ) نمط قد يؤدي إلى نتائج غير عادلة.","mcq":{"stem":"يعرف التحيز في أنظمة الذكاء الاصطناعي على أنه:","opts":["نمط قد يؤدي إلى نتائج غير عادلة.","الهلوسة.","التراكب الكمي.","الاستدلال الاحتمالي."],"correct":0}}],"1-4":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"ما المقصود بمصطلح «التحيز الخوارزمي» في أنظمة الذكاء الاصطناعي، وما هي أبرز أشكاله أو أمثلته؟","a":"التحيز الخوارزمي هو نمط في مخرجات الذكاء الاصطناعي قد يؤدي إلى نتائج غير عادلة أو ضارة، ويمكن أن ينشأ من البيانات أو تصميم النظام أو طريقة استخدامه أو السياق البشري والاجتماعي ومن أمثلته: نظام توظيف يفضل فئة بصورة غير عادلة، أو نظام للتعرف على الوجه تقل دقته مع فئات معينة."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح الأسباب الرئيسية لنشوء التحيز الخوارزمي في أنظمة الذكاء الاصطناعي؟","a":"من أسبابه بيانات تدريب متحيزة، مثل وجود بيانات غير كافية عن سمات معينة أو انعكاس نزعات تمييزية سابقة في البيانات.وقد ينشأ أيضا من طريقة بناء النظام، مثل الختيار غير المناسب للمتغيرات، أو استخدام متغير بديل يمثل بصورة غير مباشرة سمة محمية، أو من تصميم النموذج وطريقة استخدامه والسياق البشري والاجتماعي."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات التالية يعد سببًا غير مناسب أو غير صحيح لنشوء التحيز الخوارزمي؟","a":"(ج) سرعة معالجة الحاسوب بطيئة.","mcq":{"stem":"أي من الخيارات التالية يعد سببًا غير مناسب أو غير صحيح لنشوء التحيز الخوارزمي؟","opts":["بيانات التدريب متحيزة.","انعكاس نزعات تمييزية سابقة في البيانات.","سرعة معالجة الحاسوب بطيئة.","وجود بيانات غير كافية عن سمات معينة."],"correct":2}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ماذا يمثل مصطلح «التحيز الخوارزمي» في أنظمة الذكاء الاصطناعي؟","a":"(أ) نمط في مخرجات الذكاء الاصطناعي قد يؤدي إلى نتائج غير عادلة أو ضارة.","mcq":{"stem":"ماذا يمثل مصطلح «التحيز الخوارزمي» في أنظمة الذكاء الاصطناعي؟","opts":["نمط في مخرجات الذكاء الاصطناعي قد يؤدي إلى نتائج غير عادلة أو ضارة.","تقنية تتيح للبشر فهم سبب اتخاذ الذكاء الاصطناعي حكماً معيناً.","التعامل المناسب مع البيانات الشخصية وحمايتها.","تحديد الجهات المسؤولة عن النظام وقراراته وآثاره."],"correct":0}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف أدى تطور تقنية الذكاء الاصطناعي إلى ظهور قضايا جديدة تتعلق بالخصوصية والمراقبة في الأماكن العامة.","a":"أدى تطور الذكاء الاصطناعي إلى ظهور قضايا تتعلق بالخصوصية؛ إذ يمكن للكاميرات في الأماكن العامة، باستخدام تقنية التعرف على الوجه، التعرف على الأفراد وتتبعهم.كما تجمع وتحلل كميات كبيرة من بيانات السلوك عبر الإنترنت."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما المقصود بمصطلح «بيانات التدريب» في أنظمة الذكاء الاصطناعي، وكيف يؤثر نقص تمثيلها على المخرجات؟","a":"بيانات التدريب هي الأمثلة التي يتعلم منها نظام الذكاء الاصطناعي أنماطه قبل استخدامه. وكلما قل تمثيلها للواقع زاد احتمال تحيز مخرجاته؛ وقد تسهم بيانات التدريب غير الممثلة أو المتحيزة في نتائج غير عادلة."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات الآتية يمثل المفهوم الدقيق ل«بيانات التدريب»؟","a":"(أ) الأمثلة التي يتعلم منها نظام الذكاء الاصطناعي أنماطه قبل استخدامه.","mcq":{"stem":"أي من الخيارات الآتية يمثل المفهوم الدقيق ل«بيانات التدريب»؟","opts":["الأمثلة التي يتعلم منها نظام الذكاء الاصطناعي أنماطه قبل استخدامه.","تقنية تتيح للبشر فهم سبب اتخاذ الذكاء الاصطناعي حكماً معيناً.","تحديد الجهات المسؤولة عن النظام وقراراته وآثاره.","عدم التمييز ظلمًا ضد أي شخص أو مجموعة."],"correct":0}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي إحدى قضايا الخصوصية المرتبطة بالذكاء الاصطناعي؟","a":"(ج) التعرف على الأفراد وتتبعهم من خلال تقنية التعرف على الوجه.","mcq":{"stem":"ما هي إحدى قضايا الخصوصية المرتبطة بالذكاء الاصطناعي؟","opts":["تحسن سرعة حوسبة الذكاء الاصطناعي.","إنشاء الذكاء الاصطناعي لأعمال إبداعية.","التعرف على الأفراد وتتبعهم من خلال تقنية التعرف على الوجه.","زيادة كفاءة المعالجات الدقيقة."],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"ما المقصود بمصطلح «الذكاء الاصطناعي القابل للتفسير (XAI)» ولماذا يعد أسلوبا أساسيا للتغلب على مشكلة الصندوق الأسود؟","a":"الذكاء الاصطناعي القابل للتفسير (XAI) أساليب تساعد البشر على فهم العوامل التي أسهمت في وصول النظام إلى مخرج أو قرار معين.وتظهر أهميته عندما تكون آلية الوصول إلى النتيجة غير واضحة؛ إذ يصعب عندئذ تقييم النتائج واكتشاف الأخطاء أو التحيز."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"قارن بإيجاز بين مفهوم «المسؤولية» ومفهوم «المساءلة» في سياق أنظمة الذكاء الاصطناعي؟","a":"المسؤولية (Responsibility): تحديد أدوار وواجبات الأطراف المرتبطة بتطوير النظام وتشغيله واستخدامه، مثل المطور والجهة والمستخدم.ويختلف توزيع المسؤولية باختلاف النظام والاستخدام والقواعد المعمول بها. المساءلة (Accountability): تحديد الجهات المسؤولة عن النظام وقراراته وآثاره، وإمكان محاسبتها وفق أدوارها. والمساءلة لا تعني مجرد شرح القرار بل من حاسب على النتيجة."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هو المصطلح الذي يصف التقنية التي تتيح للبشر فهم العوامل والسبب الذي أدى بالذكاء الاصطناعي إلى اتخاذ حكم معين؟","a":"(ب) الذكاء الاصطناعي القابل للتفسير (XAI)","mcq":{"stem":"ما هو المصطلح الذي يصف التقنية التي تتيح للبشر فهم العوامل والسبب الذي أدى بالذكاء الاصطناعي إلى اتخاذ حكم معين؟","opts":["الحوسبة السحابية.","الذكاء الاصطناعي القابل للتفسير (XAI)","الحوسبة الطرفية.","التحيز الخوارزمي."],"correct":1}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما الفرق الأساسي بين «المسؤولية» و«المساءلة» كما تم توضيحه في الدرس؟","a":"(ب) المسؤولية تتعلق بتحديد أدوار وواجبات الأطراف ،بينما تعني المساءلة تحديد الجهات التي يمكن محاسبتها وفق أدوارها","mcq":{"stem":"ما الفرق الأساسي بين «المسؤولية» و«المساءلة» كما تم توضيحه في الدرس؟","opts":["المسؤولية تعني إظهار عملية اتخاذ القرار بينما المساءلة تعني سرعة المعالجة.","المسؤولية تتعلق بتحديد أدوار وواجبات الأطراف ،بينما تعني المساءلة تحديد الجهات التي يمكن محاسبتها وفق أدوارها","المساءلة هي التقنية التي تُفهم منطق الذكاء الاصطناعي بينما المسؤولية هي جمع البيانات.","لا يوجد أي فرق بينهما فهما مصطلحان مترادفا تماماً."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر المبادئ الأربعة الأساسية لأخلاقيات الذكاء الاصطناعي مع شرح مبدأ «العدالة» باختصار.","a":"المبادئ الأربعة الأساسية هي: العدالة. \\.الشفافية.\\. حماية الخصوصية.\\. المساءلة. العدالة:عدم التمييز ظلما ضد أي شخص أو مجموعة بعينها."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح المقصود بكل من مبدأ «الشفافية» ومبدأ «حماية الخصوصية» في إطار الاستخدام المسؤول للذكاء الاصطناعي.","a":"الشفافية: إتاحة معلومات واضحة ومناسبة عن النظام واستخدامه وعملية اتخاذ القرار وحدوده. حماية الخصوصية: التعامل مع المعلومات الشخصية بشكل مناسب وحماية الخصوصية."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"من بين المبادئ الأساسية لأخلاقيات الذكاء الاصطناعي، ما هو المبدأ الذي يقتضي عدم التمييز ظلمًا ضد أي شخص أو مجموعة بعينها؟","a":"(ج) العدالة.","mcq":{"stem":"من بين المبادئ الأساسية لأخلاقيات الذكاء الاصطناعي، ما هو المبدأ الذي يقتضي عدم التمييز ظلمًا ضد أي شخص أو مجموعة بعينها؟","opts":["الشفافية.","المساءلة.","العدالة.","حماية الخصوصية."],"correct":2}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المبدأ الذي يشير إلى إتاحة معلومات واضحة ومناسبة عن النظام واستخدامه وعملية اتخاذ القرار وحدوده؟","a":"(ب) الشفافية.","mcq":{"stem":"ما هو المبدأ الذي يشير إلى إتاحة معلومات واضحة ومناسبة عن النظام واستخدامه وعملية اتخاذ القرار وحدوده؟","opts":["العدالة.","الشفافية.","حماية الخصوصية.","المسؤولية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح ماهية «التحيز الخوارزمي» في أنظمة الذكاء الاصطناعي مبينا كيف ينشأ من بيانات التدريب أو تصميم النظام وطريقة استخدامه مع ذكر أمثلة.","a":"التحيز الخوارزمي: نمط أو انحراف في مخرجات الذكاء الاصطناعي قد يؤدي إلى نتائج غير عادلة أو ضارة. ويمكن أن ينشأ بسبب بيانات تدريب متحيزة، مثل بيانات غير كافية عن سمات معينة أو نزعات تمييزية سابقة؛ أو من تصميم النظام، مثل الاختيار غير المناسب للمتغيرات أو استخدام متغير بديل يمثل سمة محمية بشكل غير مباشر؛ أو من طريقة الاستخدام والسياق البشري والاجتماعي. مثال: نظام توظيف يفضل فئة بصورة غير عادلة، أو نظام للتعرف على الوجه تقلّ دقته مع فئات معينة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تكلم بالتفصيل عن «الذكاء الاصطناعي القابل للتفسير (XAI)» ومشكلة «الصندوق الأسود» وكيف يسافهمي تقييم النظام واكتشاف الأخطاء؟","a":"الذكاء الاصطناعي القابل للتفسير (XAI): أساليب تساعد البشر على فهم العوامل التي أسهمت في وصول النظام إلى مخرج أو قرار معين. مشكلة الصندوق الأسود: تكون آلية الوصول إلى النتيجة غير واضحة، فيصعب تقييمها واكتشاف الأخطاء أو التحيز.ويساعد الذكاء الاصطناعي القابل للتفسير على توضيح العوامل المؤثرة في المخرج؛ ومن ثم دعم فهم النظام وتقييم نتائجه واكتشاف الأخطاء أو التحيز."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"قارن بدقة بين مفهوم «المسؤولية» ومفهوم «المساءلة» موضحًا سبب اختلاف توزيع المسؤولية باختلاف السياقات والأطراف (المطور، المشغل، المستخدم)؟","a":"المسؤولية (Responsibility): تحديد أدوار وواجبات الأطراف المرتبطة بتطوير النظام وتشغيله واستخدامه، مثل المطور والجهة والمستخدم. ويختلف توزيع المسؤولية باختلاف النظام والاستخدام والقواعد المعمول بها. المساءلة (Accountability): تحديد الجهات المسؤولة عن النظام وقراراته وآثاره، وإمكان محاسبتها وفق أدوارها. والمساءلة لا تعني مجرد شرح القرار بل من حاسب على النتيجة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر المبادئ الأربعة الأساسية لأخلاقيات الذكاء الاصطناعي واشرح باختصار المقصود بكل من «العدالة«»، الشفافية«»، حماية الخصوصية»، و«المساءلة»","a":" العدالة: عدم التمييز ظلما ضد أي شخص أو مجموعة بعينها  الشفافية: إتاحة معلومات واضحة ومناسبة عن النظام واستخدامه وعملية اتخاذ القرار وحدوده.  حماية الخصوصية: التعامل مع المعلومات الشخصية بشكل مناسب وحماية الخصوصية  المساءلة: تحديد الجهات المسؤولة عن النظام وقراراته وآثاره وإمكان محاسبتها وفق أدوارها."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"نمط في مخرجات الذكاء الاصطناعي قد يؤدي إلى نتائج غير عادلة أو ضارة، وينشأ من البيانات أو التصميم يسمى:","a":"(ب) التحيز الخوارزمي.","mcq":{"stem":"نمط في مخرجات الذكاء الاصطناعي قد يؤدي إلى نتائج غير عادلة أو ضارة، وينشأ من البيانات أو التصميم يسمى:","opts":["الذكاء الاصطناعي القابل للتفسير (XAI).","التحيز الخوارزمي.","الشفافية المطلقة.","حماية الخصوصية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تقنية تتيح للبشر فهم سبب اتخاذ الذكاء الاصطناعي حكمًا معيّنًا وتساعد على تجنب مشكلة الصندوق الأسود هي:","a":"(أ) الذكاء الاصطناعي القابل للتفسير (XAI)","mcq":{"stem":"تقنية تتيح للبشر فهم سبب اتخاذ الذكاء الاصطناعي حكمًا معيّنًا وتساعد على تجنب مشكلة الصندوق الأسود هي:","opts":["الذكاء الاصطناعي القابل للتفسير (XAI)","الحوسبة الطرفية.","بيانات التدريب.","التحيز الخوارزمي."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"المبدأ الذي يعني التعامل مع المعلومات الشخصية بشكل مناسب وحمايتها هو:","a":"(ج) حماية الخصوصية","mcq":{"stem":"المبدأ الذي يعني التعامل مع المعلومات الشخصية بشكل مناسب وحمايتها هو:","opts":["العدالة","الشفافية","حماية الخصوصية","المساءلة"],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تحديد الجهات المسؤولة عن النظام وقراراته وآثاره وإمكان محاسبتها وفق أدوارها يمثل مبدأ:","a":"(ج) المساءلة","mcq":{"stem":"تحديد الجهات المسؤولة عن النظام وقراراته وآثاره وإمكان محاسبتها وفق أدوارها يمثل مبدأ:","opts":["الشفافية","العدالة","المساءلة","حماية الخصوصية"],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح كيف يمكن أن تؤدي بيانات التدريب غير الممثلة أو المتحيزة (مثل انعكاس نزعات تمييزية سابقة) إلى تكرار الذكاء الاصطناعي لهذا التحيز في أحكامه.","a":"بيانات التدريب هي الأمثلة التي يتعلم منها نظام الذكاء الاصطناعي أنماطه قبل استخدامه. وكلما قل تمثيلها للواقع زاد احتمال تحيز مخرجاته؛ لذلك يمكن أن تؤدي بيانات التدريب المتحيزة أو غير الممثلة، مثل البيانات التي تعكس نزعات تمييزية سابقة، إلى تكرار هذا التحيز في أحكام النظام وظهور نتائج غير عادلة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح مشكلة «الصندوق الأسود» في خوارزميات الذكاء الاصطناعي المعقدة ولماذا يجعل تقييم الآلية واكتشاف الأخطاء أمرا صعبا دون استخدام تقنيات التفسير.","a":"تظهر مشكلة الصندوق الأسود عندما تكون آلية وصول نظام الذكاء الاصطناعي إلى النتيجة غير واضحة.وعندئذ يصعب تقييم النتيجة واكتشاف الأخطاء أو التحيز. وتساعد أساليب الذكاء الاصطناعي القابل للتفسير (XAI) البشر على فهم العوامل التي أسهمت في الوصول إلى مخرج أو قرار معين."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر قضايا الخصوصية المرتبطة بانتشار تقنيات التعرف على الوجه في الأماكن العامة والجمع الجماعي للبيانات والسلوك عبر الإنترنت.","a":"وهذه من القضايا الجديدة المتعلقة بالخصوصية التي ظهرت مع تطور الذكاء الاصطناعي."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بالتفصيل المبادئ الأربعة الأساسية لأخلاقيات الذكاء الاصطناعي وكيف يوجه كل منها الاستخدام المسؤول لهذه التقنيات في المجتمع.","a":"يركز الدرس على أربعة مبادئ مهمة للاستخدام المسؤول للذكاء الاصطناعي:  العدالة: عدم التمييز ظلما ضد أي شخص أو مجموعة بعينها. . الشفافية: إتاحة معلومات واضحة ومناسبة عن النظام واستخدامه وعملية اتخاذ القرار وحدوده . حماية الخصوصية: التعامل مع المعلومات الشخصية بشكل مناسب وحماية الخصوصية. . المساءلة: تحديد الجهات المسؤولة عن النظام وقراراته وآثاره، وإمكان محاسبتها وفق أدوارها."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الأمثلة التي يتعلم منها نظام الذكاء الاصطناعي أنماطه قبل استخدامه وتؤثر بشكل مباشر على جودة مخرجاته تسمى:","a":"(أ) بيانات التدريب.","mcq":{"stem":"الأمثلة التي يتعلم منها نظام الذكاء الاصطناعي أنماطه قبل استخدامه وتؤثر بشكل مباشر على جودة مخرجاته تسمى:","opts":["بيانات التدريب.","خوارزميات التشفير.","الأجهزة الطرفية.","الذاكرة العشوائية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"إتاحة معلومات واضحة ومناسبة عن النظام واستخدامه وعملية اتخاذ القرار وحدوده يعد تعريفا","a":"(ب) الشفافية.","mcq":{"stem":"إتاحة معلومات واضحة ومناسبة عن النظام واستخدامه وعملية اتخاذ القرار وحدوده يعد تعريفا","opts":["العدالة.","الشفافية.","المساءلة.","حماية الخصوصية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"عدم التمييز ظلمًا ضد أي شخص أو مجموعة بعينها في أحكام ومخرجات الذكاء الاصطناعي يمثل مبدأ:","a":"(أ) العدالة.","mcq":{"stem":"عدم التمييز ظلمًا ضد أي شخص أو مجموعة بعينها في أحكام ومخرجات الذكاء الاصطناعي يمثل مبدأ:","opts":["العدالة.","الشفافية.","حماية الخصوصية.","المساءلة."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الأسلوب أو التقنية التي تساعد البشر على فهم العوامل التي أسهمت في وصول النظام إلى مخرج أو قرار مع ين هي:","a":"(ب) الذكاء الاصطناعي القابل للتفسير (XAI)","mcq":{"stem":"الأسلوب أو التقنية التي تساعد البشر على فهم العوامل التي أسهمت في وصول النظام إلى مخرج أو قرار مع ين هي:","opts":["التحيز الخوارزمي.","الذكاء الاصطناعي القابل للتفسير (XAI)","الجمع الجماعي للبيانات.","تدقيق الشبكات."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش أسباب التحيز الخوارزمي وكيف يمكن أن ينشأ من الختيار غير المناسب للمتغيرات، أو استخدام متغير بديل يمثل بشكل غير مباشر سمة محمية؟","a":"قد ينشأ التحيز الخوارزمي من بيانات تدريب متحيزة، مثل نقص البيانات عن سمات معينة أو انعكاس نزعات تمييزية سابقة فيها.كما يمكن أن يدخل التحيز من خلال طريقة بناء النظام، بسبب الختيار غير المناسب للمتغيرات، أو اختيار متغير بديل يمثل بشكل غير مباشر سمة محمية، أو من تصميم النموذج نفسه.ويمكن أن تسهم طريقة استخدام النظام والسياق البشري والاجتماعي في ظهور نتائج غير عادلة أو ضارة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"بيّن أهمية «الذكاء الاصطناعي القابل للتفسير (XAI)» في معالجة صعوبة تقييم آلية الوصول إلى النتيجة عندما تكون غير واضحة للعين البشرية؟","a":"يساعد الذكاء الاصطناعي القابل للتفسير (XAI) البشر على فهم العوامل التي أسهمت في وصول النظام إلى مخرج أو قرار معين؛ لأن غموض آلية الوصول إلى النتيجة يجعل تقييمها واكتشاف الأخطاء أو التحيز أمرا صعبا."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح الأبعاد المختلفة لمسؤولية الأطراف المتعددة (المطور الشركة المشغلة، المستخدم) عند اتخاذ نظام الذكاء الاصطناعي حكمًا خاطئًا أو غير عادل.","a":"المسؤولية: تعني تحديد أدوار وواجبات الأطراف المرتبطة بتطوير النظام وتشغيله واستخدامه، ومنها المطور والجهة المشغلة والمستخدم ولا يوجد توزيع واحد للمسؤولية يصلح لكل السياقات؛ لأن توزيعه يختلف باختلاف النظام والاستخدام والقواعد المعمول بها. أما المساءلة فتعني تحديد الجهات المسؤولة عن النظام وقراراته وآثاره وإمكان محاسبتها وفق أدوارها عندما ينتج حكم خاطئ أو غير عادل."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف تتكامل المبادئ الأربعة لأخلاقيات الذكاء الاصطناعي (العدالة، الشفافية، حماية الخصوصية، المساءلة) لتشكيل إطار متكامل للاستخدام المسؤول.","a":"المبادئ الأربعة بوصفها مبادئ مهمة للاستخدام المسؤول للذكاء الاصطناعي: العدالة: عدم التمييز ظلما ضد أي شخص أو مجموعة الشفافية: إتاحة معلومات واضحة عن النظام واستخدامه وعملية اتخاذ القرار وحدوده. حماية الخصوصية: التعامل المناسب مع المعلومات الشخصية وحمايتها. المساءلة: تحديد الجهات المسؤولة عن النظام وقراراته وآثاره وإمكان محاسبتها. الاستخدام المسؤول يعني التحقق من التحيز، والقدرة على شرح القرارات ومعرفة من المسؤول، والاسترشاد بهذه المبادئ الأربعة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تحديد أدوار وواجبات الأطراف المرتبطة بتطوير النظام وتشغيله واستخدامه (المطور، المشغل، المستخدم) يشير إلى مصطلح:","a":"(أ) المسؤولية.","mcq":{"stem":"تحديد أدوار وواجبات الأطراف المرتبطة بتطوير النظام وتشغيله واستخدامه (المطور، المشغل، المستخدم) يشير إلى مصطلح:","opts":["المسؤولية.","التحيز الخوارزمي.","بيانات التدريب.","الشفافية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"نظام أو تقنية تجمع كميات كبيرة من بيانات السلوك عبر الإنترنت وتسمح بتتبع الأفراد في الأماكن العامة تثير قضايا تتعلق ب:","a":"(ب) حماية الخصوصية","mcq":{"stem":"نظام أو تقنية تجمع كميات كبيرة من بيانات السلوك عبر الإنترنت وتسمح بتتبع الأفراد في الأماكن العامة تثير قضايا تتعلق ب:","opts":["سرعة المعالجة الحاسوبية.","حماية الخصوصية","كفاءة الذاكرة المركزية.","قانون مور."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي الخيارات الآتية يمثل الوصف الدقيق لمبدأ «المساءلة»؟","a":"(ج) تحديد الجهات المسؤولة عن النظام وقراراته وإمكان محاسبتها وفق أدوارها.","mcq":{"stem":"أي الخيارات الآتية يمثل الوصف الدقيق لمبدأ «المساءلة»؟","opts":["إتاحة معلومات واضحة عن النظام وحدوده.","عدم التمييز ظلمًا ضد أي شخص أو مجموعة.","تحديد الجهات المسؤولة عن النظام وقراراته وإمكان محاسبتها وفق أدوارها.","فهم العوامل التي أسهمت في وصول النظام إلى مخرج معين."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يعد مثالا واضحا على التحيز في أنظمة الذكاء الاصطناعي؟","a":"(أ) نظام توظيف يفضل فئة بصورة غير عادلة أو نظام تعرف على الوجه تقل دقته مع فئات معينة.","mcq":{"stem":"أي من الخيارات التالية يعد مثالا واضحا على التحيز في أنظمة الذكاء الاصطناعي؟","opts":["نظام توظيف يفضل فئة بصورة غير عادلة أو نظام تعرف على الوجه تقل دقته مع فئات معينة.","برنامج لتنظيم المجلدات والملفات الشخصية على الحاسوب المحلي.","تطبيق لحساب العمليات الرياضية البسيطة والعمليات الهندسية.","أداة لتعديل صور المناظر الطبيعية وتحسين إضاءتها."],"correct":0}}],"2-1":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح كيف تعمل اتصالات HTTPS على حماية الاتصال، وما دور بروتوكول TLS في ذلك؟","a":"HTTPS هو بروتوكول HTTP يعمل عبر اتصال TLS مؤمن. يوفر TLS سرية البيانات وسلامتها أثناء النقل، ويساعد المتصفح على التحقق من هوية الخادم واسم النطاق. تبدأ العملية بمصافحة TLS للتحقق من الشهادة والاتفاق على أسرار مشتركة تشتق منها مفاتيح الجلسة، ثم يستخدم التشفير المتماثل لحماية بيانات الجلسة بكفاءة."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"ميز بين دور كل من التشفير المتماثل والتشفير بالمفتاح العام أثناء تدفق اتصال HTTPS؟","a":"التشفير بالمفتاح العام وآلياته: يُستخدم أثناء مصافحة TLS للمصادقة والاتفاق الآمن على مفاتيح الجلسة. التشفير المتماثل: يُستخدم بعد إنشاء مفاتيح الجلسة لحماية بيانات الاتصال بسرعة وكفاءة."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من التقنيات التالية يستخدم أساسا لتشفير بيانات الجلسة بسرعة وكفاءة عالية بعد اكتمال عملية المصافحة واتفاق الأمان؟","a":"(ب) التشفير المتماثل.","mcq":{"stem":"أي من التقنيات التالية يستخدم أساسا لتشفير بيانات الجلسة بسرعة وكفاءة عالية بعد اكتمال عملية المصافحة واتفاق الأمان؟","opts":["التشفير بالمفتاح العام.","التشفير المتماثل.","التوقيع الرقمي.","الشهادة الرقمية."],"correct":1}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ماذا تسمى الخطوات الخاصة بإنشاء الاتصال الآمن والتحقق من هوية الخادم واسم النطاق عبر بروتوكول HTTPS؟","a":"(أ) مصافحة TLS.","mcq":{"stem":"ماذا تسمى الخطوات الخاصة بإنشاء الاتصال الآمن والتحقق من هوية الخادم واسم النطاق عبر بروتوكول HTTPS؟","opts":["مصافحة TLS.","التوقيع الرقمي.","المصادقة الثنائية.","التشفير المتماثل."],"correct":0}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما المقصود بمصطلح «المصادقة الثنائية (2FA)»، وكيف يقلل استخدام عامل ثان مستقل من مخاطر الدخول غير المصرح به؟","a":"المصادقة الثنائية (2FA) هي استخدام عاملين مستقلين من فئتين مختلفتين لإثبات الهوية؛ ويقلل العامل الثاني المستقل احتمال الدخول غير المصرح به إذا كُشفت كلمة المرور؛ إذ قد يُطلب بعد إدخالها رمز من تطبيق مصادقة أو جهاز يملكه المستخدم، وعندئذ لن تكفي معرفة كلمة المرور وحدها للدخول."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر الفروق الأساسية بين المصادقة الثنائية (2FA) والمصادقة متعددة العوامل (MFA) من حيث عدد وفئات العوامل المستخدمة؟","a":"المصادقة الثنائية: تستخدم عاملين مستقلين من فئتين مختلفتين لإثبات الهوية. المصادقة متعددة العوامل (MFA): تستخدم عاملين أو أكثر من فئات مختلفة؛ مثل المعرفة والحيازة والسمات الحيوية."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يمثل عاملين من فئتين مختلفتين تماما (المعرفة والحيازة) يستخدمان في المصادقة الثنائية للخدمات المصرفية؟","a":"(ب) كلمة مرور + كلمة مرور لمرة واحدة (OTP).","mcq":{"stem":"أي من الخيارات التالية يمثل عاملين من فئتين مختلفتين تماما (المعرفة والحيازة) يستخدمان في المصادقة الثنائية للخدمات المصرفية؟","opts":["كلمة مرور + كلمة مرور ثانية نصية.","كلمة مرور + كلمة مرور لمرة واحدة (OTP).","بصمة الإصبع + التعرف على الوجه.","بطاقة هوية ورقية + اسم المستخدم فقط."],"correct":1}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يقصد بمصطلح «المصادقة متعددة العوامل (MFA)»؟","a":"(ب) استخدام عاملين أو أكثر من فئات مختلفة مثل المعرفة والحيازة والسمات الحيوية.","mcq":{"stem":"ماذا يقصد بمصطلح «المصادقة متعددة العوامل (MFA)»؟","opts":["استخدام كلمة مرور واحدة قوية ومعقدة للغاية.","استخدام عاملين أو أكثر من فئات مختلفة مثل المعرفة والحيازة والسمات الحيوية.","الاعتماد حصرًا على بصمة الإصبع فقط لتسجيل الدخول.","استخدام عنوان البريد الإلكتروني مع كلمة المرور التقليدية."],"correct":1}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"ما الدور الأساسي للشهادة الرقمية وآليات المفتاح العام في بدء اتصال TLS آمن؟","a":"أثناء مصافحة TLS يرسل الخادم شهادته الرقمية، ويتحقق المتصفح من صلاحيتها وسلسلة الثقة وملاءمتها لاسم الموقع، للمساعدة على التحقق من هوية الخادم. وفي المصافحة نفسها تستخدم آليات المفتاح العام للمصادقة والاتفاق الآمن على أسرار مشتركة تشتق منها مفاتيح الجلسة، ثم يستخدم التشفير المتماثل لحماية البيانات."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"قارن بإيجاز بين وظيفة التوقيع الرقمي ووظيفة الشهادة الرقمية في أنظمة الأمان.","a":"التوقيع الرقمي: يدعم التحقق من سلامة البيانات وهوية الموقع، ويكشف التلاعب وانتحال الشخصية، ويوفر دليلا يدعم عدم التنصل عندما يتطلب النظام ذلك. الشهادة الرقمية: تساعد المتصفح على التحقق من هوية الخادم وارتباط الشهادة باسم النطاق الذي يتصل به."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي التقنية التي تساعد المتصفح على التحقق من هوية الخادم وارتباط الشهادة باسم النطاق الذي يتصل به؟","a":"(ج) الشهادة الرقمية","mcq":{"stem":"ما هي التقنية التي تساعد المتصفح على التحقق من هوية الخادم وارتباط الشهادة باسم النطاق الذي يتصل به؟","opts":["التشفير المتماثل","التوقيع الرقمي","الشهادة الرقمية","المصادقة الثنائية"],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من التقنيات الآتية تكتشف التلاعب وانتحال الشخصية وتوفر دليلا يدعم عدم التنصل؟","a":"(ب) التوقيع الرقمي","mcq":{"stem":"أي من التقنيات الآتية تكتشف التلاعب وانتحال الشخصية وتوفر دليلا يدعم عدم التنصل؟","opts":["التشفير المتماثل","التوقيع الرقمي","مصافحة TLS.","المصادقة الثنائية"],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح باختصار كيف يتم الجمع بين تقنيات الأمان المختلفة (التشفير، الشهادات، المصادقة الثنائية) عند إتمام عملية شراء عبر متجر إلكتروني.","a":"عند الدخول إلى الموقع يبدأ اتصال HTTPS ويحمي التشفير محتوى الاتصال من قراءة طرف ثالث.ويتحقق المتصفح من الشهادة الرقمية واسم النطاق للتأكد من هوية الخادم.وعند تسجيل الدخول تقلل المصادقة الثنائية (2FA) احتمال الدخول غير المصرح به باستخدام عاملين مستقلين. وعند إرسال تفاصيل الطلب يحمي TLS سرية البيانات وسلامتها أثناء النقل."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"لماذا لا يكتفى بتقنية أمان واحدة فقط لضمان حماية الخدمات والاتصالات عبر الإنترنت، وما هي الفائدة العملية لتعدد الطبقات؟","a":"لأن كل تقنية تؤدي وظيفة مختلفة؛ فالتشفير يمنع قراءة محتوى الاتصال من أطراف ثلاثة، والشهادات الرقمية تساعد على التحقق من هوية الخادم، والمصادقة الثنائية تقلل احتمال الدخول غير المصرح به، والتوقيع الرقمي يدعم التحقق من سلامة البيانات وهوية الموقع وعدم التنصل عند الحاجة. والجمع بين التقنيات يقلل مخاطر التنصت والتلاعب وانتحال الهوية، دون افتراض حماية مطلقة."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التقنيات التالية تمنع قراءة محتوى الاتصال من قبل أطراف ثلاثة أثناء نقل البيانات عبر الشبكة؟","a":"(أ) التشفير (بالمفتاح المتماثل والمفتاح العام).","mcq":{"stem":"أي من التقنيات التالية تمنع قراءة محتوى الاتصال من قبل أطراف ثلاثة أثناء نقل البيانات عبر الشبكة؟","opts":["التشفير (بالمفتاح المتماثل والمفتاح العام).","التوقيع الرقمي.","المصادقة الثنائية (2FA).","الشهادة الرقمية."],"correct":0}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"بين الخيارات التالية، أي خيار يعد مثالا خاطئا للمصادقة الثنائية لأنه يعتمد على نفس فئة العامل (المعرفة)؟","a":"(ج) كلمة مرور + كلمة مرور سرية ثانية.","mcq":{"stem":"بين الخيارات التالية، أي خيار يعد مثالا خاطئا للمصادقة الثنائية لأنه يعتمد على نفس فئة العامل (المعرفة)؟","opts":["كلمة مرور + كلمة مرور لمرة واحدة ترسل للهاتف.","كلمة مرور + بصمة الإصبع.","كلمة مرور + كلمة مرور سرية ثانية.","كلمة مرور + رمز من تطبيق مصادقة."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بالتفصيل كيف تستخدم اتصالات HTTPS تقنيات مختلفة لحماية الاتصال منذ لحظة بدء المصافحة وحتى تبادل البيانات.","a":"- التحقق من الشهادة: أثناء مصافحة TLS يرسل الخادم شهادته الرقمية، ويتحقق المتصفح من صلاحيتها وسلسلة الثقة وملاءمتها لاسم الموقع. - الاتفاق على مفاتيح الجلسة: أثناء المصافحة تستخدم آليات المفتاح العام المناسبة للاتفاق على أسرار مشتركة تشتق منها مفاتيح الجلسة، دون إرسال مفتاح الجلسة نفسه عبر الشبكة. - تبادل البيانات: تحمى بيانات الجلسة بالتشفير المتماثل وآليات سلامة البيانات بسرعة وكفاءة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ميز بدقة بين دور التشفير المتماثل والتشفير بالمفتاح العام، موضحًا سبب استخدام كل منهما في مراحل اتصال HTTPS.","a":"التشفير بالمفتاح العام: يستخدم زوجا من المفاتيح المرتبطة، مفتاحا عاما ومفتاحا خاصا؛ وتستخدم آلياته في مصافحة TLS للمصادقة والاتفاق الآمن على مفاتيح الجلسة. التشفير المتماثل: يستخدم بعد إنشاء مفاتيح الجلسة لحماية بياناتها بسرعة وكفاءة؛ لأن تشفير جميع البيانات بالمفتاح العام سيكون أبطأ."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح بمثال عملي كيف تستخدم المصادقة الثنائية في تسجيل الدخول إلى حسابات وسائل التواصل الاجتماعي أو الخدمات المصرفية.","a":"في الخدمات المصرفية عبر الإنترنت:تستخدم كلمة المرور (عامل المعرفة) مع كلمة مرور لمرة واحدة (عامل الحيازة) في وسائل التواصل الاجتماعي:تستخدم كلمة المرور (المعرفة) مع المصادقة عبر الرسائل القصيرة (SMS الحيازة) وهكذا لا تكفي معرفة كلمة المرور وحدها للدخول إذا كشفت."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش العبارة التالية:«يعتمد الاتصال والخدمات الآمنة عبر الإنترنت على الجمع بين التشفير والمصادقة، وليس على تقنية واحدة فقط»، مبينًا دور كل تقنية مجتمعة.","a":"يعتمد أمان الاتصال والخدمات على الجمع بين تقنيات متعددة؛ فالتشفير يحمي محتوى الاتصال، والشهادة الرقمية تساعد على التحقق من هوية الخادم واسم النطاق، والمصادقة الثنائية تقلل احتمال الدخول غير المصرح به، والتوقيع الرقمي يدعم سلامة البيانات وهوية الموقع وعدم التنصل عند الحاجة. يقلل الجمع بينها مخاطر التنصت والتلاعب وانتحال الهوية دون ضمان حماية مطلقة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"بروتوكول HTTP المنقول عبر اتصال مؤمن يوفر سرية البيانات وسلامتها أثناء النقل يعرف ب:","a":"(أ) HTTPS","mcq":{"stem":"بروتوكول HTTP المنقول عبر اتصال مؤمن يوفر سرية البيانات وسلامتها أثناء النقل يعرف ب:","opts":["HTTPS","FTP","SMTP","DNS"],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"استخدام عاملين مستقلين من فئتين مختلفتين لإثبات الهوية يعرف ب:","a":"(ب) المصادقة الثنائية (2FA)","mcq":{"stem":"استخدام عاملين مستقلين من فئتين مختلفتين لإثبات الهوية يعرف ب:","opts":["التشفير المتماثل.","المصادقة الثنائية (2FA)","التوقيع الرقمي.","الشهادة الرقمية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تقنية تكتشف التلاعب وانتحال الشخصية وتوفر دليلا يدعم عدم التنصل هي","a":"(أ) التوقيع الرقمي.","mcq":{"stem":"تقنية تكتشف التلاعب وانتحال الشخصية وتوفر دليلا يدعم عدم التنصل هي","opts":["التوقيع الرقمي.","التشفير بالمفتاح العام.","مصافحة TLS.","الحوسبة السحابية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يمثل فئات عوامل المصادقة متعددة العوامل (MFA) بدقة؟","a":"(أ) المعرفة والحيازة والسمات الحيوية.","mcq":{"stem":"أي من الخيارات التالية يمثل فئات عوامل المصادقة متعددة العوامل (MFA) بدقة؟","opts":["المعرفة والحيازة والسمات الحيوية.","السرعة والكفاءة والتكلفة.","المفتاح العام والمفتاح الخاص وكلمة المرور.","الاتصال اللاسلكي والشبكة المحلية والسحابة."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح الخطوات الأساسية التي تحدث خلال «مصافحة TLS»، وكيف يتحقق المتصفح من شهادة الخادم.","a":"عند بدء اتصال HTTPS تحدث مصافحة TLS: 1 - يرسل الخادم شهادته الرقمية ويتحقق المتصفح من صلاحيتها وسلسلة الثقة وملاءمتها لاسم الموقع. - يتبادل الطرفان معاملات تبادل المفاتيح ويشتقان أسرارا مشتركة تنشأ منها مفاتيح الجلسة، دون إرسال المفتاح نفسه عبر الشبكة. - بعد المصافحة تحمى بيانات الجلسة بالتشفير المتماثل وآليات سلامة البيانات."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح لماذا يكون استخدام التشفير بالمفتاح العام لجميع البيانات المتبادلة بطيئا، وكيف يعالج بروتوكول TLS هذه المشكلة باستخدام مفاتيح الجلسة.","a":"أن تبادل جميع البيانات باستخدام التشفير بالمفتاح العام سيكون بطيئا.لذلك تستخدم مصافحة TLS آليات ال مفتاح العام للمصادقة والاتفاق الآمن على مفاتيح الجلسة، ثم تستخدم مفاتيح الجلسة والتشفير المتماثل لحماية البيانات بسرعة وكفاءة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"قارن بين فئات عوامل المصادقة المختلفة (المعرفة، الحيازة، السمات الحيوية) مع ذكر مثال لكل فئة منها.","a":"المعرفة:مثل كلمة المرور. الحيازة:مثل كلمة مرور لمرة واحدة، أو مصادقة عبر الرسائل القصيرة، SMS أو بطاقة دخول. السمات الحيوية:مثل بصمة الإصبع أو التعرف على الوجه ويستخدم النظام في المصادقة الثنائية عاملين مستقلين من فئتين مختلفتين."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يمنع استخدام عامل ثان مستقل (مثل تطبيق المصادقة أو رمز الرسائل القصيرة) اختراق الحساب حتى لو تسربت كلمة المرور الأساسية.","a":"يقلل العامل الثاني المستقل احتمال الدخول غير المصرح به عند كشف كلمة المرور؛ فبعد إدخال كلمة المرور قد يطلب النظام رمزا من تطبيق مصادقة أو جهاز يملكه المستخدم، أو عبر رسائل SMS كما في أمثلة الكتاب. لذلك لا تكفي معرفة كلمة المرور وحدها للدخول."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"زوج من المفاتيح المرتبطة يتكون من مفتاح عام ومفتاح خاص يستخدم في التشفير لتأمين الاتصال هو:","a":"(أ) التشفير بالمفتاح العام.","mcq":{"stem":"زوج من المفاتيح المرتبطة يتكون من مفتاح عام ومفتاح خاص يستخدم في التشفير لتأمين الاتصال هو:","opts":["التشفير بالمفتاح العام.","التشفير المتماثل.","الكيوبت الكمومي.","البت الكلاسيكي."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"نظام أو خدمة يساعد المتصفح على التحقق من هوية الخادم ومن مطابقة اسم النطاق للشهادة الرقمية هو:","a":"(ب) الشهادة الرقمية.","mcq":{"stem":"نظام أو خدمة يساعد المتصفح على التحقق من هوية الخادم ومن مطابقة اسم النطاق للشهادة الرقمية هو:","opts":["التوقيع الرقمي.","الشهادة الرقمية.","التشفير المتماثل.","المصادقة الثنائية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يعد مثالا صحيحا لعامل «الحيازة» في المصادقة الثنائية؟","a":"(ب) كلمة مرور لمرة واحدة مرسلة للهاتف أو بطاقة ذكية.","mcq":{"stem":"أي من الخيارات التالية يعد مثالا صحيحا لعامل «الحيازة» في المصادقة الثنائية؟","opts":["معرفة السؤال السري.","كلمة مرور لمرة واحدة مرسلة للهاتف أو بطاقة ذكية.","بصمة الإصبع الخاصة بالمستخدم.","التعرف على ملامح الوجه."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي تركيبات تقنيات الأمان في المتاجر الإلكترونية تضمن حماية التسجيل والدفع؟","a":"(ب) الجمع بين التشفير والشهادات والتوقيعات والمصادقة الثنائية لتقليل المخاطر المتعددة.","mcq":{"stem":"أي تركيبات تقنيات الأمان في المتاجر الإلكترونية تضمن حماية التسجيل والدفع؟","opts":["الاعتماد على تقنية واحدة فقط لسرعة التنفيذ.","الجمع بين التشفير والشهادات والتوقيعات والمصادقة الثنائية لتقليل المخاطر المتعددة.","إلغاء استخدام كلمات المرور نهائيًا.","الاكتفاء بالتشفير المتماثل دون أي مصادقة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بالتفصيل كيف تساهم الشهادات الرقمية وسلسلة الثقة في تمكين المتصفح من التحقق من صحة الخادم وملاءمة اسم الموقع.","a":"خلال مصافحة TLS يرسل الخادم شهادته الرقمية إلى المتصفح. ويتحقق المتصفح من صلاحية الشهادة وسلسلة الثقة وملاءمتها لاسم الموقع، وبذلك تساعد الشهادة الرقمية على التحقق من هوية الخادم وارتباط الشهادة باسم النطاق الذي يتصل به."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تكلم باختصار عن التوقيع الرقمي مبينًا خصائصه، وكيف يساعد في اكتشاف التلاعب وانتحال الشخصية وتوفير دليل عدم التنصل.","a":"يدعم التوقيع الرقمي التحقق من سلامة البيانات وهوية الموقع، ويساعد على كشف التلاعب وانتحال الشخصية، ويوفر دليلا يدعم عدم التنصل. ويستخدم لإثبات التوقيع على بيانات أو رسائل محددة عندما يتطلب النظام ذلك."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما هي الفوائد الأمنية الناتجة عن جمع عدة تقنيات أمان (التشفير، التوقيعات، الشهادات المصادقة الثنائية) في سياق الخدمات المصرفية والتسوق الإلكتروني؟","a":"يساعد الجمع بين تقنيات الأمان في معالجة مخاطر مختلفة: التشفير يمنع قراءة محتوى الاتصال من أطراف ثلاثة، والتوقيع الرقمي يدعم التحقق من سلامة البيانات وهوية الموقع وعدم التنصل عند الحاجة، والشهادة الرقمية تساعد في التحقق من هوية الخادم واسم النطاق، والمصادقة الثنائية تقلل احتمال الدخول غير المصرح به. وبذلك تتراجع مخاطر التنصت والتلاعب وانتحال الهوية."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش لماذا لا تعني وسائل الأمان المتقدمة مثل TLS والمصادقة الثنائية أن الحماية مطلقة أو أن الموقع موثوق المحتوى تماما.","a":"يوضح الكتاب أن TLS يحمي سرية البيانات وسلامتها أثناء النقل، ويتحقق المتصفح من شهادة الموقع واسم النطاق، وأن المصادقة الثنائية تقلل احتمال الدخول غير المصرح به. لكن هذه الوسائل لا تعني أن محتوى الموقع موثوق أو أن الحماية مطلقة؛ فهي تقلل المخاطر، ولا توجد تقنية تضمن منعها بالكامل."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"خطوات إنشاء الاتصال من لا والاتفاق على أسرار مشتركة تشتق منها مفاتيح الجلسة تسمى:","a":"(أ) مصافحة TLS.","mcq":{"stem":"خطوات إنشاء الاتصال من لا والاتفاق على أسرار مشتركة تشتق منها مفاتيح الجلسة تسمى:","opts":["مصافحة TLS.","التشفير المتماثل.","التوقيع الرقمي.","الشهادة الرقمية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"استخدام عاملين أو أكثر من فئات مختلفة لإثبات الهوية (مثل المعرفة والحيازة والسمات الحيوية) يسمى:","a":"(أ) المصادقة متعددة العوامل (MFA)","mcq":{"stem":"استخدام عاملين أو أكثر من فئات مختلفة لإثبات الهوية (مثل المعرفة والحيازة والسمات الحيوية) يسمى:","opts":["المصادقة متعددة العوامل (MFA)","التشفير بالمفتاح العام.","مصافحة TLS.","التشفير المتماثل."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي مما يلي يعد مثالا على عامل «السمات الحيوية» في المصادقة؟","a":"(ب) بصمة الإصبع أو التعرف على الوجه.","mcq":{"stem":"أي مما يلي يعد مثالا على عامل «السمات الحيوية» في المصادقة؟","opts":["كلمة المرور النصية.","بصمة الإصبع أو التعرف على الوجه.","بطاقة الصراف الآلي.","رمز التحقق عبر الرسائل القصيرة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الاتصال والخدمات الآمنة عبر الإنترنت تعتمد بشكل أساسي على:","a":"(ب) الجمع بين التشفير والمصادقة والشهادات والتوقيعات الرقمية.","mcq":{"stem":"الاتصال والخدمات الآمنة عبر الإنترنت تعتمد بشكل أساسي على:","opts":["تقنية واحدة فريدة ومطلقة.","الجمع بين التشفير والمصادقة والشهادات والتوقيعات الرقمية.","استخدام كلمات المرور البسيطة فقط","إلغاء استخدام المفاتيح العامة والخاصة."],"correct":1}}],"2-2":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح ما المقصود بمفهوم «الدفاع في العمق» في أمان الشبكات، ولماذا يعد توفير طبقات متعددة أضمن من الاعتماد على وسيلة حماية واحدة.","a":"الدفاع في العمق هو استخدام عدة طبقات مختلفة من الحماية بدل الاعتماد على وسيلة واحدة؛ فإذا فشلت إحدى الطبقات تساعد الطبقات الأخرى على تقليل الخطر والحد من أثر الاختراق."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح الدور الأساسي لجدار الحماية (Firewall) في أمان الشبكات، واذكر مثالًا على كيفية تحكمه في حركة المرور.","a":"جدار الحماية هو نظام أمني قد يكون جهازا أو برنامجا، يراقب حركة مرور الشبكة ويسمح بها أو يمنعها وفق قواعد أمنية محددة.مثال:يمكن السماح لخادم الويب بالوصول إلى قاعدة البيانات مع منع المستخدمين القادمين من الإنترنت من الوصول إليها مباشرة."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات التالية يعد التعريف الدقيق لمفهوم «الدفاع في العمق» في أمان الشبكات؟","a":"(ب) استخدام طبقات متعددة من الضوابط الأمنية بحيث تقلل الطبقات الأخرى الخطر إذا فشلت إحدى الطبقات.","mcq":{"stem":"أي من الخيارات التالية يعد التعريف الدقيق لمفهوم «الدفاع في العمق» في أمان الشبكات؟","opts":["الاعتماد الكامل على جدار حماية قوي عند حدود الشبكة.","استخدام طبقات متعددة من الضوابط الأمنية بحيث تقلل الطبقات الأخرى الخطر إذا فشلت إحدى الطبقات.","منح الثقة التلقائية لجميع الأجهزة الموجودة داخل النطاق الجغرافي للمؤسسة.","تشفير حركة المرور بالكامل حصريًا عند استخدام شبكات Wi-Fi العامة."],"correct":1}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هو المصطلح الذي يطلق على نظام أو برنامج يراقب حركة مرور الشبكة ويسمح بها أو يمنعها وفق قواعد أمنية محددة؟","a":"(ج) جدار الحماية.","mcq":{"stem":"ما هو المصطلح الذي يطلق على نظام أو برنامج يراقب حركة مرور الشبكة ويسمح بها أو يمنعها وفق قواعد أمنية محددة؟","opts":["الشبكة الافتراضية الخاصة.","المنطقة المعزولة.","جدار الحماية.","نهج انعدام الثقة."],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما المقصود بمصطلح «الشبكة الافتراضية الخاصة (VPN)»؟ اذكر اثنين من استخداماتها الرئيسية.","a":"الشبكة الافتراضية الخاصة (VPN) هي طريقة للاتصال بشكل آمن ومشفر عبر شبكة عامة مثل الإنترنت، وتستخدم التشفير وتقنيات النفق لحماية البيانات بين طرفين.ومن استخداماتها:الاتصال الآمن بشبكة المؤسسة من المنزل أو أثناء العمل عن بعد، وربط فروع المؤسسة الموجودة في مواقع مختلفة بأمان."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"لماذا يكون وضع خادم ويب عام في «المنطقة المعزولة (DMZ)» أكثر أمانًا من وضعه مباشرة داخل الشبكة الداخلية للمؤسسة؟","a":"لأن المنطقة المعزولة (DMZ) منطقة منفصلة عن الشبكة الداخلية توضع فيها الخوادم التي يحتاج الجمهور إلى الوصول إليها؛ فإذا تعرض الخادم لهجوم تقل احتمالية وصول الهجوم إلى الشبكة الداخلية والبيانات الحساسة."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يشير إلى اتصال أو شبكة منطقية خاصة تنشأ عبر شبكة عامة مثل الإنترنت وتستخدم التشفير لحماية البيانات؟","a":"(ب) الشبكة الافتراضية الخاصة (VPN)","mcq":{"stem":"ما هو المصطلح الذي يشير إلى اتصال أو شبكة منطقية خاصة تنشأ عبر شبكة عامة مثل الإنترنت وتستخدم التشفير لحماية البيانات؟","opts":["جدار الحماية.","الشبكة الافتراضية الخاصة (VPN)","المنطقة المعزولة (DMZ).","نهج انعدام الثقة."],"correct":1}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات الآتية يمثل الاستخدام الأنسب والأكثر شيوعًا للشبكة الافتراضية الخاصة (VPN) في بيئات العمل الحديثة؟","a":"(أ) الاتصال بأمان بشبكة المؤسسة من المنزل أو أثناء التنقل والعمل عن بعد.","mcq":{"stem":"أي من الخيارات الآتية يمثل الاستخدام الأنسب والأكثر شيوعًا للشبكة الافتراضية الخاصة (VPN) في بيئات العمل الحديثة؟","opts":["الاتصال بأمان بشبكة المؤسسة من المنزل أو أثناء التنقل والعمل عن بعد.","حماية الأجهزة الطرفية من الفيروسات وإزالتها تلقائيًا بدون برامج مساعدة.","مراقبة حركة مرور الشبكة المحلية ومنع البريد الإلكتروني العشوائي.","توفير منصات تتيح للمستخدمين نشر المحتوى ومشاركته بسرعة فائقة."],"correct":0}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح المقصود ب «المنطقة المعزولة (DMZ)» في تصاميم الشبكات، وكيف تحمي مكونات البنية التحتية الداخلية.","a":"المنطقة المعزولة (DMZ) هي منطقة شبكة منفصلة توضع فيها الخوادم المواجهة للجمهور مثل خادم الويب، وتكون معزولة عن الشبكة الداخلية؛ وبذلك تقل احتمالية انتقال أي هجوم على هذه الخوادم إلى الأنظمة والبيانات الداخلية الحساسة."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"قارن بإيجاز بين الأمن التقليدي و«نهج انعدام الثقة (Trust Zero)» من حيث التعامل مع مستخدمي الشبكة الداخلية.","a":"الأمن التقليدي يفترض غالبا أن ما يوجد داخل شبكة المؤسسة موثوق وما يوجد خارجها غير موثوق.أما نهج انعدام الثقة فلا يمنح الثقة تلقائيا لأي مستخدم أو جهاز لمجرد وجوده داخل الشبكة، بل يتحقق من الهوية والجهاز والصلاحيات والسياق عند كل طلب وصول."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ماذا يقصد بمصطلح «المنطقة المعزولة (DMZ)» في هيكلة أمان الشبكات؟","a":"(ب) منطقة توضع فيها الخوادم المعرضة للشبكة الخارجية بشكل منفصل عن الشبكة الداخلية للمؤسسة.","mcq":{"stem":"ماذا يقصد بمصطلح «المنطقة المعزولة (DMZ)» في هيكلة أمان الشبكات؟","opts":["شبكة عامة مفتوحة بالكامل تتيح للمخترقين الوصول إلى قواعد البيانات الحساسة.","منطقة توضع فيها الخوادم المعرضة للشبكة الخارجية بشكل منفصل عن الشبكة الداخلية للمؤسسة.","برمجية خبيثة تقوم بمراقبة حركة المرور وتعديل قواعد جدار الحماية تلقائيًا.","خط خاص افتراضي مشفر يربط بين الفروع المختلفة عبر الإنترنت العام."],"correct":1}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي الفرضية الأساسية التي يعتمد عليها «نهج انعدام الثقة (Zero Trust)» في تأمين موارد المؤسسة؟","a":"(ب) عدم منح الثقة تلقائيًا لمستخدم أو جهاز لمجرد وجوده داخل الشبكة أو ملكيته للمؤسسة وفحص الهوية والسياق.","mcq":{"stem":"ما هي الفرضية الأساسية التي يعتمد عليها «نهج انعدام الثقة (Zero Trust)» في تأمين موارد المؤسسة؟","opts":["اعتبار كل جهاز أو مستخدم داخل شبكة المؤسسة موثوقاً تماماً بشكل تلقائي.","عدم منح الثقة تلقائيًا لمستخدم أو جهاز لمجرد وجوده داخل الشبكة أو ملكيته للمؤسسة وفحص الهوية والسياق.","الاعتماد المطلق على المحيط الأمني الخارجي وعدم فحص التطبيقات الداخلية.","تشفير رسائل البريد الإلكتروني فقط دون الاهتمام بصلاحيات الوصول للبيانات."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف تغيرت الفرضيات الأمنية حول «المحيط الأمني» التقليدي في ظل انتشار الحوسبة السحابية والعمل عن بعد.","a":"كان المحيط الأمني التقليدي يفترض أن ما داخل شبكة المؤسسة موثوق وما خارجها غير موثوق، لكن مع انتشار الحوسبة السحابية والعمل عن بعد أصبحت البيانات والخدمات والمستخدمون موجودين داخل الشبكة وخارجها؛ لذلك لم تعد حدود الشبكة التقليدية وحدها كافية للحماية."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر أمثلة على الإجراءات الأمنية الأربعة المرتبطة بطبقات الدفاع في العمق (مدخل الشبكة، مسار الاتصال، وضع الخوادم، الأجهزة الطرفية)","a":"مدخل الشبكة:منع الاتصال غير المصرح به باستخدام جدار الحماية.مسار الاتصال:تشفير الاتصالات باستخدام VPN وضع الخوادم:فصل الخوادم المواجهة للجمهور عن الشبكة الداخلية باستخدام DMZ الأجهزة الطرفية:تحديث برامج مكافحة الفيروسات والحفاظ على تحديث نظام التشغيل."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المفهوم الذي يصف الحدود التقليدية التي تفترض أن ما بداخل شبكة المؤسسة آمن تمامًا وما خارجها غير آمن والتي طمستها الخدمات السحابية والعمل عن بعد؟","a":"(ب) المحيط الأمني.","mcq":{"stem":"ما هو المفهوم الذي يصف الحدود التقليدية التي تفترض أن ما بداخل شبكة المؤسسة آمن تمامًا وما خارجها غير آمن والتي طمستها الخدمات السحابية والعمل عن بعد؟","opts":["المنطقة المعزولة.","المحيط الأمني.","الحوسبة الطرفية.","التراكب الكمي."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من طبقات «الدفاع في العمق» التالية ترتبط ارتباطًا مباشرًا بتثبيت برامج مكافحة الفيروسات وتحديث نظام التشغيل؟","a":"(د) الأجهزة الطرفية.","mcq":{"stem":"أي من طبقات «الدفاع في العمق» التالية ترتبط ارتباطًا مباشرًا بتثبيت برامج مكافحة الفيروسات وتحديث نظام التشغيل؟","opts":["مدخل الشبكة.","مسار الاتصال.","وضع الخوادم.","الأجهزة الطرفية."],"correct":3}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بالتفصيل كيف يعمل «الدفاع في العمق» على حماية المؤسسة بشكل أفضل من الاعتماد على وسيلة حماية واحدة، مستعينًا بما يحدث عند اختراق أحد الدفاعات.","a":"يعتمد الدفاع في العمق على استخدام عدة طبقات من الإجراءات الأمنية.فإذا تم اختراق إحدى الطبقات، تساعد الطبقات الأخرى على تقليل الخطر والحد من أثر الاختراق؛ لذلك تكون الحماية أقوى من الاعتماد على وسيلة واحدة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح الدور التقني ل «جدار الحماية» في مراقبة حركة مرور الشبكة، ومثل على ذلك بحماية قواعد البيانات.","a":"يراقب جدار الحماية حركة المرور الداخلة والخارجة ويسمح بها أو يمنعها وفق قواعد محددة.مثال:يسمح لخادم الويب بالاتصال بقاعدة البيانات، ويمنع المستخدمين القادمين مباشرة من الإنترنت من الوصول إلى قاعدة البيانات الحساسة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر المفهوم التفصيلي ل «الشبكة الافتراضية الخاصة (VPN)» وبين كيف تحمي البيانات المنقولة عبر شبكات Wi-Fi العامة من التنصت.","a":"الشبكة الافتراضية الخاصة (VPN) تنشئ اتصال آمنا ومشفرا عبر شبكة عامة مثل الإنترنت باستخدام التشفير وتقنيات النفق. وعند استخدام Wi-Fi عامة تقوم بتشفير محتوى الاتصال، فيصعب على المهاجم قراءة البيانات حتى إذا اعترضها."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"قارن بالتفصيل بين الأمن التقليدي ونهج انعدام الثقة (Zero Trust) موضحًا سبب عدم كفاية التصاميم التقليدية وحدها أي حال.","a":"الأمن التقليدي يعتمد على فكرة أن ما داخل شبكة المؤسسة موثوق وما خارجها غير موثوق.أما Zero Trust فلا يمنح الثقة تلقائيا، بل يتحقق من كل طلب وصول ومن الهوية والجهاز والصلاحيات والسياق.ولم تعد الحدود التقليدية وحدها كافية بسبب انتشار الحوسبة السحابية والعمل عن بعد."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الأجهزة أو الأنظمة التالية يراقب حركة مرور الشبكة ويسمح بها أو يمنعها وفق قواعد أمنية محددة؟","a":"(أ) جدار الحماية.","mcq":{"stem":"أي من الأجهزة أو الأنظمة التالية يراقب حركة مرور الشبكة ويسمح بها أو يمنعها وفق قواعد أمنية محددة؟","opts":["جدار الحماية.","المنطقة المعزولة.","الشبكة الافتراضية الخاصة.","الحوسبة الطرفية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا تسمى المنطقة التي تعزل فيها الخوادم المواجهة للجمهور عن الشبكة الداخلية لتقليل أثر الهجمات؟","a":"(ب) المنطقة المعزولة (DMZ)","mcq":{"stem":"ماذا تسمى المنطقة التي تعزل فيها الخوادم المواجهة للجمهور عن الشبكة الداخلية لتقليل أثر الهجمات؟","opts":["المحيط الأمني.","المنطقة المعزولة (DMZ)","مسار الاتصال.","الأجهزة الطرفية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يعبر عن نهج أمني لا يمنح الثقة تلقائيًا لمستخدم أو جهاز لمجرد وجوده داخل الشبكة؟","a":"(ج) نهج انعدام الثقة (Zero Trust)","mcq":{"stem":"ما هو المصطلح الذي يعبر عن نهج أمني لا يمنح الثقة تلقائيًا لمستخدم أو جهاز لمجرد وجوده داخل الشبكة؟","opts":["الدفاع في العمق.","جدار الحماية.","نهج انعدام الثقة (Zero Trust)","الشبكة الافتراضية الخاصة."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات الآتية يمثل الاستخدام الرئيسي للشبكة الافتراضية الخاصة (VPN) لربط المكاتب أو الموظفين؟","a":"(أ) تشفير الاتصال وحماية البيانات عبر شبكات غير موثوقة أو العمل عن بعد.","mcq":{"stem":"أي من الخيارات الآتية يمثل الاستخدام الرئيسي للشبكة الافتراضية الخاصة (VPN) لربط المكاتب أو الموظفين؟","opts":["تشفير الاتصال وحماية البيانات عبر شبكات غير موثوقة أو العمل عن بعد.","التخلص التلقائي من الفيروسات الموجودة على القرص الصلب.","تسريع اتصالات الإنترنت العامة بدون الحاجة لكلمات مرور.","توفير واجهة رسومية لإدارة قواعد البيانات الضخمة."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف تحمي «المنطقة المعزولة (DMZ)» شبكة المؤسسة الداخلية عند تعرض أحد خوادم الويب العامة للاختراق الهجومي الخارجي.","a":"يوضع خادم الويب العام في منطقة DMZ منفصلة عن الشبكة الداخلية.فإذا تعرض الخادم للاختراق، يساعد هذا الفصل على تقليل احتمال وصول الهجوم إلى الشبكة الداخلية وقواعد البيانات والأنظمة الحساسة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تحدث عن طبقات «الدفاع في العمق» الأربعة مبينًا الإجراء الأمني المرتبط بكل طبقة من مدخل الشبكة وحتى الأجهزة الطرفية.","a":"مدخل الشبكة:جدار الحماية لمنع الاتصال غير المصرح به. مسار الاتصال VPN: لتشفير الاتصالات. وضع الخوادم DMZ: لعزل الخوادم العامة عن الشبكة الداخلية. الأجهزة الطرفية:برامج مكافحة الفيروسات وتحديث نظام التشغيل."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح كيف يساهم تطبيق «نهج انعدام الثقة (Zero Trust)» في التحقق من كل عملية وصول بناء على الهوية والصلاحيات والسياق.","a":"لا يمنح Zero Trust الثقة تلقائيا لأي مستخدم أو جهاز، بل يتحقق عند كل طلب وصول من الهوية والجهاز والصلاحيات والسياق ثم يسمح بالوصول فقط إذا استوفت الشروط الأمنية."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش سبب تراجع فاعلية «المحيط الأمني» التقليدي في بيئات العمل الحديثة التي تعتمد على الحوسبة السحابية والعمل عن بعد.","a":"لأن المستخدمين والخدمات والبيانات لم تعد جميعها داخل حدود شبكة المؤسسة، بل أصبحت موزعة داخلها وخارجها مع الحوسبة السحابية والعمل عن بعد؛ لذلك لم تعد حدود الشبكة التقليدية وحدها كافية للحماية."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"التقنية التي تنشئ خطا خاصا افتراضيا مشفرا عبر الإنترنت للاتصال الآمن من موقع بعيد هي:","a":"(ب) الشبكة الافتراضية الخاصة (VPN)","mcq":{"stem":"التقنية التي تنشئ خطا خاصا افتراضيا مشفرا عبر الإنترنت للاتصال الآمن من موقع بعيد هي:","opts":["جدار الحماية.","الشبكة الافتراضية الخاصة (VPN)","المنطقة المعزولة.","نهج انعدام الثقة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"طبقة الدفاع في العمق التي تهتم بتثبيت برنامج مكافحة الفيروسات والحفاظ على تحديث نظام التشغيل هي:","a":"(د) الأجهزة الطرفية.","mcq":{"stem":"طبقة الدفاع في العمق التي تهتم بتثبيت برنامج مكافحة الفيروسات والحفاظ على تحديث نظام التشغيل هي:","opts":["مدخل الشبكة.","مسار الاتصال.","وضع الخوادم.","الأجهزة الطرفية."],"correct":3}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الحدود التقليدية التي تفترض أن داخل شبكة المؤسسة آمنًا تمامًا وخارجها خطر تعرف ب:","a":"(أ) المحيط الأمني.","mcq":{"stem":"الحدود التقليدية التي تفترض أن داخل شبكة المؤسسة آمنًا تمامًا وخارجها خطر تعرف ب:","opts":["المحيط الأمني.","المنطقة المعزولة.","التراكب الكمي.","الحوسبة الطرفية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"نظام أو برنامج يراقب حركة مرور الشبكة ويسمح بها أو يمنعها وفق قواعد أمنية محددة:","a":"(أ) جدار الحماية (Firewall)","mcq":{"stem":"نظام أو برنامج يراقب حركة مرور الشبكة ويسمح بها أو يمنعها وفق قواعد أمنية محددة:","opts":["جدار الحماية (Firewall)","الشبكة الافتراضية الخاصة.","الكيوبت.","الحوسبة الطرفية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش الأهمية الأمنية الاستخدام «الشبكة الافتراضية الخاصة (VPN)» عند الاتصال بشبكات غير موثوقة وكيف تحمي محتوى الاتصال من التنصت.","a":"تستخدم VPN التشفير وتقنيات النفق لإنشاء اتصال آمن عبر شبكة عامة أو غير موثوقة، فتقوم بتشفير البيانات أثناء انتقالها، وبذلك يصعب على المهاجم قراءة محتوى الاتصال حتى عند اعتراضه."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يتكامل كل من جدار الحماية، والشبكة الافتراضية الخاصة، والمنطقة المعزولة، وضوابط الأجهزة الطرفية لتشكيل استراتيجية «الدفاع في العمق» متكاملة.","a":"جدار الحماية يراقب حركة المرور ويمنع الاتصالات غير المصرح بها، و VPN تشفر مسار الاتصال، و DMZ تعزل الخوادم العامة عن الشبكة الداخلية، وضوابط الأجهزة الطرفية تحمي الأجهزة ببرامج مكافحة الفيروسات والتحديثات.وبذلك تتكون عدة طبقات من الحماية، فإذا فشلت إحداها تبقى الطبقات الأخرى."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"بين كيف يتعامل «نهج انعدام الثقة (Zero Trust)» مع الهوية والسياق والصلاحيات مقارنة بالأمان التقليدي الذي يثق بكل ما هو داخل المحيط؟","a":"الأمان التقليدي يفترض أن ما داخل المحيط موثوق، أما Zero Trust فلا يمنح الثقة تلقائيا؛ بل يتحقق من الهوية والجهاز والصلاحيات والسياق عند كل طلب وصول قبل السماح به."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح لماذا يعد وضع خادم البريد الإلكتروني أو خادم الويب في «المنطقة المعزولة (DMZ)» إجراءً وقائيًا أساسيًا لسلامة قواعد البيانات الداخلية الحساسة.","a":"لأن خادم البريد أو الويب يكون معرضا للاتصال من الإنترنت وأكثر عرضة للهجوم؛ ووضعه في DMZ يفصله عن الشبكة الداخلية، فيقل احتمال انتقال الاختراق إلى قواعد البيانات والأنظمة الداخلية الحساسة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"منطقة توضع فيها الخوادم المعرضة للشبكة الخارجية بشكل منفصل عن الشبكة الداخلية تسمى:","a":"(ب) المنطقة المعزولة (DMZ)","mcq":{"stem":"منطقة توضع فيها الخوادم المعرضة للشبكة الخارجية بشكل منفصل عن الشبكة الداخلية تسمى:","opts":["جدار الحماية.","المنطقة المعزولة (DMZ)","الشبكة الافتراضية الخاصة.","الأجهزة الطرفية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"نهج أمني لا يمنح الثقة تلقائيا لمستخدم أو جهاز لمجرد وجوده داخل الشبكة أو ملكيته للمؤسسة هو:","a":"(ب) نهج انعدام الثقة (Zero Trust)","mcq":{"stem":"نهج أمني لا يمنح الثقة تلقائيا لمستخدم أو جهاز لمجرد وجوده داخل الشبكة أو ملكيته للمؤسسة هو:","opts":["الدفاع في العمق.","نهج انعدام الثقة (Zero Trust)","المحيط الأمني.","جدار الحماية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي مما يلي يمثل الطبقة الأولى (مدخل الشبكة) في استراتيجية الدفاع في العمق؟","a":"(ب) منع الاتصال غير المصرح به باستخدام جدار الحماية.","mcq":{"stem":"أي مما يلي يمثل الطبقة الأولى (مدخل الشبكة) في استراتيجية الدفاع في العمق؟","opts":["تشفير الاتصال باستخدام الشبكة الافتراضية الخاصة","منع الاتصال غير المصرح به باستخدام جدار الحماية.","فصل الخوادم المواجهة للجمهور باستخدام المنطقة المعزولة.","تثبيت برنامج مكافحة الفيروسات على الأجهزة الطرفية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"اتصال أو شبكة منطقية خاصة عبر شبكة عامة مثل الإنترنت تستخدم التشفير وتقنيات النفق لحماية البيانات هي:","a":"(أ) الشبكة الافتراضية الخاصة (VPN)","mcq":{"stem":"اتصال أو شبكة منطقية خاصة عبر شبكة عامة مثل الإنترنت تستخدم التشفير وتقنيات النفق لحماية البيانات هي:","opts":["الشبكة الافتراضية الخاصة (VPN)","المنطقة المعزولة.","جدار الحماية.","نهج انعدام الثقة."],"correct":0}}],"2-3":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"ما المقصود بمصطلح «الحادث الأمني» وما هي أبرز الأمثلة النموذجية عليه؟","a":"الحادث الأمني هو حدث يؤثر في سرية المعلومات أو سلامتها أو توافرها، أو يهددها بجدية، أو يخالف سياسة أمنية. ومن أمثلته: تسرب المعلومات: خروج معلومات شخصية أو سرية. التلاعب بالبيانات: تعديل البيانات داخل نظام دون تصريح. انقطاع الخدمة: عدم إتاحة الخدمة مثل توقفها بسبب هجمات على الخادم."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح المراحل الست للاستجابة للحوادث، مبينًا الغرض الأساسي من مرحلتي «التحضير» و«الاكتشاف»","a":"المراحل الست بالترتيب: التحضير ←الاكتشاف ←الاحتواء ←إزالة التهديد (الاستئصال) ←الاستعادة ←الدروس المستفادة والتحسين. التحضير: إنشاء إجراءات وهياكل استجابة مسبقا استعدادا للحوادث. الاكتشاف: اكتشاف وقوع الحادث وتأكيده. الاحتواء: تحديد نطاق التأثير حتى لا ينتشر الضرر. الاستئصال: إزالة التهديد ومسبباته. الاستعادة: إعادة الخدمات إلى التشغيل الآمن. الدروس المستفادة والتحسين: تحليل ما حدث وتحسين الضوابط."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات التالية يُعد مثالًا نموذجيًا على حادث أمني يؤثر في توافر الخدمة؟","a":"انقطاع الخدمة بسبب هجمات على الخادم.","mcq":{"stem":"أي من الخيارات التالية يُعد مثالًا نموذجيًا على حادث أمني يؤثر في توافر الخدمة؟","opts":["تسرب المعلومات الشخصية أو السرية إلى الخارج.","تعديل البيانات داخل نظام ما دون تصريح.","انقطاع الخدمة بسبب هجمات على الخادم.","إنشاء إجراءات وهياكل استجابة مسبقًا."],"correct":2}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي المرحلة الأولى من نموذج الاستجابة للحوادث التي تهدف إلى إنشاء إجراءات وهياكل استجابة مسبقًا استعدادًا للحوادث؟","a":"التحضير.","mcq":{"stem":"ما هي المرحلة الأولى من نموذج الاستجابة للحوادث التي تهدف إلى إنشاء إجراءات وهياكل استجابة مسبقًا استعدادًا للحوادث؟","opts":["الاكتشاف.","التحضير.","الاحتواء.","الاستعادة."],"correct":1}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح الغرض من مرحلتي «الاحتواء» و«إزالة التهديد (الاستئصال)» في نموذج الاستجابة للحوادث.","a":"الاحتواء: عزل الجزء المتأثر أو تقييد أثره بطريقة مناسبة لمنع انتشار المشكلة وتحديد نطاق الضرر. الاستئصال: إزالة التهديد ومسبباته، مثل حذف البرمجيات الخبيثة ومعالجة الثغرة المستغلة."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"كيف يتم تقدير درجة الخطر في النموذج المبسط للدرس؟ اذكر معادلته والعاملين الأساسيين المكونين له.","a":"درجة الخطر =درجة التأثير ×درجة الاحتمالية؛ فالتأثير هو مقدار الضرر إذا وقعت المخاطرة، والاحتمالية هي مدى احتمالية وقوع المخاطرة."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يُطلق على إجراء عزل الجزء المتأثر أو تقييد أثره بالطريقة المناسبة لمنع انتشار المشكلة؟","a":"الاحتواء.","mcq":{"stem":"ما هو المصطلح الذي يُطلق على إجراء عزل الجزء المتأثر أو تقييد أثره بالطريقة المناسبة لمنع انتشار المشكلة؟","opts":["التحضير.","الاكتشاف.","الاحتواء.","الاستعادة."],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"كيف يتم حساب درجة الخطر في المصفوفة المبسطة؟","a":"التأثير × الاحتمالية.","mcq":{"stem":"كيف يتم حساب درجة الخطر في المصفوفة المبسطة؟","opts":["التأثير + الاحتمالية.","التأثير × الاحتمالية.","التأثير − الاحتمالية.","التأثير ÷ الاحتمالية."],"correct":1}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح المقصود بمرحلتي «الاستعادة» و«الدروس المستفادة والتحسين» في نموذج الاستجابة للحوادث.","a":"الاستعادة: إعادة الأنظمة والخدمات إلى حالة تشغيل آمنة وطبيعية، وقد تشمل الاستعادة من نسخة احتياطية سليمة. الدروس المستفادة والتحسين: تحليل ما حدث وتوثيق الدروس وتحسين الضوابط لتقليل احتمال تكرار الحادث وأثره."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"لماذا يجب تنفيذ مرحلة «الاحتواء» قبل مرحلة «الاستئصال (إزالة التهديد)»؟ ماذا قد يحدث إذا تم عكس هذا الترتيب؟","a":"يأتي الاحتواء أولًا لتحديد نطاق التأثير والحد من انتشار الضرر، ثم يزال التهديد ومسبباته بالاستئصال. فإذا بدأنا بإزالة التهديد قبل احتواء الجزء المتأثر، فقد يستمر انتشار المشكلة أثناء المعالجة؛"},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي المرحلة التي تتضمن إعادة الأنظمة والخدمات إلى حالة تشغيل آمنة وطبيعية وقد تشمل الاستعادة من نسخة احتياطية سليمة؟","a":"الاستعادة.","mcq":{"stem":"ما هي المرحلة التي تتضمن إعادة الأنظمة والخدمات إلى حالة تشغيل آمنة وطبيعية وقد تشمل الاستعادة من نسخة احتياطية سليمة؟","opts":["التحضير.","الاحتواء.","الاستعادة.","الدروس المستفادة والتحسين."],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي مرحلة تختتم بها المراحل الست للاستجابة للحوادث وتتضمن تحليل ما حدث وتوثيق الدروس لتحسين الضوابط؟","a":"الدروس المستفادة والتحسين.","mcq":{"stem":"أي مرحلة تختتم بها المراحل الست للاستجابة للحوادث وتتضمن تحليل ما حدث وتوثيق الدروس لتحسين الضوابط؟","opts":["الاكتشاف.","إزالة التهديد.","الاستعادة.","الدروس المستفادة والتحسين."],"correct":3}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح كيف يتم التعامل مع المخاطر وفقا ل«مصفوفة تقييم المخاطر»، وأي فئة تمثل أعلى أولويات المعالجة.","a":"تقدر المخاطر اعتمادا على التأثير والاحتمالية معا، ثم تحدد الأولويات باستخدام مصفوفة تقييم المخاطر. المخاطر ذات التأثير العالي والاحتمالية العالية من أعلى الأولويات وتعالج أولًا؛ ويعتمد ترتيب غيرها على درجات المصفوفة والسياق والضوابط المتاحة."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر أمثلة على التداخل أو التكرار الذي قد يحدث بين مراحل الاستجابة للحوادث في الواقع العملي.","a":"المثال الذي يورده الكتاب: قد يكشف العمل أثناء الاستعادة أو الاسترداد بقايا للتهديد، فتستلزم المعالجة العودة إلى الاحتواء من جديد، أو العودة إلى مرحلة إزالة التهديد (الاستئصال)، ثم استكمال الاستعادة. وهكذا قد تتكرر بعض الأنشطة أو تتداخل بحسب طبيعة الحادث."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"وفقًا لمصفوفة تقييم المخاطر، ما هي الفئة التي تُعد من أعلى الأولويات ويجب معالجتها أولًا؟","a":"التأثير المرتفع والاحتمالية المرتفعة.","mcq":{"stem":"وفقًا لمصفوفة تقييم المخاطر، ما هي الفئة التي تُعد من أعلى الأولويات ويجب معالجتها أولًا؟","opts":["التأثير المنخفض والاحتمالية المنخفضة.","التأثير المتوسط والاحتمالية المتوسطة.","التأثير المرتفع والاحتمالية المرتفعة.","التأثير المنخفض والاحتمالية المرتفعة."],"correct":2}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما المقصود بمصطلح «التأثير» في سياق تقييم المخاطر؟","a":"مقدار الضرر إذا وقعت المخاطرة.","mcq":{"stem":"ما المقصود بمصطلح «التأثير» في سياق تقييم المخاطر؟","opts":["مدى احتمال وقوع الحدث.","مقدار الضرر إذا وقعت المخاطرة.","سرعة الاستجابة للحادث الأمني.","عدد المرات التي تكرر فيها الحادث."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"عرف الحادث الأمني بالتفصيل واذكر ثلاثة من أمثلته النموذجية مع بيان وصف كل منها.","a":"الحادث الأمني هو حدث يؤثر في سرية المعلومات أو سلامتها أو توافرها، أو يهددها بجدية، أو يخالف سياسة أمنية. والأمثلة الثلاثة هي: تسرب المعلومات: خروج معلومات شخصية أو سرية. التلاعب بالبيانات: تعديل البيانات داخل نظام دون تصريح. انقطاع الخدمة: عدم إتاحة الخدمة، مثل توقفها بسبب هجمات على الخادم."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر المراحل الست للاستجابة للحوادث بترتيبها التسلسلي مع شرح وجيز لمرحلتي التحضير والاحتواء.","a":"الترتيب: التحضير ←الاكتشاف ←الاحتواء ←إزالة التهديد (الاستئصال) ←الاستعادة ←الدروس المستفادة والتحسين. التحضير: إنشاء إجراءات وهياكل استجابة مسبقا استعدادا للحوادث. الاحتواء: تحديد نطاق التأثير أو عزل الجزء المتأثر كي لا ينتشر الضرر أكثر."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيفية استخدام مصفوفة تقييم المخاطر لتحديد أولويات المعالجة بناءا على التأثير والاحتمالية.","a":"درجة الخطر =درجة التأثير ×درجة الاحتمالية؛ فالتأثير هو مقدار الضرر إذا وقعت المخاطرة والاحتمالية هي مدى احتمالية وقوع المخاطرة. تقدر المخاطر اعتمادا على التأثير والاحتمالية معا، ثم تحدد الأولويات باستخدام مصفوفة تقييم المخاطر. المخاطر ذات التأثير العالي والاحتمالية العالية من أعلى الأولويات وتعالج أولًا؛ ويعتمد ترتيب غيرها على درجات المصفوفة والسياق والضوابط المتاحة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش سبب أهمية تنفيذ المراحل الست للاستجابة بالترتيب، وما طبيعة التداخل أو التكرار المحتمل بينها أثناء المعالجة الفعلية.","a":"يساعد التسلسل العام على تنظيم الاستجابة؛ فيحد انتشار الضرر بالاحتواء أولًا، ثم يزال التهديد وسببه بالاستئصال، وبعد ذلك تعود الأنظمة للعمل الآمن بالاستعادة. وقد تتداخل الأنشطة أو تتكرر، مثل اكتشاف بقايا التهديد أثناء الاستعادة، مما يستلزم العودة للاحتواء أو الاستئصال."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"حدث يؤثر في سرية المعلومات أو سلامتها أو توافرها أو يخالف سياسة أمنية يسمى:","a":"حادثًا أمنيًا.","mcq":{"stem":"حدث يؤثر في سرية المعلومات أو سلامتها أو توافرها أو يخالف سياسة أمنية يسمى:","opts":["حادثًا أمنيًا.","تقييمًا للمخاطر.","احتواءً للتهديد.","درسًا مستفادًا."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"المرحلة التي تُستخدم للحد من انتشار الضرر وعزل الجزء المتأثر تسمى:","a":"الاحتواء.","mcq":{"stem":"المرحلة التي تُستخدم للحد من انتشار الضرر وعزل الجزء المتأثر تسمى:","opts":["التحضير.","الاحتواء.","الاستعادة.","الاستئصال."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"المخاطر التي تمثل أعلى أولوية في مصفوفة تقييم المخاطر هي ذات:","a":"التأثير المرتفع والاحتمالية المرتفعة.","mcq":{"stem":"المخاطر التي تمثل أعلى أولوية في مصفوفة تقييم المخاطر هي ذات:","opts":["التأثير المنخفض والاحتواء السريع.","التأثير المرتفع والاحتمالية المرتفعة.","التأثير الصغير والاحتمالية المنخفضة.","التأثير المتوسط والاحتمالية المعدومة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا تعني مرحلة «الاستئصال» في نموذج الاستجابة للحوادث؟","a":"إزالة التهديد ومسبباته مثل حذف البرمجيات الخبيثة.","mcq":{"stem":"ماذا تعني مرحلة «الاستئصال» في نموذج الاستجابة للحوادث؟","opts":["إنشاء إجراءات استجابة مسبقًا.","إزالة التهديد ومسبباته مثل حذف البرمجيات الخبيثة.","استعادة الأنظمة من نسخة احتياطية.","توثيق الدروس المستفادة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح بالتفصيل الغرض من مرحلتي «الاكتشاف» و«إزالة التهديد (الاستئصال)» ضمن المراحل الست للاستجابة للحوادث.","a":"الاكتشاف: اكتشاف وقوع الحادث الأمني وتأكيده. إزالة التهديد (الاستئصال): إزالة التهديد ومسبباته بعد الاحتواء، مثل حذف البرمجيات الخبيثة ومعالجة الثغرة التي استغلت في الحادث."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح المقصود بمفهومي «التأثير» و«الاحتمالية» في سياق تقييم المخاطر وكيف يساهمان في حساب درجة الخطر.","a":"درجة الخطر =درجة التأثير ×درجة الاحتمالية؛ فالتأثير هو مقدار الضرر إذا وقعت المخاطرة، والاحتمالية هي مدى احتمالية وقوع المخاطرة. تستخدم درجتا العاملين معا لتقدير أولوية المخاطرة وفق مصفوفة درجة الخطر."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تحدث عن أهمية مرحلة «الدروس المستفادة والتحسين» وكيف تسافهمي منع تكرار الحوادث الأمنية مستقبلا.","a":"في هذه المرحلة تحلل أحداث الحادث الأمني وتوثق الدروس المستفادة، ثم تحسن الضوابط الأمنية لتقليل احتمال تكرار الحادث وتقليل أثره إن وقع مجددا."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"قارن بين أنواع الحوادث الأمنية الثلاثة المذكورة في الدرس (تسرب المعلومات، التلاعب بالبيانات، انقطاع الخدمة) من حيث الوصف.","a":"تسرب المعلومات: خروج معلومات شخصية أو سرية. التلاعب بالبيانات: تعديل البيانات داخل نظام دون تصريح. انقطاع الخدمة: عدم إتاحة الخدمة، مثل توقفها بسبب هجمات على الخادم."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تعديل البيانات داخل نظام ما دون تصريح يُعد مثالًا نموذجيًا على:","a":"التلاعب بالبيانات.","mcq":{"stem":"تعديل البيانات داخل نظام ما دون تصريح يُعد مثالًا نموذجيًا على:","opts":["انقطاع الخدمة.","تسرب المعلومات.","التلاعب بالبيانات.","التحضير المسبق."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"المرحلة التي تُعنى بإعادة الأنظمة والخدمات إلى حالة تشغيل آمنة وطبيعية وتشمل الاستعادة من نسخة احتياطية هي:","a":"الاستعادة.","mcq":{"stem":"المرحلة التي تُعنى بإعادة الأنظمة والخدمات إلى حالة تشغيل آمنة وطبيعية وتشمل الاستعادة من نسخة احتياطية هي:","opts":["الاستعادة.","الاحتواء.","الاكتشاف.","التحضير."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"درجة الخطر في النموذج المبسط تُحسب كالتالي:","a":"التأثير × الاحتمالية.","mcq":{"stem":"درجة الخطر في النموذج المبسط تُحسب كالتالي:","opts":["التأثير ÷ الاحتمالية.","التأثير + الاحتمالية.","التأثير × الاحتمالية.","التأثير − الاحتمالية."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يُقصد بمصطلح «الاحتمالية» في تقييم المخاطر؟","a":"مدى احتمال وقوع الحدث أو المخاطرة.","mcq":{"stem":"ماذا يُقصد بمصطلح «الاحتمالية» في تقييم المخاطر؟","opts":["حجم الضرر المتوقع إذا وقع الحدث.","مدى احتمال وقوع الحدث أو المخاطرة.","عدد الأجهزة المتأثرة بالهجوم.","سرعة تنفيذ مراحل الاستجابة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بالتفصيل كيف يتم تنفيذ مرحلتي «الاستعادة» و«الدروس المستفادة والتحسين» عند التعامل مع حادث أمني مثل هجوم ببرمجية فدية.","a":"في مثال هجوم برمجية الفدية الوارد في الدرس، وبعد احتواء المشكلة وإزالة التهديد ومسبباته، تعاد الأنظمة والخدمات إلى حالة تشغيل آمنة وطبيعية؛ وقد يشمل ذلك الاستعادة من نسخة احتياطية سليمة. ثم يحلل ما حدث، وتوثق الدروس وتحسن الضوابط لتقليل احتمال تكرار هجوم مماثل وأثره."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش العلاقة بين مرحلتي «الاحتواء» و«الاستئصال» ولماذا يجب أن يسبق الاحتواء عملية إزالة السبب.","a":"الاحتواء يحد نطاق التأثير ويمنع انتشار الضرر، بينما يستهدف الاستئصال إزالة التهديد ومسبباته. يسبق الاحتواء الاستئصال حتى لا تستمر المشكلة في الانتشار أثناء إزالة سببها."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر المراحل الست للاستجابة للحوادث بالتسلسل، وبين كيف يمكن أن تحدث تداخلات أو عودة لمراحل سابقة أثناء الاستجابة الفعلية.","a":"المراحل: التحضير ←ا الاكتشاف ←الاحتواء ←إزالة التهديد (الاستئصال) ←الاستعادة ←الدروس المستفادة والتحسين. قد تتداخل أنشطة المراحل أو تتكرر؛ إذ قد تكشف الاستعادة عن بقايا للتهديد، فتكون هناك حاجة للرجوع إلى الاحتواء أو الاستئصال قبل متابعة الاستعادة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف تستخدم المؤسسات مصفوفة تقييم المخاطر لتصنيف المخاطر وتوجيه الجهود نحو المعالجة الأولية الفعالة.","a":"درجة الخطر =درجة التأثير ×درجة الاحتمالية؛ فالتأثير هو مقدار الضرر إذا وقعت المخاطرة، والاحتمالية هي مدى احتمالية وقوع المخاطرة. تقدر المخاطر اعتمادا على التأثير والاحتمالية معا، ثم تحدد الأولويات باستخدام مصفوفة تقييم المخاطر. المخاطر ذات التأثير العالي والاحتمالية العالية من أعلى الأولويات وتعالج أولًا؛ ويعتمد ترتيب غيرها على درجات المصفوفة والسياق والضوابط المتاحة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تسرب المعلومات الشخصية أو السرية إلى الخارج يمثل حادثًا أمنيًا من نوع:","a":"تسرب المعلومات.","mcq":{"stem":"تسرب المعلومات الشخصية أو السرية إلى الخارج يمثل حادثًا أمنيًا من نوع:","opts":["تسرب المعلومات.","انقطاع الخدمة.","التلاعب بالبيانات.","الاستعادة الآمنة."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تحليل ما حدث وتوثيق الدروس وتحسين الضوابط لتقليل احتمال التكرار يتم في مرحلة:","a":"الدروس المستفادة والتحسين.","mcq":{"stem":"تحليل ما حدث وتوثيق الدروس وتحسين الضوابط لتقليل احتمال التكرار يتم في مرحلة:","opts":["التحضير.","الاحتواء.","الاستئصال.","الدروس المستفادة والتحسين."],"correct":3}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"المخاطر ذات التأثير المرتفع والاحتمالية المنخفضة في مصفوفة تقييم المخاطر تُصنف عادة على أنها ذات خطورة:","a":"متوسطة.","mcq":{"stem":"المخاطر ذات التأثير المرتفع والاحتمالية المنخفضة في مصفوفة تقييم المخاطر تُصنف عادة على أنها ذات خطورة:","opts":["مرتفعة جدًا.","متوسطة.","منخفضة جدًا.","معدومة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"المرحلة التي تتضمن اكتشاف وتأكيد وقوع حادث أمني بعد التحضير المسبق هي مرحلة:","a":"الاكتشاف.","mcq":{"stem":"المرحلة التي تتضمن اكتشاف وتأكيد وقوع حادث أمني بعد التحضير المسبق هي مرحلة:","opts":["الاستعادة.","الاكتشاف.","الدروس المستفادة.","الاستئصال."],"correct":1}}],"3-1":[{"period":null,"kind":null,"qtype":"مقالي","q":"عرف تطبيق الويب؟","a":"تطبيق الويب هو تطبيق يستخدم عادة من خلال متصفح الويب، وقد تتيح بعض تطبيقات الويب تثبيتها على الجهاز. من أمثلته خدمات الفيديو والتسوق والبريد الإلكتروني والخرائط على الويب."},{"period":null,"kind":null,"qtype":"مقالي","q":"عدد الطبقات الرئيسة التي يتكون منها تطبيق الويب؟","a":"يتكون وفق النموذج التعليمي المبسط من ثلاث طبقات: الواجهة الأمامية، والواجهة الخلفية، وقاعدة البيانات (طبقة البيانات)"},{"period":null,"kind":null,"qtype":"موضوعي","q":"يُبنى عادة تطبيق الويب من:","a":"ثلاث طبقات.","mcq":{"stem":"يُبنى عادة تطبيق الويب من:","opts":["ثلاث طبقات.","طبقتان.","طبقة واحدة.","عدة طبقات."],"correct":0}},{"period":null,"kind":null,"qtype":"موضوعي","q":"الطبقة المسؤولة عن عرض الشاشات وتجمع بيانات وإجراءات المستخدم هي:","a":"الواجهة الأمامية.","mcq":{"stem":"الطبقة المسؤولة عن عرض الشاشات وتجمع بيانات وإجراءات المستخدم هي:","opts":["الواجهة الخلفية.","قاعدة البيانات.","الواجهة الأمامية.","خادم المعالجة."],"correct":2}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"قارن بين دور الواجهة الأمامية ودور الواجهة الخلفية في تطبيق شبكة التواصل الاجتماعي؟","a":"الواجهة الأمامية تعرض الخط الزمني وشاشات النشر وتستقبل المحتوى الذي يدخله المستخدم. أما الواجهة الخلفية فتحدد الجمهور المستهدف للمنشورات وتتحكم في الإشعارات الفورية."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"كيف تتعامل الواجهة الخلفية مع البيانات الواردة من الواجهة الأمامية والبيانات المخزنة في قاعدة البيانات في موقع للتجارة الإلكترونية؟","a":"تستقبل الواجهة الخلفية طلب المستخدم المرسل من الواجهة الأمامية، وتعالجه وفق قواعد التطبيق؛ مثل التحقق من المخزون وإرسال طلبات الدفع والتعامل مع نتائجها. وتطلب البيانات اللازمة من طبقة البيانات، مثل معلومات المنتجات، ثم تجهز النتيجة لإرسالها إلى الواجهة الأمامية."},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"في موقع مشاركة الفيديو، تتبع عملية تجميع عدد المشاهدات واختيار الفيديوهات الموصى بها لـ:","a":"الواجهة الخلفية.","mcq":{"stem":"في موقع مشاركة الفيديو، تتبع عملية تجميع عدد المشاهدات واختيار الفيديوهات الموصى بها لـ:","opts":["الواجهة الأمامية.","الواجهة الخلفية.","قاعدة البيانات.","شبكة الاتصال."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تخزين بيانات المنشورات وعلاقات المتابعة والرسائل في شبكة تواصل اجتماعي هي وظيفة:","a":"قاعدة البيانات.","mcq":{"stem":"تخزين بيانات المنشورات وعلاقات المتابعة والرسائل في شبكة تواصل اجتماعي هي وظيفة:","opts":["خادم المعالجة.","قاعدة البيانات.","الواجهة الأمامية.","الواجهة الخلفية."],"correct":1}},{"period":null,"kind":"المهام الأدائية","qtype":"مقالي","q":"صمم مخططا هيكليا يوضح كيف تتعاون الطبقات الثلاث لتنفيذ إجراءات المستخدم. الواجهة الأمامية العرض والتفاعل ←الواجهة الخلفية المعالجة والتحكم ←قاعدة البيانات التخزين والاسترجاع الطلب يتجه نحو قاعدة البيانات عبر الواجهة الخلفية، ثم تعود البيانات والنتيجة نحو الواجهة الأمامية.","a":"تنتقل مدخلات المستخدم من الواجهة الأمامية إلى الواجهة الخلفية؛ فتطلب الأخيرة البيانات اللازمة من قاعدة البيانات، ثم تعود البيانات إلى الخلفية لتجهيز النتيجة، وتعرض الواجهة الأمامية هذه النتيجة. وتسير الاستجابة في الاتجاه العكسي بعد الحصول على البيانات."},{"period":null,"kind":"المهام الأدائية","qtype":"مقالي","q":"ناقش أهمية طبقة قاعدة البيانات في مواقع التجارة الإلكترونية.","a":"تحفظ طبقة البيانات معلومات المنتجات وسجل الطلبات ومعلومات العملاء، وتوفرها للواجهة الخلفية عند الحاجة. وبذلك تتمكن الواجهة الخلفية من معالجة طلبات المستخدم، مثل التحقق من المخزون والتعامل مع طلبات الشراء، ثم تعرض النتيجة عبر الواجهة الأمامية."},{"period":null,"kind":"المهام الأدائية","qtype":"موضوعي","q":"إرسال طلبات الدفع والتعامل مع نتائجها في موقع التجارة الإلكترونية هو عمل المعالجة والتحكم في:","a":"الواجهة الخلفية.","mcq":{"stem":"إرسال طلبات الدفع والتعامل مع نتائجها في موقع التجارة الإلكترونية هو عمل المعالجة والتحكم في:","opts":["الواجهة الأمامية.","قاعدة البيانات.","الواجهة الخلفية.","متصفح المستخدم."],"correct":2}},{"period":null,"kind":"المهام الأدائية","qtype":"موضوعي","q":"الدور الرئيس لطبقة قاعدة البيانات في تطبيقات الويب هو:","a":"تخزين البيانات واسترجاعها.","mcq":{"stem":"الدور الرئيس لطبقة قاعدة البيانات في تطبيقات الويب هو:","opts":["استقبال إجراءات المستخدم.","تخزين البيانات واسترجاعها.","معالجة العمليات الحسابية.","عرض الشاشات والواجهات."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح البنية العامة لتطبيقات الويب والطبقات الثلاث.","a":"نموذجا تعليميا مبسطا لتطبيقات الويب يعتمد على ثلاث طبقات متعاونة: الواجهة الأمامية للعرض والتفاعل وجمع مدخلات المستخدم، والواجهة الخلفية لمعالجة الطلبات وتطبيق قواعد التطبيق، وطبقة البيانات لحفظ البيانات وتوفيرها. وقد تختلف البنية الفعلية من تطبيق آلخر."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح كيف تتكامل الطبقات الثلاث في تقديم خدمة «مشاركة الفيديو» مع ذكر مثال لوظيفة كل طبقة.","a":"الواجهة الأمامية: تعرض شاشات تشغيل الفيديو والبحث وتستقبل إجراءات المستخدم. الواجهة الخلفية: تختار الفيديوهات الموصى بها وتجمع عدد المشاهدات. قاعدة البيانات: تخزن بيانات الفيديو ومعلومات المستخدمين وسجل المشاهدة."},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"في موقع مشاركة الفيديو، يتم تخزين سجل المشاهدات ومعلومات المستخدمين في:","a":"طبقة قاعدة البيانات.","mcq":{"stem":"في موقع مشاركة الفيديو، يتم تخزين سجل المشاهدات ومعلومات المستخدمين في:","opts":["شاشات البحث.","الواجهة الخلفية.","الواجهة الأمامية.","طبقة قاعدة البيانات."],"correct":3}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"التحكم في الإشعارات الفورية وتحديد الجمهور المستهدف للمنشورات يتم عبر:","a":"الواجهة الخلفية.","mcq":{"stem":"التحكم في الإشعارات الفورية وتحديد الجمهور المستهدف للمنشورات يتم عبر:","opts":["الواجهة الخلفية.","الواجهة الأمامية.","قاعدة البيانات.","الخط الزمني."],"correct":0}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي مما يأتي يمثل دور الواجهة الأمامية في تطبيق الويب؟","a":"عرض المحتوى واستقبال إدخال المستخدم.","mcq":{"stem":"أي مما يأتي يمثل دور الواجهة الأمامية في تطبيق الويب؟","opts":["معالجة الطلبات.","عرض المحتوى واستقبال إدخال المستخدم.","تخزين البيانات.","التحقق من تسجيل الدخول."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"عند البحث عن منتج في متجر إلكتروني، أي طبقة تُرسل الطلب إلى قاعدة البيانات؟","a":"الواجهة الخلفية.","mcq":{"stem":"عند البحث عن منتج في متجر إلكتروني، أي طبقة تُرسل الطلب إلى قاعدة البيانات؟","opts":["الواجهة الأمامية.","الواجهة الخلفية.","قاعدة البيانات نفسها.","المتصفح."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يُعتبر مثالًا على البيانات المخزنة في قاعدة بيانات موقع تجارة إلكترونية؟","a":"سجل الطلبات.","mcq":{"stem":"أي من التالي يُعتبر مثالًا على البيانات المخزنة في قاعدة بيانات موقع تجارة إلكترونية؟","opts":["شاشة البحث.","سجل الطلبات.","التحقق من تسجيل الدخول.","واجهة المستخدم."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الفكرة الرئيسة للبنية العامة لتطبيقات الويب هي:","a":"تعاون ثلاث طبقات: واجهة أمامية، واجهة خلفية، قاعدة بيانات.","mcq":{"stem":"الفكرة الرئيسة للبنية العامة لتطبيقات الويب هي:","opts":["بناء التطبيق من طبقة واحدة فقط.","تعاون ثلاث طبقات: واجهة أمامية، واجهة خلفية، قاعدة بيانات.","استخدام المتصفح فقط.","الاعتماد على الواجهة الخلفية دون قاعدة بيانات."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح الفرق بين الواجهة الأمامية والواجهة الخلفية في تطبيقات الويب مع ذكر مثال لكل منهما.","a":"الواجهة الأمامية تعرض المحتوى وتستقبل ما يدخله المستخدم في المتصفح؛ مثل شاشة البحث أو عرض صفحات المنتجات. الواجهة الخلفية تعمل على الخادم لمعالجة الطلبات وتطبيق القواعد؛ مثل التحقق من تسجيل الدخول أو التحقق من المخزون."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح دور قاعدة البيانات في تطبيق ويب، وكيف تتعاون مع الواجهة الخلفية لإظهار النتائج للمستخدم.","a":"قاعدة البيانات تحفظ البيانات وتوفرها عند الحاجة. عند إدخال المستخدم طلبا، تطلب الواجهة الخلفية البيانات المناسبة من طبقة البيانات، فتعيدها إليها، ثم تجهز الواجهة الخلفية النتيجة وترسلها إلى الواجهة الأمامية كي تظهر للمستخدم."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"تتبع خطوات تدفق طلب البحث عن منتج في متجر إلكتروني عبر الطبقات الثلاث، وبين دور كل طبقة.","a":"(1) تستقبل الواجهة الأمامية ما أدخله المستخدم. (2) ترسل الطلب إلى الواجهة الخلفية. (3) تطلب الواجهة الخلفية البيانات المطلوبة من طبقة البيانات. (4) تعيد طبقة البيانات النتائج إلى الواجهة الخلفية. (5) تجهز الواجهة الخلفية النتائج وترسلها إلى الواجهة الأمامية. (6) تعرض الواجهة الأمامية النتيجة للمستخدم."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"صمم توزيعا مناسبا لمسؤوليات تطبيق ويب للتجارة الإلكترونية وبرر قراراتك.","a":"الواجهة الأمامية: تعرض قوائم المنتجات وشاشات سلة التسوق وتستقبل عمليات الطلب. الواجهة الخلفية: تتحقق من المخزون وترسل طلبات الدفع وتتعامل مع نتائجها. قاعدة البيانات: تخزن معلومات المنتجات وسجل الطلبات ومعلومات العملاء. التبرير: لأن الواجهة الأمامية مسؤولة عن العرض والتفاعل، والخلفية عن المعالجة والتحكم، وقاعدة البيانات عن التخزين والإدارة، كما يوضح توزيع المهام في الكتاب المدرسي."},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يُعتبر مثالًا على تطبيق ويب؟","a":"موقع خرائط على الإنترنت.","mcq":{"stem":"أي من التالي يُعتبر مثالًا على تطبيق ويب؟","opts":["برنامج تشغيل فيديو على الجهاز.","موقع خرائط على الإنترنت.","تطبيق حاسبة على سطح المكتب.","برنامج تحرير الصور."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"في موقع مشاركة الفيديو، أي طبقة تخزن بيانات الفيديو والمستخدمين؟","a":"قاعدة البيانات.","mcq":{"stem":"في موقع مشاركة الفيديو، أي طبقة تخزن بيانات الفيديو والمستخدمين؟","opts":["الواجهة الأمامية.","الواجهة الخلفية.","قاعدة البيانات.","المتصفح."],"correct":2}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تتمثل وظيفة الواجهة الخلفية في تطبيق ويب في:","a":"التحقق من تسجيل الدخول.","mcq":{"stem":"تتمثل وظيفة الواجهة الخلفية في تطبيق ويب في:","opts":["عرض صفحات المنتجات.","عرض مربع البحث للمستخدم.","التحقق من تسجيل الدخول.","تخزين سجل الطلبات."],"correct":2}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الفكرة الرئيسة للبنية العامة لتطبيقات الويب هي:","a":"أن التطبيق يُبنى من ثلاث طبقات تتعاون معًا.","mcq":{"stem":"الفكرة الرئيسة للبنية العامة لتطبيقات الويب هي:","opts":["أن التطبيق يُبنى من ثلاث طبقات تتعاون معًا.","أن كل طبقة تعمل منفردة دون تعاون.","أن التطبيق يعمل من خلال المتصفح فقط.","أن التطبيق يعتمد فقط على قاعدة البيانات."],"correct":0}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح مفهوم تطبيق الويب مع ذكر أمثلة من حياتك اليومية.","a":"تطبيق الويب هو تطبيق يستخدم عادة من خلال متصفح الويب، وقد تتيح بعض تطبيقات الويب تثبيتها على الجهاز. أمثلته: خدمات الفيديو، والتسوق الإلكتروني، والبريد الإلكتروني على الويب، والخرائط على الويب."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش أهمية تقسيم تطبيق الويب إلى ثلاث طبقات رئيسة.","a":"يساعد النموذج التعليمي ذو الطبقات الثلاث على فهم توزيع المهام: الواجهة الأمامية تعرض وتجمع، والواجهة الخلفية تقرر وتعالج، وطبقة البيانات تخزن وتسترجع. وتتعاون هذه الأجزاء لتحويل إجراء المستخدم إلى نتيجة؛ مع ملاحظة أن البنية الفعلية قد تختلف من تطبيق آلخر."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"بين كيف تتعاون الطبقات الثلاث عند استخدام شبكة التواصل الاجتماعي.","a":"عندما ينشر المستخدم محتوى، تستقبله الواجهة الأمامية عبر شاشة النشر، ثم تتولى الواجهة الخلفية معالجة الطلب وتحديد الجمهور المستهدف، وتستخدم قاعدة البيانات لحفظ بيانات المنشور وعلاقات المتابعة. وبعد إتمام المعالجة تعرض النتيجة للمستخدم عبر الواجهة الأمامية."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"حلل دور الواجهة الخلفية في موقع تجارة إلكترونية.","a":"تتولى الواجهة الخلفية معالجة الطلبات والتحكم في قواعد التطبيق، ومن أمثلة وظائفها في موقع التجارة الإلكترونية التحقق من المخزون، وإرسال طلبات الدفع والتعامل مع نتائجها. وتتعاون مع قاعدة البيانات للوصول إلى المعلومات اللازمة، ثم ترسل النتيجة للواجهة الأمامية."},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"في موقع مشاركة الفيديو، أي طبقة تخزن بيانات الفيديو والمستخدمين؟","a":"قاعدة البيانات.","mcq":{"stem":"في موقع مشاركة الفيديو، أي طبقة تخزن بيانات الفيديو والمستخدمين؟","opts":["الواجهة الأمامية.","الواجهة الخلفية.","قاعدة البيانات.","المتصفح."],"correct":2}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يُعتبر مثالًا على تطبيق ويب؟","a":"موقع خرائط على الإنترنت.","mcq":{"stem":"أي من التالي يُعتبر مثالًا على تطبيق ويب؟","opts":["برنامج تشغيل فيديو على الجهاز.","موقع خرائط على الإنترنت.","تطبيق حاسبة على سطح المكتب.","برنامج تحرير الصور."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يُمثل وظيفة الواجهة الخلفية في تطبيق ويب؟","a":"التحقق من تسجيل الدخول.","mcq":{"stem":"أي من التالي يُمثل وظيفة الواجهة الخلفية في تطبيق ويب؟","opts":["عرض صفحات المنتجات.","عرض مربع البحث للمستخدم.","تخزين سجل الطلبات.","التحقق من تسجيل الدخول."],"correct":3}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما دور الواجهة الأمامية في موقع فيديو؟","a":"عرض شاشات تشغيل الفيديو والبحث، واستقبال إجراءات المستخدم، مثل إدخال كلمات البحث أو اختيار الفيديو."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما دور قاعدة البيانات في شبكة التواصل الاجتماعي؟","a":"تخزين بيانات المنشورات وعلاقات المتابعة والرسائل، وتوفير هذه البيانات عند الحاجة."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"حدد خطوات التعاون عند إرسال بريد إلكتروني.","a":"تطبيقًا لنموذج الطبقات الثلاث: (1) يكتب المستخدم الرسالة عبر الواجهة الأمامية ويطلب إرسالها. (2) تنقل الواجهة الأمامية الطلب إلى الواجهة الخلفية لمعالجته. (3) تتعاون الواجهة الخلفية مع طبقة البيانات لحفظ البيانات المطلوبة أو استرجاعها. (4) تعود نتيجة المعالجة إلى الواجهة الأمامية لتعرضها للمستخدم. والبريد الإلكتروني مثال لتطبيق ويب، لكنه لا يفرد خطوات الإرسال تفصيلًا."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما أهمية وجود طبقة خلفية قوية في التجارة الإلكترونية؟","a":"لأن الواجهة الخلفية مسؤولة عن معالجة طلبات التطبيق وتطبيق قواعده؛ فهي تتحقق من المخزون، وترسل طلبات الدفع وتتعامل مع نتائجها، وتنسق مع قاعدة البيانات لتوفير المعلومات اللازمة. وبهذا تنفذ طلبات المستخدم التي تصل من الواجهة الأمامية."}],"3-2":[{"period":null,"kind":null,"qtype":"مقالي","q":"وضح ما هو نموذج العميل (Client) والخادم (Server)","a":"العميل (Client) هو جهاز أو برنامج يرسل طلبا إلى خدمة أخرى للحصول على بيانات أو معالجة، مثل متصفح الويب أو تطبيق الهاتف. الخادم (Server) هو الجانب الذي يستقبل طلبات العملاء ويعالجها ثم يعيد الستجابات. يعتمد نموذج العميل والخادم على إرسال العميل طلبا إلى الخادم، ثم معالجة الخادم للطلب وإرجاع استجابة إلى العميل وفق قواعد الاتصال المستخدمة."},{"period":null,"kind":null,"qtype":"مقالي","q":"صمم رسما تخطيطيا توضح فيه كيفية التواصل بين العميل والخادم. العميل (Client) متصفح الويب ⇦طلب ⇦الخادم (Server) معالجة الطلب العميل (Client) استقبال النتيجة ⇨استجابة ⇨الخادم (Server) إرجاع الاستجابة العميل يرسل طلبا إلى الخادم، ثم يعيد الخادم الاستجابة إلى العميل.","a":"يرسل العميل (مثل المتصفح) طلب HTTP/HTTPS إلى الخادم؛ يستقبل الخادم الطلب ويعالجه، ثم يرسل استجابة تعود إلى العميل."},{"period":null,"kind":null,"qtype":"موضوعي","q":"العميل في تطبيقات الويب هو:","a":"البرنامج أو الجهاز الذي يرسل الطلبات.","mcq":{"stem":"العميل في تطبيقات الويب هو:","opts":["الخادم الذي يعالج الطلبات.","البرنامج أو الجهاز الذي يرسل الطلبات.","قاعدة البيانات.","بروتوكول الاتصال."],"correct":1}},{"period":null,"kind":null,"qtype":"موضوعي","q":"عند إرسال بيانات تسجيل الدخول يُفضّل استخدام:","a":"POST.","mcq":{"stem":"عند إرسال بيانات تسجيل الدخول يُفضّل استخدام:","opts":["GET.","POST.","200.","404."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"لماذا يعتبر بروتوكول HTTPS أكثر أمانا من HTTP؟ أعط مثال.","a":"لأن HTTPS يستخدم HTTP عبر اتصال TLS آمن يحمي سرية الاتصال وسلامته ويساعد على مصادقة الخادم؛ فال يقرأ المحتوى أو يعدل بسهولة أثناء النقل. مثال: استخدام HTTPS لصفحة تسجيل الدخول لحماية البيانات المرسلة."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح الفرق بين طلب GET وطلب POST مع مثال لكل منهما.","a":"تستخدم طريقة GET عادة لطلب مورد أو بيانات من الخادم، مثل عرض صفحة ويب أو استرجاع نتائج البحث. تستخدم طريقة POST عادة لإرسال بيانات إلى الخادم لكي يعالجها، مثل إرسال نموذج تسجيل الدخول أو محتويات نموذج."},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"رمز الحالة 200 يعني:","a":"نجاح الطلب.","mcq":{"stem":"رمز الحالة 200 يعني:","opts":["خطأ داخلي في الخادم.","نجاح الطلب.","المورد غير موجود.","طلب غير مصرح به."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"رمز الحالة 404 يشير إلى:","a":"المورد غير موجود.","mcq":{"stem":"رمز الحالة 404 يشير إلى:","opts":["نجاح الطلب.","خطأ داخلي في الخادم.","المورد غير موجود.","الاتصال آمن."],"correct":2}},{"period":null,"kind":"المهام الأدائية","qtype":"مقالي","q":"فسر معنى رمز الحالة في HTTP.","a":"يعني أن الخادم عالج الطلب بنجاح؛ فهو رمز حالة HTTP يشير إلى نتيجة معالجة ناجحة."},{"period":null,"kind":"المهام الأدائية","qtype":"مقالي","q":"ماذا يعني رمز الحالة","a":"يعني أن المورد المطلوب غير موجود على العنوان المحدد، ويظهر في استجابة الخادم عندما يطلب العميل موردا غير موجود."},{"period":null,"kind":"المهام الأدائية","qtype":"موضوعي","q":"الفرق الأساسي بين HTTP وHTTPS هو:","a":"HTTPS يستخدم تشفير TLS.","mcq":{"stem":"الفرق الأساسي بين HTTP وHTTPS هو:","opts":["HTTPS يستخدم تشفير TLS.","HTTP أسرع دائمًا.","HTTPS لا يدعم POST.","HTTP يستخدم JSON."],"correct":0}},{"period":null,"kind":"المهام الأدائية","qtype":"موضوعي","q":"صيغة JSON تُستخدم في:","a":"تبادل البيانات المهيكلة.","mcq":{"stem":"صيغة JSON تُستخدم في:","opts":["تصميم واجهة المستخدم.","تبادل البيانات المهيكلة.","تشفير الاتصال.","تحديد رمز الحالة."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما دور رمز الحالة في الاتصال بين العميل والخادم؟","a":"يرسله الخادم للدلالة على حدوث خطأ داخلي فيه منع إكمال الطلب. ويوضح رمز الحالة نتيجة الطلب للعميل لكنه لا يحدد وحده السبب التفصيلي للخطأ."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما هو ال API؟ وكيف يساعد في تطوير تطبيقات الويب؟","a":"واجهة برمجة التطبيقات (API) هي مجموعة قواعد واضحة تتيح لبرنامج أن يطلب بيانات أو وظائف من برنامج آخر، وقد ترسل الواجهة الأمامية طلبا عبرها إلى خدمة خلفية وتستقبل بيانات منها. وبذلك يمكن لأجزاء التطبيق أو تطبيقات مختلفة تبادل البيانات والوظائف عبر قواعد اتصال واضحة، وقد تعيد API بيانات بصيغة JSON."},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الـ API هو:","a":"مجموعة قواعد للتواصل بين البرامج.","mcq":{"stem":"الـ API هو:","opts":["قاعدة بيانات.","مجموعة قواعد للتواصل بين البرامج.","بروتوكول أمني.","صيغة بيانات."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"عند عرض نتائج البحث من الخادم يُستخدم عادة:","a":"GET.","mcq":{"stem":"عند عرض نتائج البحث من الخادم يُستخدم عادة:","opts":["POST.","GET.","500.","HTTPS."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يمثّل دور العميل (Client) في تطبيق ويب؟","a":"إرسال الطلبات للحصول على البيانات.","mcq":{"stem":"أي من التالي يمثّل دور العميل (Client) في تطبيق ويب؟","opts":["معالجة الطلبات على الخادم.","إرسال الطلبات للحصول على البيانات.","تخزين البيانات في قاعدة البيانات.","تحديد الجمهور المستهدف للمنشورات."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يُستخدم عادة لطلب مورد أو بيانات من الخادم؟","a":"GET.","mcq":{"stem":"أي من التالي يُستخدم عادة لطلب مورد أو بيانات من الخادم؟","opts":["POST.","GET.","API.","JSON."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يُعتبر صيغة شائعة لتبادل البيانات بين التطبيقات؟","a":"JSON.","mcq":{"stem":"أي من التالي يُعتبر صيغة شائعة لتبادل البيانات بين التطبيقات؟","opts":["HTML.","JSON.","CSS.","SQL."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"رمز الحالة 404 يعني:","a":"المورد المطلوب غير موجود.","mcq":{"stem":"رمز الحالة 404 يعني:","opts":["نجاح الطلب.","خطأ داخلي في الخادم.","المورد المطلوب غير موجود.","الطلب لم يُرسل."],"correct":2}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح نموذج العميل والخادم.","a":"العميل (Client) هو جهاز أو برنامج يرسل طلبا إلى خدمة أخرى للحصول على بيانات أو معالجة، مثل متصفح الويب أو تطبيق الهاتف. الخادم (Server) هو الجانب الذي يستقبل طلبات العملاء ويعالجها ثم يعيد الستجابات. يعتمد نموذج العميل والخادم على إرسال العميل طلبا إلى الخادم، ثم معالجة الخادم للطلب وإرجاع استجابة إلى العميل وفق قواعد الاتصال المستخدمة."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"لماذا يجب استخدام HTTPS في صفحة تسجيل الدخول؟","a":"HTTPS هو استخدام HTTP عبر اتصال TLS آمن؛ ويساعد TLS على حماية سرية الاتصال وسلامته، وعلى مصادقة الخادم، فلا يستطيع المتجسس قراءة المحتوى أو تعديله بسهولة أثناء النقل. لذلك يستخدم في صفحة تسجيل الدخول لحماية البيانات المتبادلة بين العميل والخادم أثناء النقل."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما دور ال API في تطبيقات الويب؟","a":"واجهة برمجة التطبيقات (API) هي مجموعة قواعد واضحة تتيح لبرنامج أن يطلب بيانات أو وظائف من برنامج آخر، وقد ترسل الواجهة الأمامية طلبا عبرها إلى خدمة خلفية وتستقبل بيانات منها. وقد يعيد الخادم عبرها بيانات منظمة بصيغة JSON."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"فسر رمز الحالة.","a":"يشير رمز الحالة HTTP 200 إلى أن الطلب قد تمت معالجته بنجاح."},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من رموز الحالة التالية يشير إلى نجاح الطلب؟","a":"200.","mcq":{"stem":"أي من رموز الحالة التالية يشير إلى نجاح الطلب؟","opts":["200.","404.","500.","302."],"correct":0}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يُستخدم عادة لإرسال بيانات النموذج إلى الخادم؟","a":"POST.","mcq":{"stem":"أي من التالي يُستخدم عادة لإرسال بيانات النموذج إلى الخادم؟","opts":["GET.","POST.","API.","JSON."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما الواجهة التي تسمح للتطبيقات بالتواصل وتبادل البيانات؟","a":"API.","mcq":{"stem":"ما الواجهة التي تسمح للتطبيقات بالتواصل وتبادل البيانات؟","opts":["HTML.","API.","CSS.","SQL."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"اختر ما يُعتبر مثالًا على صيغة بيانات تُستخدم في تبادل المعلومات بين التطبيقات.","a":"JSON.","mcq":{"stem":"اختر ما يُعتبر مثالًا على صيغة بيانات تُستخدم في تبادل المعلومات بين التطبيقات.","opts":["XML.","JSON.","PHP.","Java."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح لماذا يعتبر نموذج الطلب والاستجابة أساسيا في تطبيقات الويب، مع ذكر مثال عملي.","a":"لأن كثيرا من تطبيقات الويب تعمل بأن يرسل العميل طلبا، فيستقبله الخادم ويعالجه ويعيد استجابة وفق قواعد HTTP. مثال: عند فتح صفحة ويب يرسل المتصفح طلبا للحصول على الصفحة، ثم يرد الخادم بالبيانات المطلوبة واستجابة تحمل نتيجة المعالجة."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"ميز بين استخدام طريقة GET وطريقة POST، وحدد مواقف مناسبة لكل منهما.","a":"تستخدم طريقة GET عادة لطلب مورد أو بيانات من الخادم، مثل عرض صفحة ويب أو استرجاع نتائج البحث. تستخدم طريقة POST عادة لإرسال بيانات إلى الخادم لكي يعالجها، مثل إرسال نموذج تسجيل الدخول أو محتويات نموذج."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح أهمية بروتوكول HTTPS في حماية البيانات أثناء النقل عبر الشبكة.","a":"HTTPS هو استخدام HTTP عبر اتصال TLS آمن؛ ويساعد TLS على حماية سرية الاتصال وسلامته، وعلى مصادقة الخادم، فال يستطيع المتجسس قراءة المحتوى أو تعديله بسهولة أثناء النقل."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"صمم طريقة اتصال مناسبة لمهمة في تطبيق ويب (مثل تسجيل مستخدم جديد)","a":"مثال تطبيقي: يدخل المستخدم بيانات التسجيل في التطبيق، ثم يرسلها العميل إلى الخادم باستخدام POST لمعالجتها، عبر HTTPS لحماية بيانات الاتصال أثناء النقل. يعالج الخادم الطلب ويعيد استجابة ورمز حالة يوضح النتيجة؛ ويدل على النجاح عند نجاح معالجة الطلب."},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من رموز الحالة التالية يشير إلى خطأ داخلي في الخادم؟","a":"500.","mcq":{"stem":"أي من رموز الحالة التالية يشير إلى خطأ داخلي في الخادم؟","opts":["200.","404.","500.","302."],"correct":2}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"إحدى هذه التقنيات تُستخدم عادة لطلب صفحة ويب أو نتائج بحث؟","a":"GET.","mcq":{"stem":"إحدى هذه التقنيات تُستخدم عادة لطلب صفحة ويب أو نتائج بحث؟","opts":["POST.","GET.","API.","JSON."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما الصيغة النصية التي تُستخدم لتمثيل البيانات المهيكلة باستخدام كائنات ومصفوفات؟","a":"JSON.","mcq":{"stem":"ما الصيغة النصية التي تُستخدم لتمثيل البيانات المهيكلة باستخدام كائنات ومصفوفات؟","opts":["HTML.","JSON.","CSS.","SQL."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يُستخدم لتأمين الاتصال بين العميل والخادم ومنع التجسس؟","a":"HTTPS.","mcq":{"stem":"أي من التالي يُستخدم لتأمين الاتصال بين العميل والخادم ومنع التجسس؟","opts":["HTTP.","HTTPS.","API.","JSON."],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يتعامل الخادم مع الطلبات الواردة من العميل، وما الذي يحدث إذا كان الطلب غير صحيح أو غير موجود. تنبيه التزاما بالكتاب: لم يحدد الدرس رمزا خاصا للطلب «غير الصحيح»، ولذلك لم يضف رمز حالة من خارج المصدر.","a":"يستقبل الخادم طلب العميل ويعالجه ثم يرسل استجابة تحتوي على نتيجة المعالجة ورمز حالة HTTP. إذا كان المورد المطلوب غير موجود تكون الاستجابة، وإذا منع خطأ داخلي في الخادم إكمال الطلب تكون، أما فيدل على نجاح المعالجة."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"فسر دور واجهات برمجة التطبيقات (API) في ربط تطبيقات مختلفة، مع مثال عملي.","a":"واجهة برمجة التطبيقات (API) هي مجموعة قواعد واضحة تتيح لبرنامج أن يطلب بيانات أو وظائف من برنامج آخر، وقد ترسل الواجهة الأمامية طلبا عبرها إلى خدمة خلفية وتستقبل بيانات منها. مثال: يطلب تطبيق طقس توقعات اليوم من خدمة الطقس عبر API، ويمكنه استلام التوقعات بصيغة JSON."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف تستخدم صيغة JSON في تبادل البيانات، ولماذا تعتبر مناسبة لتطبيقات الويب.","a":"JSON صيغة نصية شائعة لتمثيل البيانات المهيكلة وتبادلها باستخدام كائنات ومصفوفات وقيم بسيطة، وتدعمها لغات وأدوات برمجية كثيرة، وقد تعيد واجهة API البيانات بها. لذلك يمكن استعمالها في استجابات API لنقل بيانات منظمة بين أجزاء التطبيق أو التطبيقات المختلفة."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"اقترح سيناريو لتطبيق ويب يحتاج إلى استخدام طريقة POST، ووضح سبب اختيارك لها.","a":"إرسال نموذج تسجيل الدخول: يدخل المستخدم معلومات الدخول، ثم يرسلها العميل إلى الخادم بطريقة POST؛ لأنها تستخدم عادة لإرسال بيانات إلى الخادم كي يعالجها. ويفضل إجراء الاتصال عبر HTTPS لحمايته أثناء النقل."}],"3-3":[{"period":null,"kind":null,"qtype":"مقالي","q":"اشرح دور كل من HTML وCSS وJavaScript في بناء صفحة الويب.","a":"تحدد HTML بنية (هيكل) صفحة الويب، فتصف عناصر مثل العناوين والفقرات والصور والروابط. تحدد CSS مظهر صفحة الويب وتنسيقها، مثل الألوان والتخطيط والحجم والخطوط. تضيف JavaScript السلوك والتفاعلية إلى صفحة الويب، مثل استجابة الأزرار وتحديث جزء من الشاشة عند التفاعل."},{"period":null,"kind":null,"qtype":"مقالي","q":"لماذا تعتبر لغة HTML الدلالية مهمة في بناء صفحات الويب؟","a":"استخدام عناصر HTML توضح وظيفة أجزاء الصفحة، مثل <header> لرأس الصفحة، و<nav> للتنقل، و<main> للمحتوى الرئيسي، و<footer> ألسفل الصفحة. تساعد HTML الدلالية قارئ الشاشة على فهم بنية الصفحة والتنقل فيها؛ وقد تساعد محركات البحث على فهم بنية المحتوى بصورة أفضل، لكنها لا تضمن ترتيبا أعلى في نتائج البحث."},{"period":null,"kind":null,"qtype":"موضوعي","q":"لغة HTML مسؤولة عن:","a":"الهيكل الأساسي للصفحة.","mcq":{"stem":"لغة HTML مسؤولة عن:","opts":["المظهر البصري.","الهيكل الأساسي للصفحة.","السلوك التفاعلي.","تحسين الأداء."],"correct":1}},{"period":null,"kind":null,"qtype":"موضوعي","q":"أي مما يلي من عناصر صفحة الويب الدلالية (Semantic HTML) ما عدا:","a":"<E-mail>","mcq":{"stem":"أي مما يلي من عناصر صفحة الويب الدلالية (Semantic HTML) ما عدا:","opts":["<header>","<E-mail>","<main>","<footer>"],"correct":1}},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح كيف يساعد التصميم المتجاوب في تحسين تجربة المستخدم.","a":"التصميم المتجاوب مفهوم تصميمي يضبط فيه تخطيط الصفحة تلقائيا وفقا لأحجام الشاشات المختلفة، مثل الكمبيوتر والهاتف الذكي والكمبيوتر اللوحي؛ مما يحسن سهولة الاستخدام. فهو يجعل عرض الصفحة مناسبا للجهاز المستخدم، ويسهل الاطلاع على المحتوى والتعامل معه."},{"period":null,"kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح ما الفائدة من استخدام إطار عمل (Framework) في تطوير الواجهة الأمامية.","a":"إطار العمل بنية توفر وظائف ومكونات شائعة الاستخدام مسبقا فتجعل تطوير تطبيقات الويب أكثر كفاءة، وتقلل الحاجة إلى كتابة الكود كله من الصفر. كما تساعد المكتبات والأطر على بناء الصفحات بمكونات قابلة لإعادة الاستخدام."},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"لغة CSS تُستخدم في:","a":"تنسيق المظهر.","mcq":{"stem":"لغة CSS تُستخدم في:","opts":["بناء الهيكل.","إضافة التفاعل.","تنسيق المظهر.","إدارة قواعد البيانات."],"correct":2}},{"period":null,"kind":"الأداءات المنزلية","qtype":"موضوعي","q":"لغة JavaScript تضيف:","a":"السلوك التفاعلي.","mcq":{"stem":"لغة JavaScript تضيف:","opts":["العناوين والفقرات.","الألوان والخطوط.","السلوك التفاعلي.","عناصر دلالية."],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"أعط مثالًا على عنصر HTML دلالي واكتب وظيفته.","a":"العنصر <main> يستخدم لتحديد المحتوى الرئيسي للصفحة. ومن أمثلة العناصر الدلالية كذلك <header> لرأس الصفحة و<nav> للتنقل و<footer> ألسفل الصفحة."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"ناقش كيف تسهم CSS في تحسين المظهر البصري للصفحة.","a":"تحدد CSS مظهر صفحة الويب وتنسيقها، مثل الألوان والتخطيط والحجم والخطوط. فتتيح ضبط شكل النصوص وتنسيق أجزاء الصفحة وتوزيعها بصورة مناسبة."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"عنصر <header> في HTML الدلالية يُستخدم لـ:","a":"رأس الصفحة.","mcq":{"stem":"عنصر <header> في HTML الدلالية يُستخدم لـ:","opts":["المحتوى الرئيسي.","التنقل.","رأس الصفحة.","أسفل الصفحة."],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"التصميم المتجاوب يعني:","a":"ضبط التخطيط وفقًا لأحجام الشاشات المختلفة.","mcq":{"stem":"التصميم المتجاوب يعني:","opts":["ضبط التخطيط وفقًا لأحجام الشاشات المختلفة.","استخدام JavaScript فقط.","تحسين قواعد البيانات.","إخفاء المحتوى غير المهم."],"correct":0}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما الفرق بين مكتبة React وإطار Next.js؟","a":"React مكتبة JavaScript لبناء واجهات المستخدم من مكونات قابلة لإعادة الاستخدام وتحديثها عند تغير البيانات. أما Next.js إطار مبني على React لبناء تطبيقات ويب، ويوفر التوجيه وطرقا مختلفة لعرض الصفحات والعمل على الخادم والعميل."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"لماذا يعتبر نهج «الأولوية للجوال» مهمًا في التصميم المتجاوب؟","a":"نهج «الأولوية للجوال» يعني مراعاة الشاشات الصغيرة، مثل الهواتف، منذ بداية تصميم الصفحة؛ لأن كثيرا من الناس يستخدمون الويب عبر الهواتف، ثم يراعى التكيف مع الشاشات الأكبر. ويساعد ذلك على جعل الصفحة أكثر ملاءمة وسهولة للاستخدام على الأجهزة الصغيرة."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"إطار العمل React يُستخدم لـ:","a":"بناء واجهات المستخدم بمكونات قابلة لإعادة الاستخدام.","mcq":{"stem":"إطار العمل React يُستخدم لـ:","opts":["بناء واجهات المستخدم بمكونات قابلة لإعادة الاستخدام.","إدارة قواعد البيانات.","تشفير الاتصال.","تحسين الأداء فقط."],"correct":0}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"إطار العمل Next.js مبني على:","a":"React.","mcq":{"stem":"إطار العمل Next.js مبني على:","opts":["Vue.","React.","CSS.","HTML."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش دور HTML في بناء صفحة الويب.","a":"تحدد HTML بنية (هيكل) صفحة الويب، فتصف عناصر مثل العناوين والفقرات والصور والروابط. فهي المسؤولة عن البنية، بينما يستخدم CSS للمظهر وJavaScript للتفاعل عند الحاجة."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح كيف تساعد CSS في تحسين المظهر.","a":"تحدد CSS مظهر صفحة الويب وتنسيقها، مثل الألوان والتخطيط والحجم والخطوط."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما هو التصميم المتجاوب؟","a":"التصميم المتجاوب مفهوم تصميمي يضبط فيه تخطيط الصفحة تلقائيا وفقا لأحجام الشاشات المختلفة، مثل الكمبيوتر والهاتف الذكي والكمبيوتر اللوحي؛ مما يحسن سهولة الاستخدام."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما فائدة استخدام إطار عمل؟","a":"إطار العمل بنية توفر وظائف ومكونات شائعة الاستخدام مسبقا، فتجعل تطوير تطبيقات الويب أكثر كفاءة، وتقلل الحاجة إلى كتابة الكود كله من الصفر."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تُستخدم لتحديد المظهر والتنسيق في صفحة الويب؟","a":"CSS.","mcq":{"stem":"تُستخدم لتحديد المظهر والتنسيق في صفحة الويب؟","opts":["HTML.","CSS.","JavaScript.","JSON."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من عناصر HTML التالية يُستخدم لتحديد القسم الرئيسي للمحتوى؟","a":"<main>","mcq":{"stem":"أي من عناصر HTML التالية يُستخدم لتحديد القسم الرئيسي للمحتوى؟","opts":["<header>","<footer>","<main>","<nav>"],"correct":2}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"التصميم المتجاوب يعني:","a":"ضبط التخطيط تلقائيًا وفقًا لأحجام الشاشات المختلفة.","mcq":{"stem":"التصميم المتجاوب يعني:","opts":["جعل الصفحة تعمل فقط على أجهزة الكمبيوتر.","ضبط التخطيط تلقائيًا وفقًا لأحجام الشاشات المختلفة.","استخدام JavaScript لإضافة تفاعلية.","تحسين سرعة الخادم."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التالي يُعتبر مكتبة JavaScript لبناء واجهات المستخدم؟","a":"React.","mcq":{"stem":"أي من التالي يُعتبر مكتبة JavaScript لبناء واجهات المستخدم؟","opts":["React.","HTML.","CSS.","SQL."],"correct":0}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف تعمل HTML وCSS وJavaScript معا لتكوين صفحة ويب متكاملة.","a":"تحدد HTML بنية (هيكل) صفحة الويب، فتصف عناصر مثل العناوين والفقرات والصور والروابط. تحدد CSS مظهر صفحة الويب وتنسيقها، مثل الألوان والتخطيط والحجم والخطوط. تضيف JavaScript السلوك والتفاعلية إلى صفحة الويب، مثل استجابة الأزرار وتحديث جزء من الشاشة عند التفاعل. وهكذا تتكامل البنية والمظهر والسلوك بحسب احتياجات الصفحة، وليس ضروريا استخدام التقنيات الثلاث جميعا في كل صفحة."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر مثالًا على عنصر HTML دلالي، واشرح فائدته في تحسين الوصول.","a":"العنصر <nav> يحدد جزء التنقل في الصفحة؛ واستخدام العناصر الدلالية يساعد قارئ الشاشة على فهم بنية الصفحة والتنقل فيها، مع استمرار الحاجة إلى ممارسات أخرى لإمكانية الوصول."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح مفهوم «الأولوية للجوال» في التصميم المتجاوب، ولماذا يستخدم؟","a":"نهج «الأولوية للجوال» يعني مراعاة الشاشات الصغيرة، مثل الهواتف، منذ بداية تصميم الصفحة؛ لأن كثيرا من الناس يستخدمون الويب عبر الهواتف، ثم يراعى التكيف مع الشاشات الأكبر."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر اثنين من مكتبات وأطر تطوير الويب الشائعة موضحًا خصائصها.","a":"React مكتبة JavaScript لبناء واجهات المستخدم من مكونات قابلة لإعادة الاستخدام وتحديثها عند تغير البيانات. Next.js إطار مبني على React لبناء تطبيقات ويب، ويوفر التوجيه وطرقا مختلفة لعرض الصفحات والعمل على الخادم والعميل."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التقنيات التالية تُستخدم لبناء الهيكل الأساسي للصفحة؟","a":"HTML.","mcq":{"stem":"أي من التقنيات التالية تُستخدم لبناء الهيكل الأساسي للصفحة؟","opts":["CSS.","HTML.","JavaScript.","SQL."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"العنصر <nav> في HTML يُستخدم لـ:","a":"التنقل بين أجزاء الموقع.","mcq":{"stem":"العنصر <nav> في HTML يُستخدم لـ:","opts":["عرض المحتوى الرئيسي.","التنقل بين أجزاء الموقع.","عرض العنوان الرئيسي.","عرض التذييل."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ميزة التصميم المتجاوب الأساسية هي:","a":"التكيف مع مختلف أحجام الشاشات.","mcq":{"stem":"ميزة التصميم المتجاوب الأساسية هي:","opts":["تحسين سرعة الخادم.","التكيف مع مختلف أحجام الشاشات.","إضافة تفاعلية باستخدام JavaScript.","تحسين محركات البحث."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"يُعتبر إطار عمل مبنيًا على React ويوفر التوجيه وطرق عرض الصفحات:","a":"Next.js.","mcq":{"stem":"يُعتبر إطار عمل مبنيًا على React ويوفر التوجيه وطرق عرض الصفحات:","opts":["Next.js.","Vue.","HTML.","CSS."],"correct":0}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"كيف تضيف JavaScript التفاعلية إلى صفحة الويب مع مثال عملي؟","a":"تضيف JavaScript السلوك والتفاعلية إلى صفحة الويب، مثل استجابة الأزرار وتحديث جزء من الشاشة عند التفاعل. مثال: زر يعرض عدادا يتغير عند الضغط عليه، أو شاشة تحدث جزءا من بياناتها عند إدخال المستخدم."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر فوائد استخدام HTML الدلالية بالنسبة لمحركات البحث.","a":"تساعد HTML الدلالية قارئ الشاشة على فهم بنية الصفحة والتنقل فيها؛ وقد تساعد محركات البحث على فهم بنية المحتوى بصورة أفضل، لكنها لا تضمن ترتيبا أعلى في نتائج البحث. ومن أمثلتها تمييز رأس الصفحة والمحتوى الرئيسي وأجزاء التنقل."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح كيف يساعد التصميم المتجاوب في تحسين تجربة المستخدم على الهواتف الذكية.","a":"التصميم المتجاوب مفهوم تصميمي يضبط فيه تخطيط الصفحة تلقائيا وفقا لأحجام الشاشات المختلفة، مثل الكمبيوتر والهاتف الذكي والكمبيوتر اللوحي؛ مما يحسن سهولة الاستخدام. وعند استخدام الهاتف يراعى حجم شاشته منذ البداية وفق نهج «الأولوية للجوال»"},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش دور إطار العمل Next.js في تطوير تطبيقات الويب الحديثة.","a":"Next.js إطار مبني على React لبناء تطبيقات ويب، ويوفر التوجيه وطرقا مختلفة لعرض الصفحات والعمل على الخادم والعميل. وبما أنه إطار عمل، فإنه يتيح الاستفادة من وظائف ومكونات شائعة تجعل التطوير أكثر كفاءة وتقلل العمل المتكرر."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من التقنيات التالية تُستخدم لإضافة السلوك التفاعلي للصفحة؟","a":"JavaScript.","mcq":{"stem":"أي من التقنيات التالية تُستخدم لإضافة السلوك التفاعلي للصفحة؟","opts":["HTML.","CSS.","JavaScript.","SQL."],"correct":2}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"العنصر <footer> في HTML يُستخدم لـ:","a":"عرض التذييل في أسفل الصفحة.","mcq":{"stem":"العنصر <footer> في HTML يُستخدم لـ:","opts":["عرض المحتوى الرئيسي.","عرض التذييل في أسفل الصفحة.","عرض العنوان الرئيسي.","التنقل بين أجزاء الموقع."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"نهج «الأولوية للجوال» في التصميم المتجاوب يعني:","a":"تصميم الصفحة أولًا للشاشات الصغيرة مثل الهواتف.","mcq":{"stem":"نهج «الأولوية للجوال» في التصميم المتجاوب يعني:","opts":["تصميم الصفحة أولًا لأجهزة الكمبيوتر.","تصميم الصفحة أولًا للشاشات الصغيرة مثل الهواتف.","استخدام JavaScript لإضافة تفاعلية.","تحسين سرعة الخادم."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي مما يأتي يُعد إطار عمل JavaScript يتيح بناء تطبيقات تدريجيًا؟","a":"Vue.","mcq":{"stem":"أي مما يأتي يُعد إطار عمل JavaScript يتيح بناء تطبيقات تدريجيًا؟","opts":["React.","Vue.","Next.js.","HTML."],"correct":1}}],"4-1":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"قارن بين خصائص كل من التلفزيون والراديو من حيث نوع المعلومات المنقولة وطريقة الاتصال.","a":"التلفزيون ينقل الفيديو والصوت، ويصل إلى جمهور كبير في وقت واحد، وعادةً يكون الاتصال فيه من المرسل إلى المتلقي في اتجاه واحد.\nأما الراديو ينقل الصوت، ويمكن الاستماع إليه أثناء التنقل أو أداء مهام أخرى بحسب التغطية ووسيلة الاستقبال، وعادةً يكون الاتصال فيه باتجاه واحد."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح نقاط القوة والقيود الأساسية للمواقع الإلكترونية مقارنة بوسائل الإعلام التقليدية.","a":"نقاط القوة: ١) الجمع بين معلومات متنوعة مثل النص والصور والفيديو وعرضها معًا. ٢) تحديث المعلومات في أي وقت. ٣) الوصول من أي مكان يتوافر فيه اتصال مناسب بالشبكة. ٤) إمكان التفاعل ثنائي الاتجاه عبر النماذج والتعليقات وغيرها. ٥) استخدام الموقع من المتصفح، وقد تسمح بعض تطبيقات الويب أيضًا بالتثبيت. القيود: ١) تحتاج معظم وظائف الموقع إلى اتصال بالشبكة، وإن أمكن توفير محتوى أو وظائف محدودة دون اتصال في بعض الحالات. ٢) يحتاج المستخدم غالبًا إلى فتح الموقع لرؤية محتواه ما لم توجد إشعارات أو قنوات أخرى. ٣) قد تختلف سرعة العرض والتحميل بحسب جهاز المستخدم وبيئة الشبكة.\nوبخلاف الوسائط التقليدية أحادية الاتجاه، يمكن للموقع جمع وسائط متعددة وإتاحة التفاعل."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الوسائط التالية يتميز بنقل الصوت فقط وغالبًا ما يكون الاتصال فيه باتجاه واحد مع إمكانية الاستماع إليه أثناء التنقل؟","a":"الراديو.","mcq":{"stem":"أي من الوسائط التالية يتميز بنقل الصوت فقط وغالبًا ما يكون الاتصال فيه باتجاه واحد مع إمكانية الاستماع إليه أثناء التنقل؟","opts":["التلفزيون.","الراديو.","الصحيفة.","الموقع الإلكتروني."],"correct":1}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هو أحد قيود المواقع الإلكترونية؟","a":"تحتاج معظم وظائفها إلى اتصال بالشبكة.","mcq":{"stem":"ما هو أحد قيود المواقع الإلكترونية؟","opts":["لا يمكن تحديث معلوماتها في أي وقت.","تفتقر إلى إمكانية التفاعل ثنائي الاتجاه.","تحتاج معظم وظائفها إلى اتصال بالشبكة.","تقتصر على عرض النصوص فقط دون الوسائط المتعددة."],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح الغرض والوسيلة المناسبة عند الرغبة في إعلام عدد كبير من الناس في آن واحد باستخدام الفيديو.","a":"الغرض هو إيصال رسالة مصورة إلى جمهور كبير في وقت واحد. والوسيلة المناسبة هي التلفزيون؛ لأنه يجمع الفيديو والصوت ويصل إلى جمهور واسع. ويمكن استخدام إعلانات وسائل التواصل الاجتماعي كذلك لتحقيق انتشار واسع."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"لماذا تلجأ المؤسسات في الواقع العملي إلى استخدام عدة وسائط معًا (مثل توجيه المشاهد من إعلان تلفزيوني إلى موقع إلكتروني) بدلًا من وسيلة واحدة؟","a":"يمكن أن يُعلِم إعلان تلفزيوني عددًا كبيرًا من الناس بالخدمة، ويوجههم إلى موقع إلكتروني يعرض التفاصيل، ثم يشجع الموقع على مشاركة المعلومات عبر وسائل التواصل الاجتماعي. وهكذا تقوم كل وسيلة بالدور الذي تتقنه، بدل الاكتفاء بوسيلة واحدة. فالاختيار يعتمد على الغرض والجمهور، ولا توجد وسيلة واحدة هي الأفضل لكل شيء."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي الوسيلة الأنسب لإيصال معلومات حملة ترويجية مباشرة ومخصصة لأشخاص محددين؟","a":"البريد الإلكتروني أو الرسائل المباشرة.","mcq":{"stem":"ما هي الوسيلة الأنسب لإيصال معلومات حملة ترويجية مباشرة ومخصصة لأشخاص محددين؟","opts":["التلفزيون.","الموقع الإلكتروني.","البريد الإلكتروني أو الرسائل المباشرة.","الراديو."],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يُقصد بمصطلح الاتصال ثنائي الاتجاه في الوسائط الرقمية؟","a":"إمكانية الاستجابة والمشاركة من قبل المستخدمين من خلال النماذج والتعليقات.","mcq":{"stem":"ماذا يُقصد بمصطلح الاتصال ثنائي الاتجاه في الوسائط الرقمية؟","opts":["اتصال يكون من المرسل إلى المستقبل فقط دون أي رد.","إمكانية الاستجابة والمشاركة من قبل المستخدمين من خلال النماذج والتعليقات.","قراءة محتوى مطبوع دون أي اتصال بالإنترنت.","الاستماع إلى البث الصوتي أثناء أداء مهام أخرى."],"correct":1}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"كيف تختلف الصحيفة عن الموقع الإلكتروني من حيث طبيعة الوسائط المتاحة وإمكانية الاتصال والتحديث؟","a":"الصحيفة تنقل النصوص والصور، وتبقى موجودة ماديًا كوسيلة مطبوعة يمكن قراءتها دون اتصال بالإنترنت، واتصالها أحادي الاتجاه.\nأما الموقع الإلكتروني يجمع النصوص والصور والصوت والفيديو، ويمكن تحديث محتواه في أي وقت. وهو اتصال من اتجاه واحد أساسًا، لكن يمكن إتاحة التفاعل ثنائي الاتجاه عبر النماذج والتعليقات وغيرها. وبذلك تتجاوز وسائط الموقع النص والصور إلى الصوت والفيديو، ويمكن تحديثه وإضافة استجابة للمستخدمين."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"اذكر وسيلة إعلامية مناسبة لتحقيق انتشار واسع وسريع للمعلومات، مع بيان سبب اختيارها.؟","a":"وسائل التواصل الاجتماعي مناسبة لنشر المعلومات بسرعة، لأنها تسمح للمستخدمين بمشاركة المحتوى ونشره والتفاعل معه. ويمكن استخدام التلفزيون أو إعلانات التواصل إذا كان الغرض إعلام جمهور كبير في وقت واحد."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الوسائط التالية تبقى موجودة ماديًا كوسيلة مطبوعة ويمكن قراءتها دون اتصال بالإنترنت؟","a":"الصحيفة.","mcq":{"stem":"أي من الوسائط التالية تبقى موجودة ماديًا كوسيلة مطبوعة ويمكن قراءتها دون اتصال بالإنترنت؟","opts":["التلفزيون.","وسائل التواصل الاجتماعي.","الصحيفة.","الموقع الإلكتروني."],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات التالية يمثل الغرض الأنسب لاستخدام وسائل التواصل الاجتماعي؟","a":"الانتشار عن طريق التناقل الشفهي ونشر المعلومات بسرعة ومشاركتها.","mcq":{"stem":"أي من الخيارات التالية يمثل الغرض الأنسب لاستخدام وسائل التواصل الاجتماعي؟","opts":["تقديم معلومات تفصيلية ومنظمة في صفحات وأقسام متعددة.","إتاحة معلومات مطبوعة ورقية دون اتصال.","الانتشار عن طريق التناقل الشفهي ونشر المعلومات بسرعة ومشاركتها.","إيصال معلومات فردية ومباشرة لشخص محدد فقط."],"correct":2}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يمكن للموقع الإلكتروني الجمع بين معلومات متنوعة ودعم التفاعل ثنائي الاتجاه.؟","a":"يمكن للموقع الجمع بين النص والصور والصوت والفيديو وعرضها معًا، وتحديث المعلومات في أي وقت. ورغم أن العرض في اتجاه واحد أساسًا، يمكن للمستخدمين الاستجابة والمشاركة عبر النماذج والتعليقات وغيرها، وبذلك يتحقق التفاعل ثنائي الاتجاه."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر اثنين من العيوب أو القيود المحتملة لاستخدام موقع إلكتروني كقناة رئيسية لمؤسسة خدمية تخاطب عائلات قد لا تملك اتصالًا منزليًا بالإنترنت.؟","a":"١) تحتاج معظم وظائف الموقع إلى اتصال بالشبكة، مما قد يصعّب وصول العائلات التي لا يتوافر لها اتصال مناسب.\n٢) يحتاج المستخدم غالبًا إلى فتح الموقع بنفسه ليرى المحتوى، ما لم تستخدم المؤسسة إشعارات أو قنوات أخرى. ويمكن الاستعانة بوسائط أخرى تصل إلى الجمهور وفق ظروفه."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما الذي يميز وسائل التواصل الاجتماعي عن الوسائط التقليدية مثل التلفزيون والراديو؟","a":"قدرتها على نشر المعلومات بسرعة وتمكين المستخدمين من النشر والمشاركة والتفاعل.","mcq":{"stem":"ما الذي يميز وسائل التواصل الاجتماعي عن الوسائط التقليدية مثل التلفزيون والراديو؟","opts":["تقتصر على اتجاه واحد من المرسل إلى المستقبل.","قدرتها على نشر المعلومات بسرعة وتمكين المستخدمين من النشر والمشاركة والتفاعل.","كونها وسيلة مطبوعة تبقى موجودة ماديًا دون الحاجة لكهرباء.","نقل الصوت فقط دون أي صور أو نصوص."],"correct":1}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"عند اختيار الوسيلة الإعلامية المناسبة لنقل المعلومات، على ماذا يعتمد الاختيار بشكل أساسي؟","a":"الغرض والجمهور المستهدف والموارد المتاحة.","mcq":{"stem":"عند اختيار الوسيلة الإعلامية المناسبة لنقل المعلومات، على ماذا يعتمد الاختيار بشكل أساسي؟","opts":["الغرض والجمهور المستهدف والموارد المتاحة.","تفضيل الوسائل الورقية حصرًا في جميع الأحوال.","تجنب استخدام الإنترنت تمامًا.","الاكتفاء بوسيلة واحدة لجميع أنواع الجماهير."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"قارن بالتفصيل بين خصائص التلفزيون والصحيفة من حيث نوع المعلومات المنقولة وطريقة الاتصال والاعتماد على شبكة الإنترنت.","a":"التلفزيون ينقل الفيديو والصوت، ويصل إلى جمهور كبير في وقت واحد، وعادةً يكون الاتصال فيه من المرسل إلى المتلقي في اتجاه واحد.\nأما الصحيفة تنقل النصوص والصور، وتبقى موجودة ماديًا كوسيلة مطبوعة يمكن قراءتها دون اتصال بالإنترنت، واتصالها أحادي الاتجاه. ويُبيّن الكتاب أن الصحيفة تُقرأ دون إنترنت، ولا يشترط في وصف التلفزيون التقليدي اتصال المشاهد بالإنترنت."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح نقاط القوة الخمس الرئيسية للمواقع الإلكترونية.","a":"١) الجمع بين معلومات متنوعة مثل النص والصور والفيديو وعرضها معًا. ٢) تحديث المعلومات في أي وقت. ٣) الوصول من أي مكان يتوافر فيه اتصال مناسب بالشبكة. ٤) إمكان التفاعل ثنائي الاتجاه عبر النماذج والتعليقات وغيرها. ٥) استخدام الموقع من المتصفح، وقد تسمح بعض تطبيقات الويب أيضًا بالتثبيت."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"بيّن كيف تتكامل وسائل الإعلام المختلفة في الواقع العملي عبر ضرب مثال عملي يجمع بين التلفزيون والموقع الإلكتروني ووسائل التواصل الاجتماعي.","a":"يمكن أن يُعلِم إعلان تلفزيوني عددًا كبيرًا من الناس بالخدمة، ويوجههم إلى موقع إلكتروني يعرض التفاصيل، ثم يشجع الموقع على مشاركة المعلومات عبر وسائل التواصل الاجتماعي. وهكذا تقوم كل وسيلة بالدور الذي تتقنه، بدل الاكتفاء بوسيلة واحدة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش القيود الثلاثة للمواقع الإلكترونية موضحًا تأثير كل قيد على تجربة المستخدم.","a":"١) الاتصال بالشبكة: إذا لم يتوافر اتصال مناسب، فقد لا يتمكن المستخدم من الاستفادة من معظم الوظائف، مع وجود استثناءات محدودة مصممة للعمل دون اتصال.\n٢) ضرورة فتح الموقع: قد تفوت المستخدم المعلومات إذا لم يزره، ما لم توجد إشعارات أو قنوات أخرى.\n٣) اختلاف سرعة العرض والتحميل: قد يتأخر ظهور المحتوى بحسب جهاز المستخدم وبيئة الشبكة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي الوسيلة التي تجمع بين الفيديو والصوت وعادةً يكون الاتصال فيها من المرسل إلى المتلقي للوصول إلى جمهور كبير؟","a":"التلفزيون.","mcq":{"stem":"ما هي الوسيلة التي تجمع بين الفيديو والصوت وعادةً يكون الاتصال فيها من المرسل إلى المتلقي للوصول إلى جمهور كبير؟","opts":["الصحيفة.","التلفزيون.","الراديو.","البريد الإلكتروني."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الآتي يُعد من نقاط قوة المواقع الإلكترونية؟","a":"يمكن تحديث المعلومات فيها في أي وقت والتفاعل مع المستخدمين.","mcq":{"stem":"أي من الآتي يُعد من نقاط قوة المواقع الإلكترونية؟","opts":["تقتصر على اتجاه واحد دائمًا ولا تقبل التعليقات.","تحتاج حتمًا لشبكة الإنترنت في كل وظائفها دون استثناء.","يمكن تحديث المعلومات فيها في أي وقت والتفاعل مع المستخدمين.","لا يمكن عرض الصور أو الفيديو فيها."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي الوسيلة الأنسب إذا كان الغرض إتاحة كمية كبيرة من المعلومات وتفاصيلها وتنظيمها في صفحات وأقسام متعددة؟","a":"الموقع الإلكتروني.","mcq":{"stem":"ما هي الوسيلة الأنسب إذا كان الغرض إتاحة كمية كبيرة من المعلومات وتفاصيلها وتنظيمها في صفحات وأقسام متعددة؟","opts":["الراديو.","الصحيفة المطبوعة.","الموقع الإلكتروني.","الرسائل النصية المباشرة."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الوسيلة التي تتيح للمستخدمين نشر المعلومات ومشاركتها بسرعة هي:","a":"وسائل التواصل الاجتماعي.","mcq":{"stem":"الوسيلة التي تتيح للمستخدمين نشر المعلومات ومشاركتها بسرعة هي:","opts":["الصحيفة.","التلفزيون.","وسائل التواصل الاجتماعي.","الراديو."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح خصائص الراديو موضحًا مميزاته في الاستماع أثناء التنقل وقيود اتصاله أحادي الاتجاه.","a":"الراديو ينقل الصوت، ويمكن الاستماع إليه أثناء التنقل أو أداء مهام أخرى بحسب التغطية ووسيلة الاستقبال، وعادةً يكون الاتصال فيه باتجاه واحد. وميزة التنقل أن المستمع يستطيع متابعة الصوت في مواقف مختلفة بحسب التغطية ووسيلة الاستقبال، لكن الاتصال يكون غالبًا من المرسل إلى المتلقي دون رد مباشر عبر البث نفسه."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح كيف يمكن للمواقع الإلكترونية توفير تفاعل ثنائي الاتجاه موضحًا الأدوات المستخدمة في ذلك.","a":"يمكن أن يستقبل الموقع استجابات المستخدمين ومشاركاتهم عبر النماذج والتعليقات وغيرها، فلا يقتصر الاستخدام على عرض المعلومات من المرسل إلى المتلقي، بل يصبح التفاعل ثنائي الاتجاه ممكنًا."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر الغرض المناسب لكل من الوسائط الآتية: (التلفزيون، الموقع الإلكتروني، البريد الإلكتروني، وسائل التواصل الاجتماعي).","a":"التلفزيون: إعلام عدد كبير من الناس في وقت واحد. الموقع الإلكتروني: تقديم معلومات كثيرة وتفصيلية في صفحات وأقسام تُحدَّث عند الحاجة.\nالبريد الإلكتروني: إرسال المعلومات بصورة مباشرة إلى أشخاص محددين.\nوسائل التواصل الاجتماعي: الانتشار السريع عن طريق المشاركة والتناقل بين المستخدمين."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش التحديات التي تواجه المؤسسات عند محاولة الوصول إلى جمهور بلا إنترنت منزلي، وما هي البدائل أو الحلول الإعلامية المتاحة.","a":"التحدي هو أن معظم وظائف الموقع الإلكتروني تحتاج إلى اتصال بالشبكة، وأن المستخدم قد يحتاج إلى زيارة الموقع ليرى المعلومات. لذلك تختار المؤسسة وسائط أخرى بحسب الجمهور والموارد: مثل الصحيفة المطبوعة التي يمكن قراءتها دون إنترنت، والراديو بحسب التغطية، والتلفزيون للانتشار الواسع؛ ويمكن الجمع بينها وبين الموقع بدل الاعتماد عليه وحده."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"وسيلة إعلامية تعتمد على الصوت فقط ويمكن الاستماع إليها أثناء أداء مهام أخرى بحسب التغطية هي:","a":"الراديو.","mcq":{"stem":"وسيلة إعلامية تعتمد على الصوت فقط ويمكن الاستماع إليها أثناء أداء مهام أخرى بحسب التغطية هي:","opts":["التلفزيون.","الراديو.","الموقع الإلكتروني.","الصحيفة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تقنية أو وسيلة تتيح التوصيل بشكل فردي ومباشر لأشخاص محددين هي:","a":"البريد الإلكتروني أو الرسائل المباشرة.","mcq":{"stem":"تقنية أو وسيلة تتيح التوصيل بشكل فردي ومباشر لأشخاص محددين هي:","opts":["التلفزيون.","وسائل التواصل الاجتماعي.","البريد الإلكتروني أو الرسائل المباشرة.","الصحيفة اليومية."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"من قيود المواقع الإلكترونية التي تم توضيحها في الدرس:","a":"غالبًا يحتاج المستخدم إلى فتح الموقع للوصول إلى محتواه ما لم تتوفر إشعارات.","mcq":{"stem":"من قيود المواقع الإلكترونية التي تم توضيحها في الدرس:","opts":["استحالة تحديث محتواها بعد إنشائها.","غالبًا يحتاج المستخدم إلى فتح الموقع للوصول إلى محتواه ما لم تتوفر إشعارات.","عدم إمكانية دمج الصور والنصوص معًا.","كونها وسيلة مطبوعة ورقية بالكامل."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي العبارات التالية تعبير دقيق عن الفكرة الرئيسية لاختيار الوسائط؟","a":"لا توجد وسيلة واحدة هي الأفضل لكل شيء، ويجب الاختيار بناءً على الغرض والجمهور مع الجمع بين الوسائط.","mcq":{"stem":"أي العبارات التالية تعبير دقيق عن الفكرة الرئيسية لاختيار الوسائط؟","opts":["توجد وسيلة واحدة مثالية ومطلوبة لكل الأغراض بشكل دائم.","لا توجد وسيلة واحدة هي الأفضل لكل شيء، ويجب الاختيار بناءً على الغرض والجمهور مع الجمع بين الوسائط.","يجب دائمًا استخدام التلفزيون وحده لتجنب تكلفة الإنترنت.","وسائل التواصل الاجتماعي تغني عن أي موقع إلكتروني أو وسيلة أخرى نهائيًا."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش دور الصحف المطبوعة وخصائصها مقارنة بالوسائط الرقمية الحديثة من حيث الاتصال والوجود المادي.","a":"الصحيفة تنقل النصوص والصور، وتبقى موجودة ماديًا كوسيلة مطبوعة يمكن قراءتها دون اتصال بالإنترنت، واتصالها أحادي الاتجاه. وعلى العكس، يمكن للموقع الإلكتروني جمع وسائط متعددة وتحديث محتواه، وقد يتيح التفاعل ثنائي الاتجاه عبر النماذج والتعليقات، كما تمكّن وسائل التواصل المستخدمين من النشر والمشاركة والتفاعل."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يمكن اختيار الوسيلة الإعلامية المناسبة بناءً على تحليل الجمهور والغرض والرسالة المستهدفة.","a":"يعتمد اختيار الوسيلة المناسبة على الغرض من الرسالة والجمهور المستهدف والموارد المتاحة؛ فالتلفزيون وإعلانات التواصل للانتشار الواسع، والموقع للتفاصيل، والبريد الإلكتروني أو الرسائل المباشرة لأشخاص محددين، ووسائل التواصل للمشاركة والتناقل بين المستخدمين. لذلك تُراعى طبيعة الرسالة والجمهور الذي يراد الوصول إليه، ولا تُستخدم وسيلة واحدة لجميع الأغراض."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تحدث عن أهمية الجمع بين الوسائط المختلفة في الحملات الإعلامية وتوجيه الجمهور بينها بفعالية.","a":"يمكن أن يُعلِم إعلان تلفزيوني عددًا كبيرًا من الناس بالخدمة، ويوجههم إلى موقع إلكتروني يعرض التفاصيل، ثم يشجع الموقع على مشاركة المعلومات عبر وسائل التواصل الاجتماعي. وهكذا تقوم كل وسيلة بالدور الذي تتقنه، بدل الاكتفاء بوسيلة واحدة. ويساعد هذا التكامل على الجمع بين الانتشار الواسع والتفاصيل وإمكانية المشاركة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح المقصود بمصطلحي «الاتصال أحادي الاتجاه» و«الاتصال ثنائي الاتجاه» مع أمثلة لكل منهما.","a":"الاتصال أحادي الاتجاه هو نقل المعلومات من المرسل إلى المتلقي دون استجابة مباشرة ضمن الوسيلة نفسها، مثل التلفزيون أو الراديو أو الصحيفة. أما الاتصال ثنائي الاتجاه يُمكن المستخدمين من الاستجابة والمشاركة، مثل استخدام النماذج والتعليقات في المواقع الإلكترونية، وكذلك التفاعل في وسائل التواصل الاجتماعي."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"وسيلة مطبوعة تبقى موجودة ماديًا ويمكن قراءتها دون اتصال بالإنترنت وتتكون من نص وصور هي:","a":"الصحيفة.","mcq":{"stem":"وسيلة مطبوعة تبقى موجودة ماديًا ويمكن قراءتها دون اتصال بالإنترنت وتتكون من نص وصور هي:","opts":["التلفزيون.","الصحيفة.","الموقع الإلكتروني.","الراديو."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الوسائط التالية يُعد الأنسب لتحقيق انتشار واسع عبر التناقل الشفهي ومشاركة المستخدمين؟","a":"وسائل التواصل الاجتماعي.","mcq":{"stem":"أي من الوسائط التالية يُعد الأنسب لتحقيق انتشار واسع عبر التناقل الشفهي ومشاركة المستخدمين؟","opts":["الراديو.","الصحيفة المطبوعة.","وسائل التواصل الاجتماعي.","البريد الإلكتروني الفردي."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"من الخصائص الأساسية للموقع الإلكتروني أنه:","a":"اتجاه واحد أساسًا، لكن التفاعل ثنائي الاتجاه ممكن من خلال النماذج والتعليقات.","mcq":{"stem":"من الخصائص الأساسية للموقع الإلكتروني أنه:","opts":["اتجاه واحد أساسًا، لكن التفاعل ثنائي الاتجاه ممكن من خلال النماذج والتعليقات.","ينقل الصوت فقط ولا يدعم النصوص أو الصور.","لا يمكن تحديثه أبدًا بعد النشر الأول.","يستحيل الوصول إليه عبر متصفحات الهواتف المحمولة."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الغرض الأساسي من استخدام إعلانات التلفزيون أو إعلانات وسائل التواصل الاجتماعي هو:","a":"إعلام عدد كبير من الناس في آن واحد بانتشار واسع.","mcq":{"stem":"الغرض الأساسي من استخدام إعلانات التلفزيون أو إعلانات وسائل التواصل الاجتماعي هو:","opts":["تقديم تفاصيل دقيقة وموسعة في صفحات متعددة.","إعلام عدد كبير من الناس في آن واحد بانتشار واسع.","إرسال رسالة سرية لشخص واحد فقط.","قراءة مقالات طويلة دون إنترنت."],"correct":1}}],"4-2":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح المقصود بمفهوم «شخصية المستخدم (Persona)»، وبيّن كيف تساعد فريق العمل في عملية التصميم دون الاعتماد على الافتراضات الشخصية.","a":"شخصية المستخدم (Persona) تمثيل لنوع من المستخدمين يُبنى قدر الإمكان على بحث أو بيانات عن أهدافهم واحتياجاتهم وسلوكهم وسياق استخدامهم وتحدياتهم. وتُذكر معلومات كالعمر أو المهنة فقط إذا كانت ذات صلة بالتصميم. وهي تساعد الفريق على مناقشة احتياجات المستخدمين بدل الافتراضات الشخصية، وليست خطوة إلزامية في كل مشروع."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"وضّح الغرض الأساسي من استخدام «المخطط الهيكلي (Wireframe)» قبل الانتقال إلى التصميم البصري، ولماذا يُعد تحديده أولًا خطوة ضرورية للوصول إلى اتفاق بين أصحاب المصلحة.","a":"المخطط الهيكلي (Wireframe) مخطط أولي يوضح أماكن العناصر وأولويات المعلومات بتفاصيل بصرية قليلة، قبل الألوان والخطوط والزخارف. يساعد الفريق وأصحاب المصلحة على الاتفاق على توزيع المعلومات بدل الانشغال بتفضيلات المظهر الشخصية. فإذا اختيرت الزخارف أولًا، فقد ينصرف النقاش إلى الأذواق بدل أولويات المحتوى."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات التالية يمثل التعريف الأدق لمصطلح «شخصية المستخدم (Persona)»؟","a":"تمثيل لنوع أو نمط من المستخدمين يستند قدر الإمكان إلى بحث أو بيانات عن أهدافهم واحتياجاتهم وسلوكهم وسياقهم.","mcq":{"stem":"أي من الخيارات التالية يمثل التعريف الأدق لمصطلح «شخصية المستخدم (Persona)»؟","opts":["تمثيل بنسخته النهائية يتضمن الألوان والزخارف التصميمية المعقدة.","تمثيل لنوع أو نمط من المستخدمين يستند قدر الإمكان إلى بحث أو بيانات عن أهدافهم واحتياجاتهم وسلوكهم وسياقهم.","أداة لتقييم أداء خادم الموقع الإلكتروني وسرعة استجابته التقنية.","نهج تصميم يعطي الأولوية لراحة منشئ الموقع ومطوريه فقط."],"correct":1}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ماذا يمثل «المخطط الهيكلي (Wireframe)» في مراحل بناء وتخطيط مواقع الويب؟","a":"مخطط أولي لتحديد أماكن العناصر وأولوياتها بمعزل عن التصميم البصري.","mcq":{"stem":"ماذا يمثل «المخطط الهيكلي (Wireframe)» في مراحل بناء وتخطيط مواقع الويب؟","opts":["تصميم بصري نهائي يحتوي على كافة الألوان والخطوط الزخرفية.","خوارزمية برمجة خلفية لتنظيم قواعد البيانات.","مخطط أولي لتحديد أماكن العناصر وأولوياتها بمعزل عن التصميم البصري.","أداة قياس سرعة تحميل صفحات الإنترنت عبر الهواتف الذكية."],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر الفارق الأساسي بين تصميم الموقع بالاعتماد على ذوق المصمم الشخصي وبين الاعتماد على نهج «التصميم المتمحور حول المستخدم (UCD)».","a":"الاعتماد على الذوق الشخصي يجعل قرارات التصميم مبنية على تفضيلات المصمم التي قد لا تناسب الزائر. أما التصميم المتمحور حول المستخدم (UCD) نهج يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم أساسًا لقرارات التصميم. يبدأ بفهم المهمة وظروف الاستخدام، ثم تنظيم المعلومات وتصميم الحل واختباره مع المستخدمين وتحسينه بصورة تكرارية. ولذلك يُقيَّم التصميم بما يحقق أهداف المستخدم، لا بجماله بالنسبة للمصمم وحده."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ما المقصود بمصطلحي «قابلية الاستخدام (Usability)» و«إمكانية الوصول (Accessibility)» في سياق تصميم المواقع الإلكترونية؟","a":"قابلية الاستخدام (Usability) هي مدى سهولة وفاعلية إنجاز المستخدم لمهمته داخل الموقع. أما إمكانية الوصول (Accessibility) فتعني تصميم المحتوى والواجهة لتمكين أصحاب القدرات والاحتياجات المختلفة، بمن فيهم ذوو الإعاقة، من استخدام الموقع والتفاعل معه. وهما هدفان يحتاجان إلى اختبار ومعايير مناسبة؛ ولا تكفي المبادئ البصرية وحدها لتحقيقهما."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يشير إلى مدى سهولة وفاعلية إنجاز المستخدم للمهمة المطلوبة داخل الموقع الإلكتروني؟","a":"قابلية الاستخدام.","mcq":{"stem":"ما هو المصطلح الذي يشير إلى مدى سهولة وفاعلية إنجاز المستخدم للمهمة المطلوبة داخل الموقع الإلكتروني؟","opts":["إمكانية الوصول.","قابلية الاستخدام.","التقارب الهيكلي.","التباين البصري."],"correct":1}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الآتي يعبر بدقة عن مفهوم «إمكانية الوصول (Accessibility)» في تصميم الويب؟","a":"تصميم المحتوى والواجهة بحيث يمكن للأشخاص ذوي الإعاقة استخدام الموقع والتفاعل معه، بمن فيهم ذوو الاحتياجات الخاصة.","mcq":{"stem":"أي من الآتي يعبر بدقة عن مفهوم «إمكانية الوصول (Accessibility)» في تصميم الويب؟","opts":["تصميم المحتوى والواجهة بحيث يمكن للأشخاص ذوي الإعاقة استخدام الموقع والتفاعل معه، بمن فيهم ذوو الاحتياجات الخاصة.","تحديد أماكن العناصر وأولوياتها باستخدام تفاصيل بصرية قليلة.","تجميع المعلومات المرتبطة قريبة من بعضها في الشاشة الواحدة.","توحيد خط ولون العناوين في جميع صفحات الموقع الإلكتروني."],"correct":0}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح مبدأ «التباين» من مبادئ CRAP، وبيّن كيف يمكن للمصمم تطبيقه بفعالية لإبراز أهم العناصر وجعل أولوية المعلومات واضحة للمستخدم.","a":"التباين (Contrast): إبراز العناصر المهمة وجعل أولوية المعلومات واضحة فورًا؛ مثل إظهار العناوين بوضوح قياسًا بالنص، وإبراز الأزرار المهمة مع مراعاة سهولة القراءة وعدم الاعتماد على اللون وحده."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"وضّح بالتفصيل كيف يحقق مبدأ «التقارب (Proximity)» تنظيم المعلومات بحيث يدركها المستخدم كمجموعة واحدة من أول نظرة.","a":"التقارب (Proximity): وضع المعلومات المرتبطة قريبة من بعضها لتُدرك كمجموعة واحدة من أول نظرة؛ كجمع صورة المنتج واسمه وسعره مع ترك هوامش مناسبة بين المجموعات. فربط العناصر القريبة بعضها ببعض يوضح ما يتعلق بكل منتج، والمسافات بين المجموعات تميز مجموعة عن غيرها."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الإجراءات الآتية يمثل التطبيق العملي لمبدأ «التكرار (Repetition)» من مبادئ CRAP في تصميم صفحات الموقع؟","a":"توحيد اللون والحجم والخط للعناوين في كل صفحة ومطابقة تصميم أيقونات النقاط.","mcq":{"stem":"أي من الإجراءات الآتية يمثل التطبيق العملي لمبدأ «التكرار (Repetition)» من مبادئ CRAP في تصميم صفحات الموقع؟","opts":["جعل العناوين ضخمة ومتغيرة الألوان عشوائيًا في كل صفحة.","توحيد اللون والحجم والخط للعناوين في كل صفحة ومطابقة تصميم أيقونات النقاط.","تشتيت انتباه المستخدم بتوزيع العناصر في أركان الشاشة بشكل متباعد.","إخفاء أزرار التنقل الرئيسية داخل قوائم فرعية معقدة."],"correct":1}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي القاعدة الأساسية التي يعتمد عليها مبدأ «المحاذاة (Alignment)» في تصميم واجهات المستخدم باللغة العربية؟","a":"محاذاة العناصر حسب اتجاه اللغة وشبكة التصميم بحيث يكون اتجاه النص الأساسي من اليمين إلى اليسار باستخدام قواعد متسقة.","mcq":{"stem":"ما هي القاعدة الأساسية التي يعتمد عليها مبدأ «المحاذاة (Alignment)» في تصميم واجهات المستخدم باللغة العربية؟","opts":["محاذاة النص الأساسي والعناصر من اليسار إلى اليمين حصرًا.","توزيع العناصر عشوائيًا دون الالتزام بخط أساس مشترك.","محاذاة العناصر حسب اتجاه اللغة وشبكة التصميم بحيث يكون اتجاه النص الأساسي من اليمين إلى اليسار باستخدام قواعد متسقة.","الاعتماد على الزخارف الهندسية المعقدة لتغطية مساحات الفراغ."],"correct":2}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر المبادئ الأربعة للتصميم المعروفة بمبادئ (CRAP)، واشرح باختصار الغرض الأساسي من استخدامها في تنظيم شكل صفحات الويب.","a":"١) التباين (Contrast): إبراز العناصر المهمة وجعل أولوية المعلومات واضحة فورًا؛ مثل إظهار العناوين بوضوح قياسًا بالنص، وإبراز الأزرار المهمة مع مراعاة سهولة القراءة وعدم الاعتماد على اللون وحده. ٢) التكرار (Repetition): تكرار الخصائص مثل اللون والحجم والخط في الصفحات لتحقيق اتساق التصميم وتسهيل التنقل دون تشتت؛ مثل توحيد شكل العناوين وأيقونات النقاط. ٣) المحاذاة (Alignment): تنظيم مواقع العناصر وفق خط أساس مشترك وشبكة تصميم متسقة. في الصفحات العربية يُراعى اتجاه النص الأساسي من اليمين إلى اليسار، مع محاذاة العناصر وفق اللغة والتخطيط. ٤) التقارب (Proximity): وضع المعلومات المرتبطة قريبة من بعضها لتُدرك كمجموعة واحدة من أول نظرة؛ كجمع صورة المنتج واسمه وسعره مع ترك هوامش مناسبة بين المجموعات. وتساعد هذه المبادئ على تنظيم الشكل وتسهيل فهم الصفحة، لكنها لا تغني عن اختبارات قابلية الاستخدام وإمكانية الوصول."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف تتكامل خطوات التصميم بدءًا من تصور «شخصية المستخدم» مرورًا بـ«المخطط الهيكلي» ووصولًا إلى تطبيق مبادئ «CRAP» للوصول إلى تصميم ناجح متمحور حول المستخدم.","a":"نبدأ بفهم احتياجات المستخدم وسياق استخدامه، ونستخدم شخصية مستخدم تستند إلى بيانات إذا كانت مفيدة، ثم نحدد أماكن المعلومات وأولوياتها بمخطط هيكلي قبل المظهر، ونطبق مبادئ التباين والتكرار والمحاذاة والتقارب، ثم نختبر قابلية الاستخدام وإمكانية الوصول مع المستخدمين ونحسن التصميم تكراريًا. شخصية المستخدم أداة ممكنة وليست شرطًا في كل مشروع."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المبدأ التصميمي من مبادئ CRAP الذي يختص بتجميع صور المنتجات وأسمائها وأسعارها قريبة من بعضها وترك مسافات هادفة بينها؟","a":"التقارب.","mcq":{"stem":"ما هو المبدأ التصميمي من مبادئ CRAP الذي يختص بتجميع صور المنتجات وأسمائها وأسعارها قريبة من بعضها وترك مسافات هادفة بينها؟","opts":["التباين.","التكرار.","المحاذاة.","التقارب."],"correct":3}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يُعد الخيار غير المناسب أو المعلومة غير الملائمة عند إعداد «شخصية نموذجية (Persona)» للمستخدم المستهدف؟","a":"أداء خادم الموقع الإلكتروني وسرعة استجابته التقنية.","mcq":{"stem":"أي من الخيارات التالية يُعد الخيار غير المناسب أو المعلومة غير الملائمة عند إعداد «شخصية نموذجية (Persona)» للمستخدم المستهدف؟","opts":["غرض المستخدم من استخدام الموقع الإلكتروني.","أداء خادم الموقع الإلكتروني وسرعة استجابته التقنية.","عمر المستخدم ومهنته وسياق استخدامه.","التحديات والصعوبات التي يواجهها المستخدم."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش أهمية فهم المستخدم وسياق استخدامه كخطوة أولى في تصميم الويب الجيد، وكيف يحمي ذلك التصميم من الوقوع في فخ الاعتماد على ذوق المصمم الشخصي.","a":"التصميم المتمحور حول المستخدم (UCD) نهج يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم أساسًا لقرارات التصميم. يبدأ بفهم المهمة وظروف الاستخدام، ثم تنظيم المعلومات وتصميم الحل واختباره مع المستخدمين وتحسينه بصورة تكرارية. فالموقع الذي يبدو منطقيًا للمصمم قد يربك زواره، لذا تُستخدم احتياجاتهم ومهامهم وظروف استعمالهم أساسًا للاختيارات، بدل تفضيلات المصمم."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح الغرض التقني والتصميمي من استخدام «المخطط الهيكلي (Wireframe)»، موضحًا لماذا يتم تأجيل اختيار الألوان والخطوط والزخارف إلى المراحل اللاحقة.","a":"المخطط الهيكلي (Wireframe) مخطط أولي يوضح أماكن العناصر وأولويات المعلومات بتفاصيل بصرية قليلة، قبل الألوان والخطوط والزخارف. يساعد الفريق وأصحاب المصلحة على الاتفاق على توزيع المعلومات بدل الانشغال بتفضيلات المظهر الشخصية. ويتيح هذا ترتيب البنية والمحتوى ومراجعتها قبل الانشغال بالشكل النهائي."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"عدّد مبادئ التصميم الأربعة (CRAP) مع بيان الغرض الوظيفي لكل مبدأ في تسهيل فهم الصفحة وتجربة تصفح المستخدم.","a":"١) التباين (Contrast): إبراز العناصر المهمة وجعل أولوية المعلومات واضحة فورًا؛ مثل إظهار العناوين بوضوح قياسًا بالنص، وإبراز الأزرار المهمة مع مراعاة سهولة القراءة وعدم الاعتماد على اللون وحده. ٢) التكرار (Repetition): تكرار الخصائص مثل اللون والحجم والخط في الصفحات لتحقيق اتساق التصميم وتسهيل التنقل دون تشتت؛ مثل توحيد شكل العناوين وأيقونات النقاط. ٣) المحاذاة (Alignment): تنظيم مواقع العناصر وفق خط أساس مشترك وشبكة تصميم متسقة. في الصفحات العربية يُراعى اتجاه النص الأساسي من اليمين إلى اليسار، مع محاذاة العناصر وفق اللغة والتخطيط. ٤) التقارب (Proximity): وضع المعلومات المرتبطة قريبة من بعضها لتُدرك كمجموعة واحدة من أول نظرة؛ كجمع صورة المنتج واسمه وسعره مع ترك هوامش مناسبة بين المجموعات."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بالتفصيل دور نهج «التصميم المتمحور حول المستخدم (UCD)» في تحسين مؤشرات قابلية الاستخدام وإمكانية الوصول الرقمي لذوي الاحتياجات الخاصة.","a":"التصميم المتمحور حول المستخدم (UCD) نهج يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم أساسًا لقرارات التصميم. يبدأ بفهم المهمة وظروف الاستخدام، ثم تنظيم المعلومات وتصميم الحل واختباره مع المستخدمين وتحسينه بصورة تكرارية. ويستهدف تحسين سهولة وفاعلية إنجاز المهام، وتمكين الأشخاص ذوي الإعاقة من استخدام الموقع؛ ويتطلب الحكم على ذلك اختبارات ومعايير مناسبة، فالتنسيق البصري وحده غير كافٍ. ويمكن أن تشمل المراجعة وضوح التباين وإمكانية استخدام لوحة المفاتيح وتوافر النص البديل، وهي أمثلة مذكورة في تطبيقات الدرس."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"بم يبدأ تصميم الويب الجيد؟","a":"من فهم المستخدم واحتياجاته وسياق استخدامه لا على ذوق المصمم فقط.","mcq":{"stem":"بم يبدأ تصميم الويب الجيد؟","opts":["من فهم المستخدم واحتياجاته وسياق استخدامه لا على ذوق المصمم فقط.","من اختيار الألوان والزخارف البصرية الفاخرة أولًا.","من كتابة الأكواد البرمجية الخلفية وقواعد البيانات.","من زيادة سرعة خادم الاستضافة فقط."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو الوصف الصحيح لـ«المخطط الهيكلي (Wireframe)»؟","a":"مخطط أولي لتحديد أماكن العناصر وأولوياتها بتفاصيل بصرية قليلة قبل التصميم النهائي.","mcq":{"stem":"ما هو الوصف الصحيح لـ«المخطط الهيكلي (Wireframe)»؟","opts":["مخطط أولي لتحديد أماكن العناصر وأولوياتها بتفاصيل بصرية قليلة قبل التصميم النهائي.","تصميم نهائي مدمج بالرسومات والصور عالية الدقة.","ملف برمجي لتنفيذ عمليات الدفع الإلكتروني.","أداة اختبار سرعة تصفح الإنترنت عبر الجوال."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو الغرض من تطبيق مبدأ «التباين (Contrast)» في تصميم صفحات الويب؟","a":"جعل العناوين واضحة وإبراز العناصر المهمة فورًا.","mcq":{"stem":"ما هو الغرض من تطبيق مبدأ «التباين (Contrast)» في تصميم صفحات الويب؟","opts":["جعل العناوين واضحة وإبراز العناصر المهمة فورًا.","توحيد خط ولون العناوين في كل الصفحات.","تجميع العناصر المرتبطة قريبة من بعضها.","محاذاة النصوص وفق خط أساس مشترك."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي مما يأتي يمثل المفهوم الدقيق للتصميم المتمحور حول المستخدم؟","a":"نهج يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم أساسًا لقرارات التصميم.","mcq":{"stem":"أي مما يأتي يمثل المفهوم الدقيق للتصميم المتمحور حول المستخدم؟","opts":["نهج يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم أساسًا لقرارات التصميم.","إعطاء الأولوية لراحة منشئ الموقع ومطوريه.","الاعتماد المطلق على ذوق المصمم الفردي.","تخطي مرحلة تقييم ومراجعة الموقع مع المستخدمين الفعليين."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يسهم بناء «شخصية المستخدم (Persona)» المستندة إلى بحث أو بيانات حقيقية في مساعدة فريق العمل على مناقشة احتياجات نمط معين من المستخدمين بدقة.","a":"شخصية المستخدم (Persona) تمثيل لنوع من المستخدمين يُبنى قدر الإمكان على بحث أو بيانات عن أهدافهم واحتياجاتهم وسلوكهم وسياق استخدامهم وتحدياتهم. وتُذكر معلومات كالعمر أو المهنة فقط إذا كانت ذات صلة بالتصميم. وهي تساعد الفريق على مناقشة احتياجات المستخدمين بدل الافتراضات الشخصية، وليست خطوة إلزامية في كل مشروع. فحين تستند المناقشة إلى أهداف المستخدم وسلوكه وتحدياته، تقل الافتراضات الشخصية ويتجه التخطيط إلى ما يحتاجه فعلًا."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضّح بالتفصيل كيف يساهم تطبيق مبدأ «التباين (Contrast)» في إبراز العناوين والأزرار المهمة مع مراعاة سهولة القراءة وعدم الاعتماد على اللون وحده.","a":"التباين (Contrast): إبراز العناصر المهمة وجعل أولوية المعلومات واضحة فورًا؛ مثل إظهار العناوين بوضوح قياسًا بالنص، وإبراز الأزرار المهمة مع مراعاة سهولة القراءة وعدم الاعتماد على اللون وحده. والمطلوب أن يظهر المهم بوضوح للمستخدم، مع عدم جعل تمييز المعلومات قائمًا على اختلاف اللون وحده."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"بيّن بالأمثلة كيف يطبق مصمم المواقع مبدأ «المحاذاة (Alignment)» لإنشاء نظام بصري متناسق على الشاشة وفقًا لشبكة التصميم واتجاه اللغة.","a":"المحاذاة (Alignment): تنظيم مواقع العناصر وفق خط أساس مشترك وشبكة تصميم متسقة. في الصفحات العربية يُراعى اتجاه النص الأساسي من اليمين إلى اليسار، مع محاذاة العناصر وفق اللغة والتخطيط. مثال: محاذاة الحواف اليمنى للعناوين والفقرات والعناصر المرتبطة ضمن شبكة واحدة، بدل أن يبدأ كل عنصر في موضع عشوائي."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح العلاقة التكاملية بين دورة حياة التصميم المتمحور حول المستخدم (UCD) واختبار الحلول مع المستخدمين لتحسين وتطوير الواجهات تكراريًا.","a":"التصميم المتمحور حول المستخدم (UCD) نهج يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم أساسًا لقرارات التصميم. يبدأ بفهم المهمة وظروف الاستخدام، ثم تنظيم المعلومات وتصميم الحل واختباره مع المستخدمين وتحسينه بصورة تكرارية. وتكشف الاختبارات ما يربك المستخدم أو يصعّب إنجاز مهمته، فيُعدّل الفريق الحل ويعيد تقييمه. وتظل قابلية الاستخدام وإمكانية الوصول هدفين يُختبران ولا يتحققان تلقائيًا بتطبيق مبادئ الشكل."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي الفائدة الأساسية من استخدام «شخصية المستخدم (Persona)» في مشاريع الويب؟","a":"مساعدة الفريق على مناقشة احتياجات نمط من المستخدمين بدل الافتراضات الشخصية.","mcq":{"stem":"ما هي الفائدة الأساسية من استخدام «شخصية المستخدم (Persona)» في مشاريع الويب؟","opts":["مساعدة الفريق على مناقشة احتياجات نمط من المستخدمين بدل الافتراضات الشخصية.","زيادة عدد زوار الموقع عبر محركات البحث.","تقليل حجم ملفات الصور والوسائط في الصفحة.","تسريع تحميل صفحات الويب على الأجهزة الذكية."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من المبادئ الأربعة للتصميم يُعنى بمحاذاة مواضع العناصر إلى خط أساس مشترك لمنح الشاشة نظامًا؟","a":"المحاذاة.","mcq":{"stem":"أي من المبادئ الأربعة للتصميم يُعنى بمحاذاة مواضع العناصر إلى خط أساس مشترك لمنح الشاشة نظامًا؟","opts":["التباين.","التكرار.","المحاذاة.","التقارب."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يفعل مبدأ «التكرار (Repetition)» في تصميم صفحات الموقع الإلكتروني؟","a":"يكرر خصائص معينة كاللون والحجم والخط لتحقيق الاتساق ومساعدة المستخدم على التنقل دون تشتت.","mcq":{"stem":"ماذا يفعل مبدأ «التكرار (Repetition)» في تصميم صفحات الموقع الإلكتروني؟","opts":["يكرر خصائص معينة كاللون والحجم والخط لتحقيق الاتساق ومساعدة المستخدم على التنقل دون تشتت.","يجمع العناصر المرتبطة ببعضها في مكان واحد.","يبرز العناصر المهمة عبر إيجاد فروق بصرية واضحة.","يحدد أماكن العناصر وأولوياتها بمعزل عن التصميم البصري."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو الهدف من دراسة «قابلية الاستخدام (Usability)» و«إمكانية الوصول (Accessibility)»؟","a":"تحسين سهولة وفاعلية إنجاز المهمة وتمكين ذوي الإعاقة من استخدام الموقع بفاعلية.","mcq":{"stem":"ما هو الهدف من دراسة «قابلية الاستخدام (Usability)» و«إمكانية الوصول (Accessibility)»؟","opts":["قياس سرعة أداء الخادم التقني.","تحسين سهولة وفاعلية إنجاز المهمة وتمكين ذوي الإعاقة من استخدام الموقع بفاعلية.","تقليل تكلفة شراء النطاقات والاستضافة.","تصميم الأكواد البرمجية للغات الخلفية."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضّح كيف يمكن لمخطط هيكلي مصمم بعناية أن يسهل على أصحاب المصلحة والفريق التقني الوصول إلى اتفاق بشأن توزيع المعلومات ومواضعها بمعزل عن المظهر البصري.","a":"المخطط الهيكلي (Wireframe) مخطط أولي يوضح أماكن العناصر وأولويات المعلومات بتفاصيل بصرية قليلة، قبل الألوان والخطوط والزخارف. يساعد الفريق وأصحاب المصلحة على الاتفاق على توزيع المعلومات بدل الانشغال بتفضيلات المظهر الشخصية. فعند التركيز على أين تظهر المعلومة ومدى أولويتها، يستطيع المعنيون مناقشة هيكل الصفحة دون الخلاف حول الألوان والزينة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"قارن بين مبدأ «التكرار (Repetition)» ومبدأ «التقارب (Proximity)» من حيث الأثر البصري المترتب على كل منهما في تنظيم محتوى صفحات الويب.","a":"التكرار (Repetition): تكرار الخصائص مثل اللون والحجم والخط في الصفحات لتحقيق اتساق التصميم وتسهيل التنقل دون تشتت؛ مثل توحيد شكل العناوين وأيقونات النقاط. أما التقارب (Proximity): وضع المعلومات المرتبطة قريبة من بعضها لتُدرك كمجموعة واحدة من أول نظرة؛ كجمع صورة المنتج واسمه وسعره مع ترك هوامش مناسبة بين المجموعات. فالأول يوحد المظهر عبر الصفحات، والثاني يجمع المعلومات المترابطة داخل الصفحة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يؤدي تجاهل معايير «إمكانية الوصول (Accessibility)» إلى حرمان فئات معينة من المستخدمين (مثل ضعاف البصر أو ذوي الإعاقة) من التفاعل الفعّال مع خدمات الموقع الإلكتروني.","a":"قابلية الاستخدام (Usability) هي مدى سهولة وفاعلية إنجاز المستخدم لمهمته داخل الموقع. أما إمكانية الوصول (Accessibility) فتعني تصميم المحتوى والواجهة لتمكين أصحاب القدرات والاحتياجات المختلفة، بمن فيهم ذوو الإعاقة، من استخدام الموقع والتفاعل معه. وهما هدفان يحتاجان إلى اختبار ومعايير مناسبة؛ ولا تكفي المبادئ البصرية وحدها لتحقيقهما. وإذا أهملت متطلبات مثل التباين المناسب أو إمكان استخدام لوحة المفاتيح أو النص البديل، فقد تصبح بعض المعلومات أو الوظائف صعبة الوصول لبعض المستخدمين. لذلك يلزم اختبار التصميم ومعالجة حواجز الوصول."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تحدث بالتفصيل عن الخطوات المتسلسلة لعملية التصميم المتمحور حول المستخدم، بدءًا من دراسة الاحتياجات مرورًا بتنظيم المعلومات ووصولًا للتقييم والاختبار.","a":"نبدأ بفهم احتياجات المستخدم وسياق استخدامه، ونستخدم شخصية مستخدم تستند إلى بيانات إذا كانت مفيدة، ثم نحدد أماكن المعلومات وأولوياتها بمخطط هيكلي قبل المظهر، ونطبق مبادئ التباين والتكرار والمحاذاة والتقارب، ثم نختبر قابلية الاستخدام وإمكانية الوصول مع المستخدمين ونحسن التصميم تكراريًا. ويُعاد تحسين الحل بناءً على الاختبار؛ وليست شخصية المستخدم شرطًا لازمًا في كل مشروع."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المبدأ التصميمي المسؤول عن تجميع المعلومات المرتبطة (كصور المنتجات وأسعارها) قريبة من بعضها؟","a":"التقارب.","mcq":{"stem":"ما هو المبدأ التصميمي المسؤول عن تجميع المعلومات المرتبطة (كصور المنتجات وأسعارها) قريبة من بعضها؟","opts":["التقارب.","التباين.","التكرار.","المحاذاة."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يُقصد بمفهوم «التصميم المتمحور حول المستخدم (UCD)»؟","a":"نهج تصميم يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم أساسًا لقرارات التصميم.","mcq":{"stem":"ماذا يُقصد بمفهوم «التصميم المتمحور حول المستخدم (UCD)»؟","opts":["نهج تصميم يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم أساسًا لقرارات التصميم.","طريقة لبرمجة قواعد البيانات بأسلوب متقدم.","تصميم واجهات تعتمد بالكامل على الحدس الشخصي للمطور.","أداة لتقييم أخطاء الشبكات والاتصال بالإنترنت."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو السبب الرئيسي لتأجيل اختيار الألوان والخطوط والزخارف لحين الانتهاء من إعداد «المخطط الهيكلي»؟","a":"لمنع انحراف النقاشات نحو التفضيلات الشخصية للمظهر وتسهيل اتفاق أصحاب المصلحة على بنية المعلومات.","mcq":{"stem":"ما هو السبب الرئيسي لتأجيل اختيار الألوان والخطوط والزخارف لحين الانتهاء من إعداد «المخطط الهيكلي»؟","opts":["لمنع انحراف النقاشات نحو التفضيلات الشخصية للمظهر وتسهيل اتفاق أصحاب المصلحة على بنية المعلومات.","لزيادة سرعة معالجة الرسوميات في متصفح المستخدم.","لتقليل مساحة تخزين الموقع على الخادم.","لتجنب استخدام لغات البرمجة الحديثة."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يُعد التطبيق الصحيح لمبدأ «المحاذاة» في النصوص العربية؟","a":"جعل اتجاه النص الأساسي من اليمين إلى اليسار وفق قواعد متسقة.","mcq":{"stem":"أي من الخيارات التالية يُعد التطبيق الصحيح لمبدأ «المحاذاة» في النصوص العربية؟","opts":["جعل اتجاه النص الأساسي من اليمين إلى اليسار وفق قواعد متسقة.","جعل اتجاه النص من اليسار إلى اليمين حصرًا.","توزيع الكلمات بشكل عشوائي في أركان الشاشة.","إخفاء النصوص داخل قوائم منسدلة معقدة."],"correct":0}}],"4-3":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"ما الفرق الأساسي بين التقييم النوعي والتقييم الكمي من حيث التركيز والهدف لكل منهما في تقييم المواقع الإلكترونية؟","a":"التقييم النوعي يركز على فهم تجربة المستخدم وأسباب السلوك والصعوبات من خلال الملاحظة واختبارات قابلية الاستخدام والمقابلات، ويُستخدم التقييم الإرشادي القائم على مراجعة الخبراء أيضًا لدراسة مشكلات الواجهة.\nأما التقييم الكمي يركز على قياس السلوك والنتائج بالأرقام والمقاييس العددية المحددة، باستخدام تحليلات الويب واختبار A/B.\nفالأول يساعد في معرفة «لماذا» تحدث الصعوبات، والثاني في قياس «كم» يحدث من سلوك أو نتائج."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح المقصود بـ«اختبار قابلية الاستخدام» كإحدى أدوات التقييم النوعي وكيف يساهم في تحسين واجهة المستخدم.","a":"في اختبار قابلية الاستخدام يُطلب من مستخدمين استكشاف الموقع وتنفيذ مهام فعلية، ثم تُراقَب عمليات الاستخدام لتحديد المواضع التي يصعب استعمالها.\nو تساعد الملاحظات في فهم الصعوبات وتوجيه تحسينات واجهة المستخدم."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الطرق التالية يُعد من أدوات التقييم النوعي لفهم تجربة المستخدم وأسباب السلوك؟","a":"اختبار قابلية الاستخدام.","mcq":{"stem":"أي من الطرق التالية يُعد من أدوات التقييم النوعي لفهم تجربة المستخدم وأسباب السلوك؟","opts":["اختبار قابلية الاستخدام.","تحليلات الويب.","اختبار A/B.","معدل التحويل (CVR)."],"correct":0}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هو مصطلح التقييم الذي يركز على القياس بالأرقام واستخدام بيانات عددية ومقاييس محددة بوضوح؟","a":"التقييم الكمي.","mcq":{"stem":"ما هو مصطلح التقييم الذي يركز على القياس بالأرقام واستخدام بيانات عددية ومقاييس محددة بوضوح؟","opts":["التقييم النوعي.","التقييم الإرشادي.","التقييم الكمي.","المقابلات المباشرة."],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضّح بإيجاز المقصود بمفهوم «تحليلات الويب» وكيف تُعتبر إحدى أدوات التقييم الكمي.","a":"تحليلات الويب هي جمع بيانات استخدام الموقع وقياسها وتحليلها لفهم الوصول والتفاعل والنتائج.\nوهي تقييم كمي يعتمد على مؤشرات عددية، وتختلف أسماء بعض المقاييس وتعريفاتها وطرق حسابها حسب أداة التحليل وإعداداتها."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر اثنين من المؤشرات الرئيسية في تحليلات الويب مع بيان الغرض من كل منهما.","a":"١) مشاهدات الصفحة (PV): العدد الإجمالي لمرات مشاهدة الصفحة، وقد يتضمن مشاهدات مكررة؛ لذلك لا يساوي عدد الزوار أو الأشخاص الفريدين، ولا يفسر بمفرده أسباب سلوكهم.\n٢) معدل التحويل (CVR): نسبة المستخدمين أو الجلسات التي حققت إجراءً مستهدفًا، مثل التسجيل أو الشراء، بحسب هدف الموقع؛ ويجب تحديد المقام وطريقة الحساب."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يمثل مؤشر (PV) في تحليلات الويب؟","a":"العدد الإجمالي لمرات مشاهدة الصفحة.","mcq":{"stem":"ماذا يمثل مؤشر (PV) في تحليلات الويب؟","opts":["نسبة المستخدمين الذين حققوا هدفًا محددًا.","العدد الإجمالي لمرات مشاهدة الصفحة.","نسبة المستخدمين الذين غادروا بعد الصفحة الأولى.","معدل الارتداد الكلي للموقع."],"correct":1}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المؤشر الذي يقيس نسبة المستخدمين أو الجلسات التي حققت إجراءً مستهدفًا مثل التسجيل أو الشراء؟","a":"معدل التحويل (CVR).","mcq":{"stem":"ما هو المؤشر الذي يقيس نسبة المستخدمين أو الجلسات التي حققت إجراءً مستهدفًا مثل التسجيل أو الشراء؟","opts":["مشاهدات الصفحة (PV).","معدل الارتداد.","معدل التحويل (CVR).","التقييم الإرشادي."],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"عرّف «التقييم الإرشادي» وممن يتم إجراؤه؟ وما هي علاقته بقواعد واجهة المستخدم؟","a":"التقييم الإرشادي (Heuristic Evaluation) مراجعة يجريها خبراء لواجهة المستخدم اعتمادًا على قواعد أو مبادئ إرشادية عملية؛بهدف تحديد مشكلات قابلية الاستخدام. تُستخدم القواعد الإرشادية لمراجعة اتساق الواجهة، ومنع الأخطاء، ووضوح حالة النظام."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"اذكر ثلاثة أمثلة على القواعد الإرشادية المستخدمة في تقييم واجهة المستخدم واشرح واحدة منها باختصار.","a":"القواعد الثلاث المذكورة في الدرس: ١) الاتساق: هل التصميم والعمليات موحدة عبر الموقع؟ ٢) منع الأخطاء: هل يصعّب التصميم على المستخدم ارتكاب الأخطاء؟ ٣) وضوح حالة النظام: هل يعرف المستخدم بوضوح ما يحدث، مثل ظهور مؤشر معالجة أو رسالة خطأ في الإدخال؟"},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ماذا يُقصد بمصطلح «التقييم الإرشادي (Heuristic Evaluation)»؟","a":"مراجعة يجريها خبراء لواجهة المستخدم استنادًا إلى قواعد عملية.","mcq":{"stem":"ماذا يُقصد بمصطلح «التقييم الإرشادي (Heuristic Evaluation)»؟","opts":["قياس السلوك بالأرقام والبيانات العددية.","مراجعة يجريها خبراء لواجهة المستخدم استنادًا إلى قواعد عملية.","اختبار خيارين لمعرفة أيهما يحقق نتائج أفضل.","إحصاء إجمالي عدد زيارات الصفحات."],"correct":1}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من الخيارات التالية يُعد من القواعد الإرشادية الأساسية لواجهة المستخدم؟","a":"منع الأخطاء.","mcq":{"stem":"أي من الخيارات التالية يُعد من القواعد الإرشادية الأساسية لواجهة المستخدم؟","opts":["معدل الارتداد (Bounce Rate).","إجمالي مشاهدات الصفحة (PV).","منع الأخطاء.","معدل التحويل (CVR)."],"correct":2}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"لماذا يُعد الجمع بين التقييم النوعي والتقييم الكمي أكثر فائدة عند تقييم موقع إلكتروني مقارنة بالاعتماد على أحدهما فقط؟","a":"القياس الكمي يوضح مقدار السلوك والنتائج بالأرقام، لكنه لا يشرح السبب وحده. أما التقييم النوعي فيكشف أسباب الصعوبات وآراء المستخدمين، لكنه لا يمثل جميع المستخدمين بالضرورة. لذلك يُفيد الجمع بين النوعين في تفسير المشكلة وتوجيه التحسين."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بإيجاز كيف يمكن الاستفادة من «اختبار A/B» في قياس سلوك المستخدمين ونتائج التصميم.","a":"اختبار A/B أسلوب من التقييم الكمي يقارن خيارين أو نسختين من التصميم لمعرفة أيهما يحقق نتائج أفضل بالاعتماد على القياس. تُقارن نتائج النسختين وفق مقياس محدد يناسب هدف الموقع، ويُستفاد من المقارنة في اختيار البديل الأفضل."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من المؤشرات التالية يعبر عن نسبة الجلسات أو المستخدمين الذين غادروا الموقع بعد مشاهدة الصفحة الأولى فقط؟","a":"معدل الارتداد (Bounce Rate).","mcq":{"stem":"أي من المؤشرات التالية يعبر عن نسبة الجلسات أو المستخدمين الذين غادروا الموقع بعد مشاهدة الصفحة الأولى فقط؟","opts":["مشاهدات الصفحة (PV).","معدل التحويل (CVR).","معدل الارتداد (Bounce Rate).","التقييم الإرشادي."],"correct":2}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"عندما تظهر تحليلات الويب ارتفاعًا كبيرًا في عدد المشاهدات (PV) مع انخفاض ملحوظ في معدل التحويل (CVR)، فإن ذلك يدل على:","a":"أن مستخدمين كثيرين يصلون للصفحة لكنهم لا يكملون الإجراء المستهدف.","mcq":{"stem":"عندما تظهر تحليلات الويب ارتفاعًا كبيرًا في عدد المشاهدات (PV) مع انخفاض ملحوظ في معدل التحويل (CVR)، فإن ذلك يدل على:","opts":["أن جميع الزوار قد أكملوا عمليات الشراء بنجاح.","أن مستخدمين كثيرين يصلون للصفحة لكنهم لا يكملون الإجراء المستهدف.","عدم وجود أي زيارات نهائية للموقع.","نجاح التصميم بالكامل دون الحاجة إلى أي تقييم نوعي."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"قارن بين التقييم النوعي والتقييم الكمي موضحًا التقنيات المستخدمة في كل فئة.","a":"التقييم النوعي يركز على فهم تجربة المستخدم وأسباب السلوك والصعوبات من خلال الملاحظة واختبارات قابلية الاستخدام والمقابلات، ويُستخدم التقييم الإرشادي القائم على مراجعة الخبراء أيضًا لدراسة مشكلات الواجهة. أما التقييم الكمي يركز على قياس السلوك والنتائج بالأرقام والمقاييس العددية المحددة، باستخدام تحليلات الويب واختبار A/B. النوعي يساعد على فهم السبب، والكمي يقيس مقدار السلوك والنتائج."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح مؤشر مشاهدات الصفحة (PV) ومؤشر معدل التحويل (CVR) موضحًا أهمية كل منهما وحدود استخدامهما.","a":"مشاهدات الصفحة (PV): العدد الإجمالي لمرات مشاهدة الصفحة، وقد يتضمن مشاهدات مكررة؛ لذلك لا يساوي عدد الزوار أو الأشخاص الفريدين، ولا يفسر بمفرده أسباب سلوكهم. يفيد في قياس حجم مشاهدة المحتوى. أما معدل التحويل (CVR): نسبة المستخدمين أو الجلسات التي حققت إجراءً مستهدفًا، مثل التسجيل أو الشراء، بحسب هدف الموقع؛ ويجب تحديد المقام وطريقة الحساب. يفيد في قياس تحقيق هدف محدد؛ ولا يكفي أي منهما منفردًا لتفسير أسباب النتائج، كما يجب مراجعة تعريف المقياس وطريقة حسابه."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تحدث عن «التقييم الإرشادي» مبينًا تعريفه، ومن يقوم به، وأهم القواعد الإرشادية المستخدمة في فحص واجهة المستخدم.","a":"التقييم الإرشادي (Heuristic Evaluation) مراجعة يجريها خبراء لواجهة المستخدم اعتمادًا على قواعد أو مبادئ إرشادية عملية؛ ويُستخدم إلى جانب اختبار قابلية الاستخدام وطرق أخرى لدراسة مشكلات الواجهة. القواعد الثلاث: ١) الاتساق: هل التصميم والعمليات موحدة عبر الموقع ٢) منع الأخطاء: هل يصعّب التصميم على المستخدم ارتكاب الأخطاء ٣) وضوح حالة النظام: هل يعرف المستخدم بوضوح ما يحدث، مثل ظهور مؤشر معالجة أو رسالة خطأ في الإدخال"},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضّح لماذا لا يكفي المؤشر الكمي وحده لتفسير سبب مغادرة الزوار للموقع، وكيف تساهم الطرق النوعية في سد هذه الثغرة.","a":"المؤشرات مثل مشاهدات الصفحة أو معدل الارتداد تُظهر مقادير وأنماطًا ولا تحدد بمفردها أسباب المغادرة. ويمكن إجراء مقابلات أو اختبار قابلية استخدام لملاحظة ما يربك المستخدم واستيضاح أسباب الصعوبة، ثم الجمع بين النتيجتين. معدل الارتداد (Bounce Rate) مؤشر يمكن أن يساعد مع مؤشرات أخرى على ملاحظة ضعف التفاعل، لكنه لا يفسر السبب وحده. تختلف طريقة تعريفه وحسابه باختلاف أداة التحليل وإعداداتها؛ ومن صوره التعليمية المبسطة نسبة الجلسات التي تنتهي بعد مشاهدة صفحة واحدة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي الفئتين الأساسيتين تركز على الفهم التفصيلي لتجربة المستخدم وأسباب السلوك؟","a":"التقييم النوعي.","mcq":{"stem":"أي الفئتين الأساسيتين تركز على الفهم التفصيلي لتجربة المستخدم وأسباب السلوك؟","opts":["التقييم النوعي.","التقييم الكمي.","تحليلات الويب.","اختبار A/B."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يقيس مؤشر مشاهدات الصفحة (PV) في تحليلات الويب؟","a":"العدد الإجمالي لمرات مشاهدة الصفحة.","mcq":{"stem":"ماذا يقيس مؤشر مشاهدات الصفحة (PV) في تحليلات الويب؟","opts":["نسبة المستخدمين الذين غادروا الموقع.","العدد الإجمالي لمرات مشاهدة الصفحة.","نسبة التحويلات المكتملة فقط.","عدد الزوار الفريدين بدقة تامة."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يُطلق على مراجعة الخبراء لواجهة المستخدم استنادًا إلى قواعد عملية؟","a":"التقييم الإرشادي.","mcq":{"stem":"ما هو المصطلح الذي يُطلق على مراجعة الخبراء لواجهة المستخدم استنادًا إلى قواعد عملية؟","opts":["التقييم الإرشادي.","اختبار قابلية الاستخدام.","معدل الارتداد.","التقييم الكمي."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يُعد الوصف الصحيح لاختبار قابلية الاستخدام؟","a":"مراقبة العمليات الفعلية لتحديد النقاط التي يصعب استخدامها.","mcq":{"stem":"أي من الخيارات التالية يُعد الوصف الصحيح لاختبار قابلية الاستخدام؟","opts":["قياس السلوك بالأرقام والبيانات العددية.","مراقبة العمليات الفعلية لتحديد النقاط التي يصعب استخدامها.","مقارنة خيارين للتحقق من أيهما أفضل.","تحليل بيانات الويب تلقائيًا."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يتم تنفيذ «اختبار قابلية الاستخدام» وما هي الأهداف الأساسية من ورائه في دراسة سلوك المستخدمين.","a":"في اختبار قابلية الاستخدام يُطلب من مستخدمين استكشاف الموقع وتنفيذ مهام فعلية، ثم تُراقَب عمليات الاستخدام لتحديد المواضع التي يصعب استعمالها. تساعد الملاحظات في فهم الصعوبات وتوجيه تحسينات واجهة المستخدم. والهدف هو معرفة المواضع التي تربك المستخدم أثناء المهمة وتفسير الصعوبات المحتملة بدل الاكتفاء بالبيانات العددية."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تحدث عن تحليلات الويب باعتبارها أدوات تقييم كمي، موضحًا تنوع طرق حساب المؤشرات وأهمية مراجعة تعريف الأداة المستخدمة.","a":"تحليلات الويب هي جمع بيانات استخدام الموقع وقياسها وتحليلها لفهم الوصول والتفاعل والنتائج. وهي تقييم كمي يعتمد على مؤشرات عددية، وتختلف أسماء بعض المقاييس وتعريفاتها وطرق حسابها حسب أداة التحليل وإعداداتها. ومن المؤشرات: مشاهدات الصفحة (PV): العدد الإجمالي لمرات مشاهدة الصفحة، وقد يتضمن مشاهدات مكررة؛ لذلك لا يساوي عدد الزوار أو الأشخاص الفريدين، ولا يفسر بمفرده أسباب سلوكهم. معدل الارتداد (Bounce Rate) مؤشر يمكن أن يساعد مع مؤشرات أخرى على ملاحظة ضعف التفاعل، لكنه لا يفسر السبب وحده. تختلف طريقة تعريفه وحسابه باختلاف أداة التحليل وإعداداتها؛ ومن صوره التعليمية المبسطة نسبة الجلسات التي تنتهي بعد مشاهدة صفحة واحدة. معدل التحويل (CVR): نسبة المستخدمين أو الجلسات التي حققت إجراءً مستهدفًا، مثل التسجيل أو الشراء، بحسب هدف الموقع؛ ويجب تحديد المقام وطريقة الحساب."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر القواعد الإرشادية الثلاث المذكورة في الدرس لواجهة المستخدم واشرح مفهوم «وضوح حالة النظام» و«الاتساق».","a":"القواعد الثلاث المذكورة في الدرس: ١) الاتساق: هل التصميم والعمليات موحدة عبر الموقع\n٢) منع الأخطاء: هل يصعّب التصميم على المستخدم ارتكاب الأخطاء\n٣) وضوح حالة النظام: هل يعرف المستخدم بوضوح ما يحدث، مثل ظهور مؤشر معالجة أو رسالة خطأ في الإدخال"},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يمكن لفريق الموقع الجمع بين الأدلة العددية (الكمية) وآراء المستخدمين (النوعية) للوصول إلى تقييم شامل ودقيق.","a":"يمكن للفريق قياس المشاهدات أو معدل التحويل لتحديد موضع المشكلة، ثم ملاحظة المستخدمين في اختبار قابلية الاستخدام أو الاستماع إلى آرائهم في مقابلات لفهم الأسباب المحتملة؛ ويجمع الدليلين قبل اقتراح تحسين واختباره. القياس الكمي يوضح مقدار السلوك والنتائج بالأرقام، لكنه لا يشرح السبب وحده. أما التقييم النوعي فيكشف أسباب الصعوبات وآراء المستخدمين، لكنه لا يمثل جميع المستخدمين بالضرورة. لذلك يُفيد الجمع بين النوعين في تفسير المشكلة وتوجيه التحسين."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي التقنية التي تبدأ بمراقبة العمليات الفعلية باستخدام الموقع عبر الملاحظة والمقابلات؟","a":"اختبار قابلية الاستخدام.","mcq":{"stem":"ما هي التقنية التي تبدأ بمراقبة العمليات الفعلية باستخدام الموقع عبر الملاحظة والمقابلات؟","opts":["اختبار A/B.","اختبار قابلية الاستخدام.","التقييم الإرشادي.","تحليلات الويب."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي التقنية التي تقارن بين خيارين أو تصميمين للتحقق من أيهما يؤدي إلى نتائج أفضل؟","a":"اختبار A/B.","mcq":{"stem":"ما هي التقنية التي تقارن بين خيارين أو تصميمين للتحقق من أيهما يؤدي إلى نتائج أفضل؟","opts":["تحليلات الويب.","التقييم الإرشادي.","اختبار A/B.","اختبار قابلية الاستخدام."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا يمثل مؤشر (PV) في أدوات تحليلات الويب؟","a":"إجمالي مرات مشاهدة الصفحة.","mcq":{"stem":"ماذا يمثل مؤشر (PV) في أدوات تحليلات الويب؟","opts":["إجمالي مرات مشاهدة الصفحة.","معدل التحويل للأهداف.","نسبة الارتداد للموقع.","القواعد الإرشادية للخبراء."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المصطلح الذي يعبر عن نسبة الجلسات أو المستخدمين الذين غادروا الموقع بعد مشاهدة الصفحة الأولى فقط؟","a":"معدل الارتداد (Bounce Rate).","mcq":{"stem":"ما هو المصطلح الذي يعبر عن نسبة الجلسات أو المستخدمين الذين غادروا الموقع بعد مشاهدة الصفحة الأولى فقط؟","opts":["معدل التحويل.","مشاهدات الصفحة.","معدل الارتداد (Bounce Rate).","التقييم الإرشادي."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضّح دور المقابلات المباشرة في التقييم النوعي وكيف تساعد في الاستماع إلى آراء المستخدمين واحتياجاتهم واستيائهم.","a":"المقابلات من أدوات التقييم النوعي؛ إذ تتيح الاستماع مباشرة إلى آراء المستخدمين حول تجربة الموقع، وما يحتاجونه وما يسبب عدم رضاهم، فتساعد على تفسير الصعوبات التي قد لا تُظهر الأرقام أسبابها."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح فكرة «اختبار A/B» وكيف يساهم في مقارنة خيارين للتحقق من أيهما يؤدي إلى نتائج أفضل للموقع.","a":"اختبار A/B أسلوب من التقييم الكمي يقارن خيارين أو نسختين من التصميم لمعرفة أيهما يحقق نتائج أفضل بالاعتماد على القياس. تُستخدم النتائج المقاسة لكل خيار للمقارنة، بدل الحكم وفق الانطباع الشخصي فقط."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بالتفصيل المقصود بـ«معدل الارتداد (Bounce Rate)» ولماذا يُعد مؤشرًا يحتاج إلى تفسير وفق تعريف أداة التحليل المستخدمة.","a":"معدل الارتداد (Bounce Rate) مؤشر يمكن أن يساعد مع مؤشرات أخرى على ملاحظة ضعف التفاعل، لكنه لا يفسر السبب وحده. تختلف طريقة تعريفه وحسابه باختلاف أداة التحليل وإعداداتها؛ ومن صوره التعليمية المبسطة نسبة الجلسات التي تنتهي بعد مشاهدة صفحة واحدة. ولهذا لا يصح افتراض تعريف أو طريقة حساب واحدة ثابتة لجميع أدوات التحليل، أو استنتاج سبب مغادرة الزائر من قيمته وحدها."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش الأهمية القصوى للجمع بين بيانات «الكم» و«لماذا» النوعية من خلال مثال عملي على تقييم متجر إلكتروني.","a":"في متجر إلكتروني قد تُظهر تحليلات الويب ارتفاع مشاهدات الصفحة (PV) وانخفاض معدل التحويل (CVR)، ما يشير إلى أن كثيرًا من المستخدمين يصلون ولا ينجزون الإجراء المستهدف. ثم يُجرى اختبار قابلية استخدام أو مقابلات لمعرفة الصعوبة التي تواجههم. القياس الكمي يوضح مقدار السلوك والنتائج بالأرقام، لكنه لا يشرح السبب وحده. أما التقييم النوعي فيكشف أسباب الصعوبات وآراء المستخدمين، لكنه لا يمثل جميع المستخدمين بالضرورة. لذلك يُفيد الجمع بين النوعين في تفسير المشكلة وتوجيه التحسين."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الأدوات التالية تُستخدم للاستماع إلى آراء المستخدمين المباشرة لفهم احتياجاتهم واستيائهم؟","a":"المقابلات.","mcq":{"stem":"أي من الأدوات التالية تُستخدم للاستماع إلى آراء المستخدمين المباشرة لفهم احتياجاتهم واستيائهم؟","opts":["المقابلات.","تحليلات الويب.","اختبار A/B.","معدل الارتداد."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو المنهج أو النهج الذي يقيس السلوك والنتائج باستخدام بيانات عددية ومقاييس محددة بوضوح؟","a":"التقييم الكمي.","mcq":{"stem":"ما هو المنهج أو النهج الذي يقيس السلوك والنتائج باستخدام بيانات عددية ومقاييس محددة بوضوح؟","opts":["التقييم النوعي.","التقييم الكمي.","التقييم الإرشادي.","اختبار قابلية الاستخدام."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هي الأدوات أو المنصات التي تجمع وتقيس وتحلل بيانات استخدام الموقع لفهم الوصول والتفاعل؟","a":"تحليلات الويب.","mcq":{"stem":"ما هي الأدوات أو المنصات التي تجمع وتقيس وتحلل بيانات استخدام الموقع لفهم الوصول والتفاعل؟","opts":["تحليلات الويب.","اختبار قابلية الاستخدام.","المقابلات المباشرة.","التقييم الإرشادي."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من القواعد الإرشادية التالية تعني التأكد من أن التصميم يقلل من احتمالية ارتكاب الأخطاء؟","a":"منع الأخطاء.","mcq":{"stem":"أي من القواعد الإرشادية التالية تعني التأكد من أن التصميم يقلل من احتمالية ارتكاب الأخطاء؟","opts":["الاتساق.","وضوح حالة النظام.","منع الأخطاء.","معدل التحويل."],"correct":2}}],"4-4":[{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"اشرح لماذا يُعد تحسين الموقع الإلكتروني عملية متكررة بدلًا من مهمة تُنجز مرة واحدة، وما دور دورة PDCA في تنظيم هذا التحسين.","a":"الموقع لا يكون بالضرورة مثاليًا من أول مرة؛ فملاحظات المستخدمين وبيانات الاستخدام تكشف ما يعمل وما يحتاج إلى تحسين. لذلك تُجرى تغييرات وتُقاس نتائجها، ثم تُستخدم النتائج في تحسينات متكررة بدل الاكتفاء بالإصدار الأول. وتنظم دورة PDCA التحسين من خلال تكرار «خطط، نفذ، تحقق، تصرف»، بحيث يُقاس أثر التغيير وتُحدد الخطوة التالية بناءً على النتائج."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"مقالي","q":"وضح خطوات دورة التحسين المستمر (PDCA) واذكر وصفًا مبسطًا لكل خطوة من خطواتها الأربع.","a":"تتكون دورة PDCA من أربع خطوات تتكرر باستمرار: (١) خطط Plan: حدد هدفًا واضحًا وضع خطة للتغيير المناسب. (٢) نفذ Do: نفذ التغيير وفقًا للخطة. (٣) تحقق Check: قس النتائج وقارنها بخط الأساس والهدف. (٤) تصرف Act: اعتمد التغيير أو وسّعه إن نجح، وإلا راجع السبب وعدّل الخطة وحدد الخطوة التالية."},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هو المصطلح الذي يصف طريقة تدفع التحسين قدمًا باستمرار من خلال تكرار الخطوات الأربع (خطط، نفذ، تحقق، تصرف)؟","a":"دورة PDCA.","mcq":{"stem":"ما هو المصطلح الذي يصف طريقة تدفع التحسين قدمًا باستمرار من خلال تكرار الخطوات الأربع (خطط، نفذ، تحقق، تصرف)؟","opts":["التفكير التصميمي.","دورة PDCA.","اختبار A/B.","التحسين المستمر."],"correct":1}},{"period":"الفترة الأولى","kind":"المهام الأدائية","qtype":"موضوعي","q":"في خطوة «التخطيط (Plan)» ضمن دورة PDCA، ما الذي يجب على الفريق فعله؟","a":"تحديد هدف واضح ووضع خطة لتغيير مناسب.","mcq":{"stem":"في خطوة «التخطيط (Plan)» ضمن دورة PDCA، ما الذي يجب على الفريق فعله؟","opts":["تنفيذ التغييرات المباشرة على الموقع.","قياس النتائج ومقارنتها بخط الأساس.","تحديد هدف واضح ووضع خطة لتغيير مناسب.","اعتماد ما نجح وتعديل الخطة."],"correct":2}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر الفكرة الأساسية وراء استخدام دورة PDCA والتفكير التصميمي واختبار A/B في تطوير المنتجات الرقمية بدلًا من افتراض أن النسخة الأولى نهائية.","a":"الموقع لا يكون بالضرورة مثاليًا من أول مرة؛ فملاحظات المستخدمين وبيانات الاستخدام تكشف ما يعمل وما يحتاج إلى تحسين. لذلك تُجرى تغييرات وتُقاس نتائجها، ثم تُستخدم النتائج في تحسينات متكررة بدل الاكتفاء بالإصدار الأول. تدعم PDCA تحسينًا منظمًا قابلًا للقياس؛ ويساعد التفكير التصميمي على فهم احتياجات المستخدم وتجريب الحلول؛ ويقارن اختبار A/B خيارات التصميم ببيانات فعلية."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بمثال كيف يتم تطبيق خطوتي «التنفيذ (Do)» و«التحقق (Check)» في تحسين نسبة إكمال نموذج التسجيل في موقع إلكتروني.","a":"التنفيذ Do: يغير الفريق تصميم صفحة التسجيل وفق خطة التحسين. التحقق Check: يقيس نسبة إكمال التسجيل بعد التغيير، ثم يقارنها بنسبة ما قبل التغيير (مثل ٤٠٪) وبالهدف (مثل ٥٠٪) ليرى هل تحقق التحسن المطلوب."},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ماذا تعني خطوة «التصرف (Act)» في دورة PDCA إذا حقق التغيير الهدف المطلوب؟","a":"اعتماد التغيير أو توسيعه.","mcq":{"stem":"ماذا تعني خطوة «التصرف (Act)» في دورة PDCA إذا حقق التغيير الهدف المطلوب؟","opts":["تغيير الخطة كليًا وإلغاء الموقع.","اعتماد التغيير أو توسيعه.","البدء في مرحلة التعاطف من جديد.","قياس معدل الارتداد فقط دون تعديل."],"correct":1}},{"period":"الفترة الأولى","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يمثل الوصف الصحيح لمفهوم «التحسين المستمر»؟","a":"التحسن قليلًا في كل مرة عبر دورات متكررة.","mcq":{"stem":"أي من الخيارات التالية يمثل الوصف الصحيح لمفهوم «التحسين المستمر»؟","opts":["بناء الموقع مرة واحدة وبشكل مثالي دون تعديلات.","تغيير جميع عناصر الموقع دفعة واحدة.","التحسن قليلًا في كل مرة عبر دورات متكررة.","الاعتماد على آراء المطورين فقط دون المستخدمين."],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"عرّف «التفكير التصميمي» وبيّن كيف يساعد في فهم المشكلة وحل المشكلات من منظور المستخدم عبر مراحله المختلفة.","a":"التفكير التصميمي طريقة مرنة لفهم المشكلة من منظور المستخدم وتجربة الحلول وتحسينها. يتضمن النموذج التعليمي خمسة أنماط: التعاطف، التعريف، توليد الأفكار، النموذج الأولي، الاختبار؛ ويمكن العودة بين الأنماط بدل السير في اتجاه خطي صارم. فالتعاطف يُظهر احتياجات المستخدم، والتعريف يحدد المشكلة، ثم يجري توليد الأفكار وبناء نموذج أولي وتجربته، ويمكن مراجعة الخطوات بحسب نتائج الاختبار."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"مقالي","q":"اذكر المراحل الخمس لنموذج التفكير التصميمي واشرح باختصار المقصود بمرحلتي «التعاطف (Empathize)» و«التعريف (Define)».","a":"(١) التعاطف Empathize: التعرف إلى تجربة المستخدم واحتياجاته بالملاحظة والأسئلة والبحث المناسب. (٢) التعريف Define: توضيح المشكلة المطلوب حلها بناءً على معلومات التعاطف. (٣) توليد الأفكار Ideate: اقتراح أفكار كثيرة للحل. (٤) النموذج الأولي Prototype: إنشاء مسودة سريعة قابلة للاختبار بناءً على الأفكار. (٥) الاختبار Test: تجربة النموذج مع المستخدمين وجمع ملاحظاتهم ومراقبة ما يحدث."},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"ما هي مرحلة التفكير التصميمي التي تتضمن تعرف تجربة المستخدم واحتياجاته من خلال الملاحظة والأسئلة والبحث المناسب؟","a":"التعاطف (Empathize).","mcq":{"stem":"ما هي مرحلة التفكير التصميمي التي تتضمن تعرف تجربة المستخدم واحتياجاته من خلال الملاحظة والأسئلة والبحث المناسب؟","opts":["التعريف (Define).","توليد الأفكار (Ideate).","التعاطف (Empathize).","الاختبار (Test)."],"correct":2}},{"period":"الفترة الثانية","kind":"المهام الأدائية","qtype":"موضوعي","q":"أي من المراحل التالية في التفكير التصميمي تعني إنشاء مسودة سريعة أو نموذج أولي بسرعة بناءً على الأفكار المولدة؟","a":"النموذج الأولي (Prototype).","mcq":{"stem":"أي من المراحل التالية في التفكير التصميمي تعني إنشاء مسودة سريعة أو نموذج أولي بسرعة بناءً على الأفكار المولدة؟","opts":["النموذج الأولي (Prototype).","الاختبار (Test).","التعريف (Define).","التعاطف (Empathize)."],"correct":0}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يتيح «اختبار A/B» لمصممي المواقع الإلكترونية مقارنة نسختين ببيانات حقيقية وكيف يتم توزيع الزيارات بينهما.","a":"اختبار A/B تجربة منظمة تُقارن نسختين A وB وفق مقياس محدد مسبقًا، مع توزيع المستخدمين أو الزيارات عشوائيًا قدر الإمكان أو بتصميم تجربة مناسب، وجمع عينة كافية قبل الحكم. ويُحدَّد المقياس وخطة التحليل قبل بدء الاختبار. وبمقارنة النتائج وفق المقياس المُختار مسبقًا يتعرف الفريق أي النسختين حققت أداء أفضل."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر شرطين أساسيين وضحهما الدرس لضمان نجاح «اختبار A/B» عند محاولة عزل أثر تغيير واحد بعينه.","a":"الأول: جعل الفرق بين النسختين واضحًا ومحددًا في العنصر المراد اختبار أثره. الثاني: تحديد المقياس وخطة التحليل قبل الاختبار، وجمع عينة كافية قبل إصدار الحكم. إذا أردنا معرفة أثر عنصر واحد، فلا بد أن يكون الفرق بين النسختين واضحًا ومحددًا في هذا العنصر فقط. أما تغيير عدة عناصر معًا فيقيس أثر حزمة التغييرات ولا يكشف أثر كل عنصر منها بمفرده."},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو التعريف الدقيق لاختبار A/B؟","a":"تجربة تقارن نسختين A وB وفق مقياس محدد مسبقًا وتوزع الزيارات بينهما عشوائيًا.","mcq":{"stem":"ما هو التعريف الدقيق لاختبار A/B؟","opts":["تجربة تقارن نسختين A وB وفق مقياس محدد مسبقًا وتوزع الزيارات بينهما عشوائيًا.","طريقة لإنشاء مخطط أولي يوضح تخطيط صفحة الويب.","نهج حوسبي يستخدم خصائص ميكانيكا الكم لمعالجة المعلومات.","طريقة تفكير لتحليل البيانات العددية للموقع فقط."],"correct":0}},{"period":"الفترة الثانية","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"إذا أردت في اختبار A/B عزل أثر تغيير عنصر واحد (مثل لون زر الشراء)، فماذا يجب عليك فعله؟","a":"جعل الفرق بين النسختين واضحًا ومحددًا لهذا العنصر فقط.","mcq":{"stem":"إذا أردت في اختبار A/B عزل أثر تغيير عنصر واحد (مثل لون زر الشراء)، فماذا يجب عليك فعله؟","opts":["تغيير جميع عناصر الصفحة في نفس الوقت.","جعل الفرق بين النسختين واضحًا ومحددًا لهذا العنصر فقط.","الاعتماد على الحدس دون جمع بيانات كافية.","تجنب استخدام أي مقاييس عددية للقياس."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح بالتفصيل لماذا يُعد تحسين الموقع الإلكتروني عملية متكررة وليست مهمة تُنجز لمرة واحدة، موضحًا دور دورة PDCA.","a":"الموقع لا يكون بالضرورة مثاليًا من أول مرة؛ فملاحظات المستخدمين وبيانات الاستخدام تكشف ما يعمل وما يحتاج إلى تحسين. لذلك تُجرى تغييرات وتُقاس نتائجها، ثم تُستخدم النتائج في تحسينات متكررة بدل الاكتفاء بالإصدار الأول. تتكون دورة PDCA من أربع خطوات تتكرر باستمرار: (١) خطط Plan: حدد هدفًا واضحًا وضع خطة للتغيير المناسب. (٢) نفذ Do: نفذ التغيير وفقًا للخطة. (٣) تحقق Check: قس النتائج وقارنها بخط الأساس والهدف. (٤) تصرف Act: اعتمد التغيير أو وسّعه إن نجح، وإلا راجع السبب وعدّل الخطة وحدد الخطوة التالية."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"تحدث عن نموذج التفكير التصميمي مبينًا أنه طريقة مرنة من خمسة أنماط يمكن الرجوع بينها بدلًا من المسار الخطي الصارم.","a":"التفكير التصميمي طريقة مرنة لفهم المشكلة من منظور المستخدم وتجربة الحلول وتحسينها. يتضمن النموذج التعليمي خمسة أنماط: التعاطف، التعريف، توليد الأفكار، النموذج الأولي، الاختبار؛ ويمكن العودة بين الأنماط بدل السير في اتجاه خطي صارم. (١) التعاطف Empathize: التعرف إلى تجربة المستخدم واحتياجاته بالملاحظة والأسئلة والبحث المناسب. (٢) التعريف Define: توضيح المشكلة المطلوب حلها بناءً على معلومات التعاطف. (٣) توليد الأفكار Ideate: اقتراح أفكار كثيرة للحل. (٤) النموذج الأولي Prototype: إنشاء مسودة سريعة قابلة للاختبار بناءً على الأفكار. (٥) الاختبار Test: تجربة النموذج مع المستخدمين وجمع ملاحظاتهم ومراقبة ما يحدث. فقد تظهر ملاحظات الاختبار حاجةً إلى العودة للتعاطف أو تعريف المشكلة وتكرار المحاولة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يعمل «اختبار A/B» في مقارنة نسختين واذكر أهمية تحديد المقياس وخطة التحليل وعينة كافية.","a":"اختبار A/B تجربة منظمة تُقارن نسختين A وB وفق مقياس محدد مسبقًا، مع توزيع المستخدمين أو الزيارات عشوائيًا قدر الإمكان أو بتصميم تجربة مناسب، وجمع عينة كافية قبل الحكم. ويُحدَّد المقياس وخطة التحليل قبل بدء الاختبار. إذا أردنا معرفة أثر عنصر واحد، فلا بد أن يكون الفرق بين النسختين واضحًا ومحددًا في هذا العنصر فقط. أما تغيير عدة عناصر معًا فيقيس أثر حزمة التغييرات ولا يكشف أثر كل عنصر منها بمفرده. فتحديد المقياس والخطة مسبقًا يوضح أساس المقارنة، والعينة الكافية ضرورية قبل الحكم على النتائج."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"طبق دورة PDCA على مثال عملي لرفع نسبة إكمال نموذج التسجيل من 40% إلى 50% موضحًا الخطوات الأربع.","a":"خطط: حدد هدف رفع نسبة إكمال نموذج التسجيل من ٤٠٪ إلى ٥٠٪، وخطط لتعديل مناسب في تصميم الصفحة. نفذ: طبق التعديل على الصفحة وفق الخطة. تحقق: قس نسبة الإكمال بعد التغيير وقارنها بخط الأساس ٤٠٪ وبالهدف ٥٠٪. تصرف: إذا تحقق الهدف فاعتمد التعديل أو وسعه؛ وإلا راجع السبب وعدل الخطة وكرر الدورة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما مصطلح طريقة التحسين التي تكرر الخطوات الأربع خطط - نفذ - تحقق - تصرف؟","a":"دورة PDCA.","mcq":{"stem":"ما مصطلح طريقة التحسين التي تكرر الخطوات الأربع خطط - نفذ - تحقق - تصرف؟","opts":["التفكير التصميمي.","دورة PDCA.","اختبار A/B.","النموذج الأولي."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما مصطلح طريقة التفكير لاكتشاف المشكلات وتوليد الحلول من منظور المستخدم عبر خمس خطوات؟","a":"التفكير التصميمي.","mcq":{"stem":"ما مصطلح طريقة التفكير لاكتشاف المشكلات وتوليد الحلول من منظور المستخدم عبر خمس خطوات؟","opts":["دورة PDCA.","اختبار A/B.","التفكير التصميمي.","التحسين المستمر."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما مصطلح الطريقة التي يُعد فيها نمطان ويقارنان بالبيانات لمعرفة أيهما أكثر فعالية؟","a":"اختبار A/B.","mcq":{"stem":"ما مصطلح الطريقة التي يُعد فيها نمطان ويقارنان بالبيانات لمعرفة أيهما أكثر فعالية؟","opts":["دورة PDCA.","التفكير التصميمي.","اختبار A/B.","التعاطف."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يصف مرحلة «الاختبار (Test)» في التفكير التصميمي بأفضل شكل؟","a":"جعل المستخدمين يجربون النموذج الأولي وجمع ملاحظاتهم.","mcq":{"stem":"أي من الخيارات التالية يصف مرحلة «الاختبار (Test)» في التفكير التصميمي بأفضل شكل؟","opts":["فهم احتياجات المستخدم من خلال الملاحظة والأسئلة.","توضيح المشكلة المراد حلها بدقة.","توليد أفكار كثيرة لحل المشكلة.","جعل المستخدمين يجربون النموذج الأولي وجمع ملاحظاتهم."],"correct":3}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"وضح كيف تساهم ملاحظات المستخدمين وبيانات الاستخدام في معرفة ما يعمل وما يحتاج إلى تحسين في المواقع الإلكترونية.","a":"تساعد بيانات الاستخدام على التعرف إلى نتائج وأداء الموقع بعد الاستخدام الفعلي، وتكشف ملاحظات المستخدمين عن الصعوبات والاحتياجات. يستفيد الفريق من الدليلين في اختيار تغيير مناسب وقياس أثره ضمن دورات تحسين متكررة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح خطوات دورة PDCA بالتفصيل مع ذكر الوصف الخاص بكل خطوة (خطط، نفذ، تحقق، تصرف).","a":"تتكون دورة PDCA من أربع خطوات تتكرر باستمرار: (١) خطط Plan: حدد هدفًا واضحًا وضع خطة للتغيير المناسب. (٢) نفذ Do: نفذ التغيير وفقًا للخطة. (٣) تحقق Check: قس النتائج وقارنها بخط الأساس والهدف. (٤) تصرف Act: اعتمد التغيير أو وسّعه إن نجح، وإلا راجع السبب وعدّل الخطة وحدد الخطوة التالية."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر مراحل التفكير التصميمي الخمس واشرح باختصار مرحلتي «توليد الأفكار (Ideate)» و«النموذج الأولي (Prototype)».","a":"(١) التعاطف Empathize: التعرف إلى تجربة المستخدم واحتياجاته بالملاحظة والأسئلة والبحث المناسب. (٢) التعريف Define: توضيح المشكلة المطلوب حلها بناءً على معلومات التعاطف. (٣) توليد الأفكار Ideate: اقتراح أفكار كثيرة للحل. (٤) النموذج الأولي Prototype: إنشاء مسودة سريعة قابلة للاختبار بناءً على الأفكار. (٥) الاختبار Test: تجربة النموذج مع المستخدمين وجمع ملاحظاتهم ومراقبة ما يحدث. في توليد الأفكار يقترح الفريق حلولًا كثيرة، وفي النموذج الأولي يصنع بسرعة مسودة للحل يمكن اختبارها."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش أهمية أن يكون الفرق بين النسختين (A) و (B) واضحًا ومحددًا في اختبار A/B، ولماذا يؤدي تغيير عدة عناصر معًا إلى قياس أثر الحزمة بدلًا من العنصر المنفرد.","a":"إذا أردنا معرفة أثر عنصر واحد، فلا بد أن يكون الفرق بين النسختين واضحًا ومحددًا في هذا العنصر فقط. أما تغيير عدة عناصر معًا فيقيس أثر حزمة التغييرات ولا يكشف أثر كل عنصر منها بمفرده. ويجب تحديد مقياس المقارنة وخطة التحليل سلفًا وجمع عينة كافية."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"من الخيارات التالية، اختر ما يقابل خطوة «تحقق (Check)» في دورة PDCA:","a":"قس معدل الارتداد بعد التغيير وقارنه بخط الأساس.","mcq":{"stem":"من الخيارات التالية، اختر ما يقابل خطوة «تحقق (Check)» في دورة PDCA:","opts":["حدد هدف خفض معدل الارتداد بنسبة 10%.","غير تصميم الصفحة الرئيسية وفق الخطة.","قس معدل الارتداد بعد التغيير وقارنه بخط الأساس.","اعتمد التغيير أو وسع نطاقه."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"من الخيارات التالية، اختر ما لا يُعد طريقة مناسبة لإجراء اختبار A/B:","a":"تغيير عدة عناصر في الوقت نفسه عند الرغبة في عزل أثر عنصر واحد.","mcq":{"stem":"من الخيارات التالية، اختر ما لا يُعد طريقة مناسبة لإجراء اختبار A/B:","opts":["إعداد نمطين ومقارنتهما ببيانات حقيقية.","تغيير عدة عناصر في الوقت نفسه عند الرغبة في عزل أثر عنصر واحد.","اتخاذ القرارات فقط بعد جمع كمية كافية من البيانات.","عرض كل نمط على مستخدمين فعليين."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"ما هو الوصف الأنسب لمفهوم عملية تحسين المواقع الإلكترونية؟","a":"من المهم التحسن تدريجيًا من خلال تكرار التقييم والتحسين المستمر.","mcq":{"stem":"ما هو الوصف الأنسب لمفهوم عملية تحسين المواقع الإلكترونية؟","opts":["إذا بُني موقع إلكتروني في البداية، فلا حاجة لأي تحسين نهائيًا.","يكفي تحسين التصميم البصري للأناقة مرة واحدة فقط.","من المهم التحسن تدريجيًا من خلال تكرار التقييم والتحسين المستمر.","ينبغي أن تتم جميع التحسينات باختبار A/B وحده دون تخطيط."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"أي من الخيارات التالية يصف «التفكير التصميمي» بأفضل شكل؟","a":"طريقة تفكير تؤدي إلى اكتشاف المشكلات وتوليد الحلول من منظور المستخدم.","mcq":{"stem":"أي من الخيارات التالية يصف «التفكير التصميمي» بأفضل شكل؟","opts":["طريقة تستخدم بيانات عددية بحتة لتحليل استخدام الخوادم.","طريقة تفكير تؤدي إلى اكتشاف المشكلات وتوليد الحلول من منظور المستخدم.","طريقة يحدد فيها الخبراء مشكلات الواجهة استنادًا لقواعد تجريدية بحتة.","طريقة لإنشاء مخطط كود البرمجة بلغة جافا سكربت."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اشرح كيف يساعد التحسين التكراري فريق العمل على التعلم من النتائج بدلًا من افتراض أن النسخة الأولى ستكون مثالية.","a":"الموقع لا يكون بالضرورة مثاليًا من أول مرة؛ فملاحظات المستخدمين وبيانات الاستخدام تكشف ما يعمل وما يحتاج إلى تحسين. لذلك تُجرى تغييرات وتُقاس نتائجها، ثم تُستخدم النتائج في تحسينات متكررة بدل الاكتفاء بالإصدار الأول. إذا حقق التغيير هدفه في دورة PDCA يمكن اعتماده أو توسيعه، وإن لم يحققه يُراجع السبب وتُعدل الخطة، وبذلك تستفيد الجولات التالية من نتائج الجولات السابقة."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"ناقش كيف يسير التحسين في التفكير التصميمي ذهابًا وإيابًا (بين التعاطف والتعريف والاختبار) بدلًا من اتجاه واحد صارم.","a":"التفكير التصميمي طريقة مرنة لفهم المشكلة من منظور المستخدم وتجربة الحلول وتحسينها. يتضمن النموذج التعليمي خمسة أنماط: التعاطف، التعريف، توليد الأفكار، النموذج الأولي، الاختبار؛ ويمكن العودة بين الأنماط بدل السير في اتجاه خطي صارم. فعندما يجرب المستخدمون النموذج في مرحلة الاختبار قد يتضح أن المشكلة لم تُفهم جيدًا، فيرجع الفريق إلى التعاطف لفهم احتياجات المستخدم أو إلى التعريف لتوضيح المشكلة، ثم يجرب الحل مرة أخرى."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"بين كيف يتم تصميم اختبار A/B ناجح لموقع إلكتروني يعاني من انخفاض نسبة النقر على زر الشراء، مع تحديد المقياس وتوزيع الزيارات.","a":"يُنشأ إصداران للصفحة يختلفان في عنصر واضح ومحدد، مثل لون زر الشراء (A أحمر وB أزرق). يُحدد قبل التجربة مقياس «عدد النقرات على زر الشراء» وخطة تحليل النتائج، ثم تُوزع زيارات المستخدمين بين الإصدارين عشوائيًا قدر الإمكان أو بتصميم مناسب، وتُجمع عينة كافية قبل مقارنة النقرات والحكم على الخيار الأفضل. إذا أردنا معرفة أثر عنصر واحد، فلا بد أن يكون الفرق بين النسختين واضحًا ومحددًا في هذا العنصر فقط. أما تغيير عدة عناصر معًا فيقيس أثر حزمة التغييرات ولا يكشف أثر كل عنصر منها بمفرده."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"مقالي","q":"اذكر الفروق الأساسية بين دورة PDCA والتفكير التصميمي واختبار A/B من حيث الغرض وطريقة التنفيذ.","a":"دورة PDCA تنظم التحسين المستمر في حلقة «خطط، نفذ، تحقق، تصرف» اعتمادًا على قياس النتائج. التفكير التصميمي يساعد على فهم المشكلة من منظور المستخدم وتجربة حلول عبر أنماطه الخمسة المرنة. اختبار A/B يقارن نسختين بصورة منظمة وبمقياس محدد وبيانات حقيقية للمساعدة على تحديد الخيار الأفضل."},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"طريقة مرنة لفهم المشكلة من منظور المستخدم وتجربة حلول ثم تحسينها عبر خمسة أنماط تسمى:","a":"التفكير التصميمي.","mcq":{"stem":"طريقة مرنة لفهم المشكلة من منظور المستخدم وتجربة حلول ثم تحسينها عبر خمسة أنماط تسمى:","opts":["دورة PDCA.","التفكير التصميمي.","اختبار A/B.","التحسين المستمر."],"correct":1}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"مسودة سريعة قابلة للاختبار يتم إنشاؤها بناءً على الأفكار المولدة في التفكير التصميمي هي:","a":"النموذج الأولي (Prototype).","mcq":{"stem":"مسودة سريعة قابلة للاختبار يتم إنشاؤها بناءً على الأفكار المولدة في التفكير التصميمي هي:","opts":["النموذج الأولي (Prototype).","البت الكلاسيكي.","الحوسبة الطرفية.","دورة التحقق."],"correct":0}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"تجربة تقارن نسختين A وB وفق مقياس محدد مسبقًا لتحديد الخيار الأفضل تسمى:","a":"اختبار A/B.","mcq":{"stem":"تجربة تقارن نسختين A وB وفق مقياس محدد مسبقًا لتحديد الخيار الأفضل تسمى:","opts":["دورة PDCA.","التفكير التصميمي.","اختبار A/B.","خط الأساس."],"correct":2}},{"period":"التقييم الأسبوعي","kind":"الأداءات المنزلية","qtype":"موضوعي","q":"الحلقة أو الدورة التي تتألف من (خطط، نفذ، تحقق، تصرف) وتُستخدم على نطاق واسع في تحسين الأعمال وإدارة الجودة هي:","a":"دورة PDCA.","mcq":{"stem":"الحلقة أو الدورة التي تتألف من (خطط، نفذ، تحقق، تصرف) وتُستخدم على نطاق واسع في تحسين الأعمال وإدارة الجودة هي:","opts":["دورة PDCA.","اختبار A/B.","التفكير التصميمي.","نموذج التعاطف."],"correct":0}}]};
